// ---------- terrain with splat map
const SPLAT = {
  x0: HM.x0,
  z0: HM.z0,
  w: (HM.nx - 1) * HM.dx,
  h: (HM.nz - 1) * HM.dx,
  W: 2048,
  H: Math.round(2048 * ((HM.nz - 1) / (HM.nx - 1)))
};
function buildSplat() {
  const { c, x, sx, P, poly, AT } = buildSplatPart1();
  const { areaCol, order } = buildSplatPart2();
  const { m, y } = buildSplatPart3(order, AT, x, poly, areaCol, sx, P);
  y.fillStyle = '#000';
  y.fillRect(0, 0, SPLAT.W, SPLAT.H);
  const mpoly = (coords, fill) => {
    y.beginPath();
    for (let i = 0; i < coords.length; i += 2) {
      const p = P(coords[i], coords[i + 1]);
      i ? y.lineTo(p[0], p[1]) : y.moveTo(p[0], p[1]);
    }
    y.closePath();
    y.fillStyle = fill;
    y.fill();
  };
  y.lineJoin = 'round';
  for (const b of DATA.B) {
    y.lineWidth = 12 * sx;
    y.strokeStyle = '#999';
    mpoly(b[6], '#999');
    y.stroke();
  }
  for (const a of DATA.A) if (['residential', 'industrial'].includes(AT[a[0]])) mpoly(a[2], '#777');
  mpoly(HIST_CORE, '#fff');
  for (const a of DATA.A) if (['square', 'parking', 'playground'].includes(AT[a[0]])) mpoly(a[2], '#fff');
  for (const a of DATA.A)
    if (['park', 'garden', 'grass', 'pitch', 'forest', 'water', 'farmland', 'meadow', 'scrub', 'cemetery', 'orchard'].includes(AT[a[0]]))
      mpoly(a[2], '#000');
  SPLAT.mask = m;
  return c;
}
/** (v1.1.7, code quality) part of buildSplat: furrows */
function buildSplatPart3(order, AT, x, poly, areaCol, sx, P) {
  for (const k of order)
    for (const a of DATA.A)
      if (AT[a[0]] === k) {
        x.lineWidth = 1;
        poly(a[2], areaCol[k]);
        if (k === 'farmland') {
          // furrows
          x.save();
          poly(a[2]);
          x.clip();
          x.strokeStyle = 'rgba(90,70,45,.35)';
          x.lineWidth = 1.2;
          for (let i = -SPLAT.H; i < SPLAT.W; i += 5) {
            x.beginPath();
            x.moveTo(i, 0);
            x.lineTo(i + SPLAT.H * 0.6, SPLAT.H);
            x.stroke();
          }
          x.restore();
        }
        if (k === 'pitch') {
          x.lineWidth = 1;
          poly(a[2], null, 'rgba(255,255,255,.7)');
        }
      }
  // roads (for distance look)
  const RT = DATA.RT;
  for (const rd of DATA.R) {
    const t = RT[rd[0]];
    const c2 = rd[4];
    const w = rd[2];
    x.strokeStyle =
      t === 'pedestrian' || ((rd[3] >> 3) & 3) === 1
        ? '#8f8a80'
        : t === 'track' || t === 'path'
          ? '#9a8566'
          : t === 'footway' || t === 'steps'
            ? '#a8a298'
            : '#4a4a4c';
    x.lineWidth = Math.max(1, w * sx * (t === 'footway' ? 1 : 1.35));
    x.lineCap = 'round';
    x.beginPath();
    for (let i = 0; i < c2.length; i += 2) {
      const p = P(c2[i], c2[i + 1]);
      i ? x.lineTo(p[0], p[1]) : x.moveTo(p[0], p[1]);
    }
    x.stroke();
  }
  for (const b of DATA.B) {
    x.lineWidth = 1;
    poly(b[6], '#6d6960');
  }
  // paving mask (R channel): historic core, squares, urban halos
  const m = mkCanvas(SPLAT.W, SPLAT.H),
    y = m.getContext('2d');
  return { m, y };
}
/** (v1.1.7, code quality) part of buildSplat */
function buildSplatPart2() {
  const areaCol = {
    park: '#5f8a3e',
    garden: '#6c9146',
    grass: '#6f9a45',
    farmland: '#8b8a4e',
    meadow: '#7f9650',
    pitch: '#4f8a3a',
    forest: '#3f6230',
    scrub: '#6f7a45',
    water: '#4a7fa0',
    cemetery: '#86866a',
    playground: '#b49a74',
    parking: '#6b6b6b',
    residential: '#a09a8c',
    industrial: '#8f8c86',
    square: '#b8b2a6',
    sports: '#9c7b5b',
    orchard: '#6c8844'
  };
  const order = [
    'residential',
    'industrial',
    'farmland',
    'meadow',
    'orchard',
    'scrub',
    'forest',
    'grass',
    'park',
    'garden',
    'cemetery',
    'sports',
    'pitch',
    'playground',
    'parking',
    'square',
    'water'
  ];
  return { areaCol, order };
}
/** (v1.1.7, code quality) part of buildSplat: base: rural terrain with noise (greens/ochres of La Laguna) */
function buildSplatPart1() {
  const c = mkCanvas(SPLAT.W, SPLAT.H),
    x = c.getContext('2d');
  const sx = SPLAT.W / SPLAT.w,
    sz = SPLAT.H / SPLAT.h;
  const P = (px, pz) => [(px - SPLAT.x0) * sx, (pz - SPLAT.z0) * sz];
  // base: rural terrain with noise (greens/ochres of La Laguna)
  x.fillStyle = '#7c8452';
  x.fillRect(0, 0, SPLAT.W, SPLAT.H);
  const r = mulberry(99);
  for (let i = 0; i < 2600; i++) {
    x.fillStyle = pick(['rgba(110,120,70,.35)', 'rgba(150,130,85,.3)', 'rgba(95,110,60,.35)', 'rgba(160,145,100,.25)']);
    const R = 6 + r() * 40;
    x.beginPath();
    x.arc(r() * SPLAT.W, r() * SPLAT.H, R, 0, 7);
    x.fill();
  }
  const poly = (coords, fill, stroke) => {
    x.beginPath();
    for (let i = 0; i < coords.length; i += 2) {
      const p = P(coords[i], coords[i + 1]);
      i ? x.lineTo(p[0], p[1]) : x.moveTo(p[0], p[1]);
    }
    x.closePath();
    if (fill) {
      x.fillStyle = fill;
      x.fill();
    }
    if (stroke) {
      x.strokeStyle = stroke;
      x.stroke();
    }
  };
  // urban halo around buildings
  x.lineJoin = 'round';
  for (const b of DATA.B) {
    x.lineWidth = 16 * sx;
    poly(b[6], '#9d978a', '#9d978a');
  }
  const AT = DATA.AT;
  return { c, x, sx, P, poly, AT };
}
let SPLATCANVAS;
// tunnel cuttings: kept in a small float texture (mobile GPUs have few fragment uniforms)
