    H = Math.max(64, Math.round((512 * wid) / len));
  const { c, x, k, line, R, circ } = courtCanvasPart1(W, H, len);
  const m = 1.5; // margin
  const PL = len - 2 * m,
    PW = wid - 2 * m;
