const FINCA_COLS = ['#e8c9a0', '#e6b08f', '#dcc29a', '#eab7a0', '#e9d3b0'];
function fincaEspanaLook(cx, cz) {
  if (cx < 1840 || cx > 2080 || cz < 1180 || cz > 1285) return null;
  return { col: FINCA_COLS[Math.abs(Math.round(cx * 7 + cz * 3)) % FINCA_COLS.length], atlas: 2 };
}
function landmarkFor(name) {
  for (const L of LANDMARKS) if (L.re.test(name)) return L;
  return null;
}
function landmarkAt(cx, cz) {
  for (const L of LANDMARK_AT) if (Math.hypot(cx - L.x, cz - L.z) < L.r) return L.o;
  return fincaEspanaLook(cx, cz) || guajaraLook(cx, cz);
}
// Urbanización Guajara (v0.72, docs/referencias/tf13_geneto/): chalets with hipped red tile roofs and white or cream
// walls, on the north-west side of the TF-5 by Cam. San Bartolomé de Geneto (C. Roque Nublo, Tindaya, Timanfaya)
const GUAJARA_COLS = ['#f4efe4', '#efe3cf', '#f2e6d6', '#e9dcc6', '#f6f1e7'];
function guajaraLook(cx, cz) {
  if (cx < 160 || cx > 480 || cz < 1545 || cz > 1790) return null;
  if ((cx - 396) * 236 - (cz - 1536) * 211 > -400) return null; // only on the far side of the motorway
  return { col: GUAJARA_COLS[Math.abs(Math.round(cx * 5 + cz * 11)) % GUAJARA_COLS.length], hip: true, atlas: 8 };
}
const LMQ = [];
// edge of the footprint that faces the street (long and close to a road)
function frontEdge(pts) {
  let best = null,
    bs = -1e9;
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i],
      q = pts[(i + 1) % pts.length];
    const L = Math.hypot(q[0] - p[0], q[1] - p[1]);
    if (L < 4) continue;
    const nx = (q[1] - p[1]) / L,
      nz = -(q[0] - p[0]) / L;
    const mx = (p[0] + q[0]) / 2,
      mz = (p[1] + q[1]) / 2;
    const rd = ROADSEG.nearest(mx + nx * 3, mz + nz * 3);
    const d = rd ? rd.d : 40;
    const sc = Math.min(L, 30) - d * 1.6;
    if (sc > bs) {
      bs = sc;
      best = { p, q, L, nx, nz, mx, mz, ux: (q[0] - p[0]) / L, uz: (q[1] - p[1]) / L };
    }
  }
  return best;
}
const LMMAT = {
  tuff: new THREE.MeshStandardMaterial({ color: 0x8a4a36, roughness: 0.9 }),
  grey: new THREE.MeshStandardMaterial({ color: 0x8f8b84, roughness: 0.9 }),
  wood: new THREE.MeshStandardMaterial({ color: 0x4a2c17, roughness: 0.8 }),
  white: new THREE.MeshStandardMaterial({ color: 0xf2efe8, roughness: 0.85 }),
  door: new THREE.MeshStandardMaterial({ color: 0x3b2616, roughness: 0.7 })
};
function signPlate(text, w, h) {
  const c = mkCanvas(1024, Math.round((1024 * h) / w));
  const x = c.getContext('2d');
  x.fillStyle = '#efe8d6';
  x.fillRect(0, 0, c.width, c.height);
  let fs = c.height * 0.62;
  x.font = `600 ${fs}px Oswald, Georgia, serif`;
  while (x.measureText(text).width > c.width * 0.9) {
    fs -= 4;
    x.font = `600 ${fs}px Oswald, Georgia, serif`;
  }
  x.fillStyle = '#3a2a1c';
  x.textAlign = 'center';
  x.textBaseline = 'middle';
  x.fillText(text, c.width / 2, c.height / 2);
  return new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshStandardMaterial({ map: canvasTex(c, { repeat: false }), roughness: 0.6 }));
}
function buildLandmarkDeco() {
  for (const B of LMQ) {
    buildLandmarkDecoEach(B);
  }
}
/** (v1.1.7, code quality) the body of a loop of buildLandmarkDeco, split out of it */
function buildLandmarkDecoEach(B) {
  const { L, pts, top, bmin, cx, cz } = B;
  const E = frontEdge(pts);
  if (!E) return;
  const g = new THREE.Group();
  const gy = heightAt(E.mx, E.mz) - 0.2;
  const ang = Math.atan2(E.nx, E.nz);
  g.position.set(E.mx, gy, E.mz);
  g.rotation.y = ang;
  scene.add(g); // local: +z = out of the facade, x along it
  const H = top - gy;
  const box = (w, h, d, m, x, y, z) => addMesh(g, new THREE.BoxGeometry(w, h, d), m, x, y, z);
  for (const dk of L.deco || []) {
    const [kind, arg] = dk.split(':');
    if (kind === 'portal') {
      const m = arg === 'tuff' ? LMMAT.tuff : LMMAT.grey;
      const pw = 3.6,
        ph = Math.min(H * 0.62, 6.2);
      box(0.55, ph, 0.35, m, -pw / 2, ph / 2, 0.15);
      box(0.55, ph, 0.35, m, pw / 2, ph / 2, 0.15);
      box(pw + 1.1, 0.6, 0.45, m, 0, ph + 0.3, 0.18); // pilasters + entablature
      const tri = new THREE.Shape();
      tri.moveTo(-pw / 2 - 0.4, 0);
      tri.lineTo(pw / 2 + 0.4, 0);
      tri.lineTo(0, 1.1);
      tri.closePath();
      const tg = new THREE.ExtrudeGeometry(tri, { depth: 0.35, bevelEnabled: false });
      addMesh(g, tg, m, 0, ph + 0.6, 0);
      box(0.8, 0.8, 0.2, m, 0, ph + 1.05, 0.38); // coat of arms
      const door = new THREE.Mesh(new THREE.PlaneGeometry(pw - 0.55, ph - 0.2), LMMAT.door);
      door.position.set(0, (ph - 0.2) / 2, 0.06);
      g.add(door);
    }
    if (kind === 'pyramid') {
      // 'La Pirámide' (Campus de Guajara): stepped glass-and-concrete pyramid over the low base
      let a = 1e9,
        b = -1e9,
        c = 1e9,
        d = -1e9;
      for (const p of pts) {
        a = Math.min(a, p[0]);
        b = Math.max(b, p[0]);
        c = Math.min(c, p[1]);
        d = Math.max(d, p[1]);
      }
      const pg = new THREE.Group();
      pg.position.set(cx, top - 0.1, cz);
      scene.add(pg);
      let rIn = 1e9;
      for (let i = 0; i < pts.length; i++) {
        const p = pts[i],
          q = pts[(i + 1) % pts.length];
        const L2 = (q[0] - p[0]) ** 2 + (q[1] - p[1]) ** 2 || 1;
        const t = Math.max(0, Math.min(1, ((cx - p[0]) * (q[0] - p[0]) + (cz - p[1]) * (q[1] - p[1])) / L2));
        rIn = Math.min(rIn, Math.hypot(cx - p[0] - (q[0] - p[0]) * t, cz - p[1] - (q[1] - p[1]) * t));
      }
      const W0 = Math.max(14, Math.min(rIn * 2 * 0.95, Math.min(b - a, d - c) * 0.6));
      const steps = 6,
        sh = 3.4;
      const conc = new THREE.MeshStandardMaterial({ color: 0xd8d2c6, roughness: 0.85 }),
        gl = new THREE.MeshStandardMaterial({ color: 0x2f4656, roughness: 0.12, metalness: 0.55 });
      for (let k = 0; k < steps; k++) {
        const w = W0 * (1 - k / steps);
        const m1 = new THREE.Mesh(new THREE.BoxGeometry(w, sh * 0.62, w), gl);
        m1.position.y = k * sh + sh * 0.31;
        pg.add(m1);
        const m2 = new THREE.Mesh(new THREE.BoxGeometry(w + 0.6, sh * 0.38, w + 0.6), conc);
        m2.position.y = k * sh + sh * 0.81;
        pg.add(m2);
      }
      const cap = new THREE.Mesh(new THREE.ConeGeometry((W0 / steps) * 0.75, sh * 1.4, 4), gl);
      cap.rotation.y = Math.PI / 4;
      cap.position.y = steps * sh + sh * 0.7;
      pg.add(cap);
      pg.rotation.y = 0;
    }
    if (kind === 'pabellon') pabellonSantiagoMartin(pts, cx, cz, top);
    if (kind === 'ayto') buildAyuntamiento(pts);
    if (kind === 'huc') buildHUC(pts);
    if (kind === 'glass') buildGlassSkin(pts, top);
    if (kind === 'salud') saludDeco(g, E, H, arg);
    if (kind === 'cornice') box(E.L + 0.6, 0.45, 0.6, LMMAT.grey, 0, H - 0.2, 0.2);
    if (kind === 'balustrade') {
      box(E.L, 0.15, 0.4, LMMAT.white, 0, H + 0.95, 0.05);
      for (let x = -E.L / 2 + 0.3; x < E.L / 2; x += 0.45) addMesh(g, new THREE.CylinderGeometry(0.07, 0.1, 0.8, 6), LMMAT.white, x, H + 0.45, 0.05);
    }
    if (kind === 'pediment') {
      const tri = new THREE.Shape();
      const w = Math.min(E.L * 0.5, 12);
      tri.moveTo(-w / 2, 0);
      tri.lineTo(w / 2, 0);
      tri.lineTo(0, w * 0.22);
      tri.closePath();
      addMesh(g, new THREE.ExtrudeGeometry(tri, { depth: 0.5, bevelEnabled: false }), LMMAT.white, 0, H, -0.1);
      for (const x of [-w / 2, -w / 6, w / 6, w / 2]) box(0.5, H - 4.5, 0.3, LMMAT.white, x * 0.9, 4.5 + (H - 4.5) / 2, 0.12);
    }
    if (kind === 'sign') {
      const s = signPlate(arg, Math.min(E.L * 0.6, 9), 0.9);
      s.position.set(0, Math.min(H - 1.2, 4.6), 0.08);
      g.add(s);
    }
    if (kind === 'towers2')
      for (const sx of [-1, 1]) {
        const tw = 4.2,
          th = H + 3.2;
        const t = box(
          tw,
          th,
          tw,
          new THREE.MeshStandardMaterial({ color: new THREE.Color(L.col || '#bdb6aa'), roughness: 0.9 }),
          sx * (E.L / 2 - tw / 2),
          th / 2,
          -tw / 2 + 0.05
        );
        box(tw + 0.5, 0.4, tw + 0.5, LMMAT.grey, sx * (E.L / 2 - tw / 2), th, -tw / 2 + 0.05);
        const c = addMesh(g, new THREE.ConeGeometry(tw * 0.72, 1.6, 4), MAT.roofTile, sx * (E.L / 2 - tw / 2), th + 1.0, -tw / 2 + 0.05);
        c.rotation.y = Math.PI / 4;
      }
    if (kind === 'celosia') {
      // long carved wooden mirador on the upper wall
      const w = Math.min(E.L * 0.8, 24),
        h = 3.2,
        y = Math.max(3.5, H - h - 1.2);
      box(w, h, 1.0, LMMAT.wood, 0, y + h / 2, 0.5);
      box(w + 0.6, 0.3, 1.3, LMMAT.wood, 0, y + h + 0.15, 0.55);
      box(w + 0.3, 0.3, 1.2, LMMAT.wood, 0, y - 0.15, 0.5);
      const lat = new THREE.MeshStandardMaterial({ color: 0x5e3a1f, roughness: 0.75 });
      for (let x = -w / 2 + 0.25; x < w / 2; x += 0.32) box(0.06, h - 0.3, 0.06, lat, x, y + h / 2, 1.02);
      for (let yy = y + 0.3; yy < y + h; yy += 0.35) box(w, 0.05, 0.06, lat, 0, yy, 1.03);
      for (let x = -w / 2 + 1; x < w / 2; x += 2.2) {
        const b = box(0.15, 0.8, 0.15, LMMAT.wood, x, y - 0.55, 0.85);
        b.rotation.x = 0.6;
      }
    }
    if (kind === 'espadana') espadana(E.mx - E.ux * E.L * 0.3, E.mz - E.uz * E.L * 0.3, top - 0.3, Math.atan2(E.ux, E.uz) + Math.PI / 2, 3.6);
    if (kind === 'ruins') {
      // roofless church: rows of stone arches inside the shell
      const F = axisFrame(pts, cx, cz);
      const y0 = bmin - 0.3,
        len = F.u1 - F.u0,
        wid = F.v1 - F.v0;
      const st = new THREE.MeshStandardMaterial({ color: 0xa79f90, roughness: 0.95 });
      for (const vv of [F.v0 + wid / 3, F.v1 - wid / 3])
        for (let u = F.u0 + 3; u < F.u1 - 2; u += 4.2) {
          const p = F.W(u, vv);
          const c = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.55, 7.5, 10), st);
          c.position.set(p[0], y0 + 3.75, p[1]);
          c.castShadow = true;
          scene.add(c);
          COL.addCirc(p[0], p[1], 0.5);
          if (u + 4.2 < F.u1 - 2) {
            const q = F.W(u + 2.1, vv);
            const a = new THREE.Mesh(new THREE.TorusGeometry(2.1, 0.35, 6, 12, Math.PI), st);
            a.position.set(q[0], y0 + 7.5, q[1]);
            a.rotation.y = F.ang - Math.PI / 2;
            scene.add(a);
          }
        }
      // inner faces of the walls (the shell is open to the sky) + rubble floor
      const A = acc(cx, cz, 'facade');
      for (let i = 0; i < pts.length; i++) {
        const p = pts[i],
          q = pts[(i + 1) % pts.length];
        const l = Math.hypot(q[0] - p[0], q[1] - p[1]);
        if (l < 0.1) continue;
        const nb = Math.max(1, Math.round(l / 3));
        A.quad(
          [q[0], y0, q[1]],
          [p[0], y0, p[1]],
          [p[0], top, p[1]],
          [q[0], top, q[1]],
          [0, 0],
          [nb, 0],
          [nb, (top - y0) / 3],
          [0, (top - y0) / 3],
          [0.85, 0.82, 0.76],
          [5, 7],
          [-(q[1] - p[1]) / l, 0, (q[0] - p[0]) / l]
        );
      }
    }
  }
  if (L.label) LABELS.push([L.label, cx, cz, 1]);
}

/** v1.2.0: the Pabellón de Deportes Santiago Martín (fotos de Jonay): a drum of grey vertical slats with a very low white
 *  dome, on the stone base; a blue block with windows on one side, a big banner (parody) and the steel portal frame that
 *  runs around it */
function pabellonSantiagoMartin(pts, cx, cz, top) {
  let rIn = 1e9;
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i],
      q = pts[(i + 1) % pts.length],
      L2 = (q[0] - p[0]) ** 2 + (q[1] - p[1]) ** 2 || 1,
      t = Math.max(0, Math.min(1, ((cx - p[0]) * (q[0] - p[0]) + (cz - p[1]) * (q[1] - p[1])) / L2));
    rIn = Math.min(rIn, Math.hypot(cx - p[0] - (q[0] - p[0]) * t, cz - p[1] - (q[1] - p[1]) * t));
  }
  const R = Math.max(14, Math.min(30, rIn * 0.92)),
    Hd = 12,
    g = new THREE.Group();
  g.position.set(cx, top - 0.05, cz);
  scene.add(g);
  // the slats: a canvas of light and dark grey stripes wrapped round the drum
  const c = mkCanvas(1024, 128),
    x = c.getContext('2d');
  for (let i = 0; i < 128; i++) {
    x.fillStyle = i % 2 ? '#aeb3b5' : '#c9cdcf';
    x.fillRect(i * 8, 0, 8, 128);
  }
  x.fillStyle = 'rgba(40,45,50,0.35)';
  x.fillRect(0, 100, 1024, 28); // the dark band of glass at the foot
  const tex = canvasTex(c, { repeat: true });
  tex.repeat.set(3, 1);
  const drum = new THREE.Mesh(
    new THREE.CylinderGeometry(R, R, Hd, 64, 1, true),
    new THREE.MeshStandardMaterial({ map: tex, roughness: 0.6, side: THREE.DoubleSide })
  );
  drum.position.y = Hd / 2;
  g.add(drum);
  // the dome: a very flat white cap
  const capH = R * 0.18,
    sr = (R * R + capH * capH) / (2 * capH),
    dome = new THREE.Mesh(
      new THREE.SphereGeometry(sr, 64, 12, 0, Math.PI * 2, 0, Math.asin(R / sr)),
      new THREE.MeshStandardMaterial({ color: 0xf1f1ec, roughness: 0.75 })
    );
  dome.position.y = Hd - (sr - capH);
  g.add(dome);
  const rim = new THREE.Mesh(new THREE.TorusGeometry(R, 0.35, 6, 64), new THREE.MeshStandardMaterial({ color: 0x9da2a4, roughness: 0.6 }));
  rim.rotation.x = Math.PI / 2;
  rim.position.y = Hd;
  g.add(rim);
  // the dark vertical strip on the drum (the stair tower) and the banner (parody of the real ads)
  const strip = new THREE.Mesh(new THREE.BoxGeometry(2.2, Hd + 1.5, 1.2), new THREE.MeshStandardMaterial({ color: 0x3b3a38, roughness: 0.8 }));
  strip.position.set(Math.sin(0.4) * R, (Hd + 1.5) / 2, Math.cos(0.4) * R);
  strip.rotation.y = 0.4;
  g.add(strip);
  const bc = mkCanvas(1024, 384),
    bx = bc.getContext('2d');
  bx.fillStyle = '#1f3f8f';
  bx.fillRect(0, 0, 1024, 384);
  bx.fillStyle = '#ffffff';
  bx.font = '800 150px Oswald, Impact, sans-serif';
  bx.textAlign = 'center';
  bx.textBaseline = 'middle';
  bx.fillText('¡HOLA, AGUERE!', 512, 150);
  bx.font = '600 60px Oswald, sans-serif';
  bx.fillText('LANOVO · TENERIFE CON TODO', 512, 300);
  const banA = 0.9,
    banW = R * 0.7,
    banner = new THREE.Mesh(
      new THREE.PlaneGeometry(banW, Hd * 0.45),
      new THREE.MeshStandardMaterial({ map: canvasTex(bc, { repeat: false }), roughness: 0.6 })
    );
  banner.position.set(Math.sin(banA) * (R + 0.15), Hd * 0.55, Math.cos(banA) * (R + 0.15));
  banner.rotation.y = banA;
  g.add(banner);
  // the blue block with windows on one side
  const blue = new THREE.Mesh(new THREE.BoxGeometry(R * 0.7, 7, 8), new THREE.MeshStandardMaterial({ color: 0x2f5fb3, roughness: 0.5 }));
  blue.position.set(Math.sin(-0.6) * (R + 2), 3.5 - 0.05, Math.cos(-0.6) * (R + 2));
  blue.rotation.y = -0.6;
  g.add(blue);
  // the steel portal frame around it: posts and a ring beam
  const steel = new THREE.MeshStandardMaterial({ color: 0x6a6660, roughness: 0.55, metalness: 0.4 }),
    Rp = R + 6,
    n = 28;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2,
      post = new THREE.Mesh(new THREE.BoxGeometry(0.35, 9, 0.35), steel);
    post.position.set(Math.sin(a) * Rp, 4.5, Math.cos(a) * Rp);
    g.add(post);
  }
  const beam = new THREE.Mesh(new THREE.TorusGeometry(Rp, 0.22, 4, 64), steel);
  beam.rotation.x = Math.PI / 2;
  beam.position.y = 9;
  g.add(beam);
  // the name, on the base facing the motorway (the real name: a public sports hall)
  const sign = signPlate('PABELLÓN DE DEPORTES DE TENERIFE SANTIAGO MARTÍN', 26, 1.6);
  sign.position.set(Math.sin(-2.4) * (Rp + 0.4), 2.2, Math.cos(-2.4) * (Rp + 0.4));
  sign.rotation.y = -2.4;
  g.add(sign);
}

// ---------- tram stops: side platforms with shelters, benches and an info totem (replaces the OSM "building" footprints)
const TRAMSTOP_NAMES = new Set(DATA.P.filter((p) => p[1] === 'tram_stop').map((p) => p[0]));
function isTramStopBuilding(nameIdx, pts) {
  if (!TRAMSTOP_NAMES.has(nameIdx)) return false;
  const T = DATA.T;
  for (const [x, z] of pts)
    for (let i = 0; i < T.length - 2; i += 2) {
      const dx = T[i + 2] - T[i],
        dz = T[i + 3] - T[i + 1],
        L2 = dx * dx + dz * dz || 1;
      const t = clamp(((x - T[i]) * dx + (z - T[i + 1]) * dz) / L2, 0, 1);
      if (Math.hypot(x - T[i] - dx * t, z - T[i + 1] - dz * t) < 8) return true;
    }
  return false;
}
function tramNearest(x, z) {
  const T = DATA.T;
  let best = null,
    bd = 1e9;
  for (let i = 0; i < T.length - 2; i += 2) {
    const dx = T[i + 2] - T[i],
      dz = T[i + 3] - T[i + 1],
      L2 = dx * dx + dz * dz || 1;
    const t = clamp(((x - T[i]) * dx + (z - T[i + 1]) * dz) / L2, 0, 1);
    const px = T[i] + dx * t,
      pz = T[i + 1] + dz * t,
      d = Math.hypot(x - px, z - pz);
    if (d < bd) {
      const L = Math.sqrt(L2);
      bd = d;
      best = { x: px, z: pz, dx: dx / L, dz: dz / L, d };
    }
  }
  return best;
}
function stopSignTex(name) {
  const c = mkCanvas(256, 512),
    x = c.getContext('2d');
  x.fillStyle = '#f4f4f2';
  x.fillRect(0, 0, 256, 512);
  x.fillStyle = '#2f8a3c';
  x.fillRect(0, 0, 256, 150);
  x.fillStyle = '#fff';
  x.beginPath();
  x.arc(128, 75, 52, 0, 7);
  x.fill();
  x.fillStyle = '#2f8a3c';
  x.font = '900 70px Oswald, sans-serif';
  x.textAlign = 'center';
  x.textBaseline = 'middle';
  x.fillText('T', 128, 78);
  x.fillStyle = '#1d1d1d';
  x.font = '700 30px Oswald, sans-serif';
  x.fillText('TRANVÍA', 128, 190);
  // stop name, wrapped
  x.font = '600 34px Barlow, sans-serif';
  const words = (name || 'Parada').toUpperCase().split(' ');
  const lines = [];
  let cur = '';
  for (const w of words) {
    const t = cur ? cur + ' ' + w : w;
    if (x.measureText(t).width > 230 && cur) {
      lines.push(cur);
      cur = w;
    } else cur = t;
  }
  if (cur) lines.push(cur);
  lines.slice(0, 4).forEach((l, i) => x.fillText(l, 128, 260 + i * 42));
  x.fillStyle = '#2f8a3c';
  x.fillRect(0, 470, 256, 42);
  x.fillStyle = '#fff';
  x.font = '600 20px Barlow, sans-serif';
  x.fillText('Próximo: 4 min', 128, 492);
  return canvasTex(c, { repeat: false });
}
function buildTramStops() {
  if (DATA.T.length < 6) return 0;
  // group POIs by name -> one stop per name
  const by = new Map();
  for (const p of DATA.P)
    if (p[1] === 'tram_stop') {
      let a = by.get(p[0]);
      if (!a) by.set(p[0], (a = []));
      a.push(p);
    }
  const mPlat = M(0xb9b6ae, 0.85),
    mEdge = M(0xe3be1e, 0.7),
    mKerb = M(0x8d8a84, 0.9),
    mSteel = M(0x5c6166, 0.45, 0.6),
    mRoof = M(0xf0f0ee, 0.6),
    mGreen = M(0x2f8a3c, 0.6),
    mWood = M(0x8a5a3a, 0.8);
  const { mGlass, box } = buildTramStopsPart1();
  let n = 0;
  for (const [nameIdx, list] of by) {
    const cx = list.reduce((s, p) => s + p[2], 0) / list.length,
      cz = list.reduce((s, p) => s + p[3], 0) / list.length;
    const t = tramNearest(cx, cz);
    if (!t || t.d > 30) continue;
    const name = nameIdx >= 0 ? STR[nameIdx] : null;
    const sign = new THREE.MeshStandardMaterial({ map: stopSignTex(name), roughness: 0.5, emissive: 0xffffff, emissiveIntensity: 0.08 });
    const h = Math.atan2(t.dx, t.dz);
    for (const sg of [-1, 1]) {
      const K = 0.8;
      /* platforms at 80 % of the real size so they fit between the tracks and the streets (Jonay) */ const off = 3.6 + (2.3 * K) / 2;
      const px = t.x - t.dz * off * sg,
        pz = t.z + t.dx * off * sg;
      const g = new THREE.Group();
      g.position.set(px, Math.max(heightAt(px, pz), heightAt(t.x, t.z)), pz);
      g.rotation.y = h + (sg > 0 ? Math.PI : 0);
      g.scale.set(K, 1, K);
      // local frame: z along the track, -x towards the rails... (after the flip both sides face the track at -x)
      const W = 2.3;
      const ry = g.rotation.y,
        cr = Math.cos(ry),
        sr = Math.sin(ry);
      // platform length: as long as it fits (30 m) without its ramps or its outer edge reaching a carriageway (agent: platform in Av. Menceyes)
      const clear = (Lt) => {
        for (let lz = -Lt / 2 - 2.8; lz <= Lt / 2 + 2.8; lz += 1.5)
          for (const lx of [-W / 2, 0, W / 2]) {
            const wx = px + (lx * cr + lz * sr) * K,
              wz = pz + (-lx * sr + lz * cr) * K;
            if (onCarriageway(wx, wz, -0.6)) return false;
          }
        return true;
      };
      const L = [30, 24, 18, 14].find(clear) || 30;
      if (!clear(L)) console.log('tram stop platform still on a carriageway', Math.round(px), Math.round(pz));
      else if (L < 30) console.log('tram stop platform shortened', L * K, Math.round(px), Math.round(pz)); // a platform whose centre is already on a road (the OSM road is drawn over the tram median) keeps its length
      box(g, mPlat, W, 0.32, L, 0, 0.16, 0);
      box(g, mKerb, 0.12, 0.34, L, -W / 2 + 0.06, 0.17, 0);
      box(g, mEdge, 0.45, 0.012, L, -W / 2 + 0.38, 0.326, 0);
      // ramps at both ends
      for (const e of [-1, 1]) {
        const r = new THREE.Mesh(new THREE.BoxGeometry(W, 0.06, 3), mPlat);
        r.position.set(0, 0.14, e * (L / 2 + 1.4));
        r.rotation.x = e * 0.1;
        r.receiveShadow = true;
        g.add(r);
      }
      // shelter (outer half of the platform)
      const SL = 9,
        sx = 0.2;
      for (const zz of [-SL / 2 + 0.2, 0, SL / 2 - 0.2]) {
        box(g, mSteel, 0.1, 2.6, 0.1, sx + 0.7, 1.62, zz);
      }
      box(g, mRoof, 2.0, 0.12, SL + 0.6, sx + 0.1, 2.95, 0);
      box(g, mGreen, 0.06, 0.22, SL + 0.6, sx - 0.92, 2.86, 0);
      box(g, mGreen, 2.0, 0.22, 0.06, sx + 0.1, 2.86, SL / 2 + 0.3);
      box(g, mGreen, 2.0, 0.22, 0.06, sx + 0.1, 2.86, -SL / 2 - 0.3);
      const gl = box(g, mGlass, 0.03, 2.1, SL - 0.4, sx + 0.72, 1.45, 0);
      gl.castShadow = false;
      for (const e of [-1, 1]) {
        const ge = box(g, mGlass, 1.3, 2.1, 0.03, sx + 0.1, 1.45, e * (SL / 2 - 0.15));
        ge.castShadow = false;
      }
      // bench
      box(g, mWood, 0.42, 0.06, 3.2, sx + 0.38, 0.78, -1.5);
      box(g, mWood, 0.05, 0.4, 3.2, sx + 0.6, 1.05, -1.5);
      for (const zz of [-2.9, -0.1]) box(g, mSteel, 0.36, 0.45, 0.06, sx + 0.38, 0.53, zz);
      // ticket machine + info totem
      const mach = [
        box(g, mGreen, 0.55, 1.5, 0.5, sx + 0.5, 1.07, SL / 2 + 1.4),
        box(g, M(0x1a2228, 0.3), 0.02, 0.35, 0.3, sx + 0.22, 1.35, SL / 2 + 1.4)
      ];
      const tot = box(g, M(0x3a3f44, 0.5, 0.4), 0.16, 2.4, 0.5, sx + 0.3, 1.52, -SL / 2 - 1.6);
      const panel = new THREE.Mesh(new THREE.PlaneGeometry(0.62, 1.24), sign);
      panel.position.set(sx + 0.3 - 0.09, 1.95, -SL / 2 - 1.6);
      panel.rotation.y = -Math.PI / 2;
      g.add(panel);
      const panel2 = panel.clone();
      panel2.position.x = sx + 0.3 + 0.09;
      panel2.rotation.y = Math.PI / 2;
      g.add(panel2);
      const totem = [tot, panel, panel2];
      // waste bin
      box(g, M(0x2b5a33, 0.6), 0.4, 0.75, 0.4, sx + 0.8, 0.7, SL / 2 + 0.4);
      scene.add(g);
      g.updateMatrixWorld(true);
      // collisions: posts, glass back wall, totem and machine
      const W2 = (lx, lz) => {
        const v = new THREE.Vector3(lx, 0, lz).applyMatrix4(g.matrixWorld);
        return [v.x, v.z];
      };
      const a = W2(sx + 0.72, -SL / 2),
        b = W2(sx + 0.72, SL / 2);
      COL.addSeg(a[0], a[1], b[0], b[1]);
      for (const [lx, lz, r, ms] of [
        [sx + 0.5, SL / 2 + 1.4, 0.4, mach],
        [sx + 0.3, -SL / 2 - 1.6, 0.3, totem]
      ]) {
        const p = W2(lx, lz);
        if (onCarriageway(p[0], p[1], r)) {
          for (const m of ms) if (m.parent) m.parent.remove(m);
          continue;
        }
        COL.addCirc(p[0], p[1], r);
      } // v0.69 (auditor): a platform end on the carriageway: no machine / totem there
      n++;
    }
  }
  return n;
}
/** (v1.1.7, code quality) part of buildTramStops */
function buildTramStopsPart1() {
  const mGlass = new THREE.MeshStandardMaterial({
    color: 0xcfe6ee,
    roughness: 0.05,
    metalness: 0.1,
    transparent: true,
    opacity: 0.28,
    depthWrite: false
  });
  const box = (g, mat, w, h, d, x, y, z) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    m.position.set(x, y, z);
    m.castShadow = h > 0.2;
    m.receiveShadow = true;
    g.add(m);
    return m;
  };
  return { mGlass, box };
}

// ============ underground car parks: Plaza del Cristo (under the big plaza, next to the market) and Avenida de La Trinidad ============
// Each one: a hall (floor, ceiling, columns, bays, lights, parked cars) at about -4 m, vehicle ramps that you can drive
// down from the street (open cutting + short covered mouth), and pedestrian stairwells with glass pavilions on the surface.
const UGC = []; // underground obstacles [x, z, r] (columns, parked cars): only apply below ground
function ugcPush(x, z, r, y) {
  for (const c of UGC) {
    if (y !== undefined && c[3] !== undefined && Math.abs(y - c[3]) > 0.6) continue;
    /* only at the hall floor (not on the stairs above) */ const dx = x - c[0],
      dz = z - c[1];
    if (Math.abs(dx) > 4 || Math.abs(dz) > 4) continue;
    const d = Math.hypot(dx, dz),
      m = c[2] + r;
    if (d < m && d > 1e-4) {
      x = c[0] + (dx / d) * m;
      z = c[1] + (dz / d) * m;
    }
  }
  return [x, z];
}
function inCut(x, z, m = 1.5) {
  for (const c of TCUTS) {
    const dx = c[2] - c[0],
      dz = c[3] - c[1],
      L2 = dx * dx + dz * dz || 1;
    const t = clamp(((x - c[0]) * dx + (z - c[1]) * dz) / L2, -0.15, 1.15);
    if (Math.hypot(x - c[0] - dx * t, z - c[1] - dz * t) < c[4] + m) return true;
  }
  return false;
}
const CARPARK_SRC = {};
const CARPARKS = [];
// before the terrain splat is painted: the car park polygon of the Plaza del Cristo is really a big paved square on top
function prepUndergroundAreas() {
  const sq = DATA.AT.indexOf('square');
  for (const a of DATA.A)
    if (a[1] >= 0 && /Parking del Cristo/.test(STR[a[1]])) {
      CARPARK_SRC.cristo = a[2].slice();
      if (sq >= 0) a[0] = sq;
    }
}
function pcaFrame(c) {
  let cx = 0,
    cz = 0;
  const n = c.length / 2;
  for (let i = 0; i < c.length; i += 2) {
    cx += c[i];
    cz += c[i + 1];
  }
  cx /= n;
  cz /= n;
  let a = 0,
    b = 0,
    d = 0;
  for (let i = 0; i < c.length; i += 2) {
    const x = c[i] - cx,
      z = c[i + 1] - cz;
    a += x * x;
    b += x * z;
    d += z * z;
  }
  const ang = 0.5 * Math.atan2(2 * b, a - d);
  const ux = Math.cos(ang),
    uz = Math.sin(ang);
  let u0 = 1e9,
    u1 = -1e9,
    v0 = 1e9,
    v1 = -1e9;
  for (let i = 0; i < c.length; i += 2) {
    const x = c[i] - cx,
      z = c[i + 1] - cz;
    const u = x * ux + z * uz,
      v = -x * uz + z * ux;
    u0 = Math.min(u0, u);
    u1 = Math.max(u1, u);
    v0 = Math.min(v0, v);
    v1 = Math.max(v1, v);
  }
  return { cx, cz, ux, uz, u0, u1, v0, v1, W: (u, v) => [cx + ux * u - uz * v, cz + uz * u + ux * v] };
}
const PK = {};
function pkMats() {
  if (PK.ok) return PK;
  PK.ok = true;
  const c = mkCanvas(256, 256),
    x = c.getContext('2d');
  x.fillStyle = '#5d6063';
  x.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 1400; i++) {
    x.fillStyle = `rgba(${Math.random() < 0.5 ? 255 : 0},${Math.random() < 0.5 ? 255 : 0},255,0.04)`;
    x.fillRect(Math.random() * 256, Math.random() * 256, 2, 2);
  }
  const t = canvasTex(c);
  t.repeat.set(1, 1);
  PK.floor = new THREE.MeshStandardMaterial({ map: t, roughness: 0.85, emissive: 0x2a2c2e, emissiveIntensity: 1 });
  PK.ceil = new THREE.MeshStandardMaterial({ color: 0xb9b7b0, roughness: 0.95, emissive: 0x3b3a37, side: THREE.DoubleSide });
  PK.wall = new THREE.MeshStandardMaterial({ color: 0xd8d5cc, roughness: 0.9, emissive: 0x3a3936, side: THREE.DoubleSide });
  PK.col = new THREE.MeshStandardMaterial({ color: 0xe8e4da, roughness: 0.8, emissive: 0x403f3b });
  PK.stripe = new THREE.MeshStandardMaterial({ color: 0xf2c12e, roughness: 0.6, emissive: 0x3a2e08 });
  PK.line = new THREE.MeshBasicMaterial({ color: 0xf2f2f2 });
  PK.light = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xf4f8ff, emissiveIntensity: 1.6 });
  PK.green = new THREE.MeshStandardMaterial({ color: 0x1f8a3c, emissive: 0x1f8a3c, emissiveIntensity: 0.9 });
  PK.blue = new THREE.MeshStandardMaterial({ color: 0x1d4f9c, roughness: 0.5, emissive: 0x0d2550, emissiveIntensity: 0.5 });
  PK.glass = new THREE.MeshStandardMaterial({
    color: 0xbfdbe6,
    roughness: 0.05,
    metalness: 0.2,
    transparent: true,
    opacity: 0.35,
    depthWrite: false
  });
  PK.steel = new THREE.MeshStandardMaterial({ color: 0x4d5357, roughness: 0.4, metalness: 0.6 });
  return PK;
}
function pkSignTex(text, bg = '#1d4f9c', fg = '#fff', w = 512, h = 128) {
  const c = mkCanvas(w, h),
    x = c.getContext('2d');
  x.fillStyle = bg;
  x.fillRect(0, 0, w, h);
  x.fillStyle = fg;
  x.font = `700 ${Math.round(h * 0.55)}px Oswald, sans-serif`;
  x.textAlign = 'center';
  x.textBaseline = 'middle';
  x.fillText(text, w / 2, h / 2 + 2);
  return canvasTex(c, { repeat: false });
}
// hall: centre, axis u (length L) and v (width W = 31: bays | lane | double bays | lane | bays), floor height yF at the
// u- end. o (v0.76): y1 = floor height at the u+ end (a sloping hall: the long one of La Trinidad follows the avenue),
// density = share of bays with a parked car, deck = false when the caller lays one deck along a chain of halls
function buildHall(F, uc, L, yF, name, gaps, holes = [], o = {}) {
  // holes: [u0, u1, v0, v1] (hall frame) left open in the ceiling over the stairwells (v0.76)
  const M_ = pkMats();
  const g = new THREE.Group();
  const W = 31,
    H = 3.4,
    hl = L / 2,
    hw = W / 2;
  const { yAt, tilt, dens, P, ang, place } = buildHallPart1(o, yF, L, F, hl, uc, g);
  const tilted = (mesh) => {
    if (tilt) mesh.rotation.set(-tilt, mesh.rotation.y, 0, 'YXZ');
    return mesh;
  }; // follows the slope along u
  // floor + ceiling
  const fl = new THREE.Mesh(new THREE.PlaneGeometry(W, L / Math.cos(tilt)), M_.floor);
  fl.rotation.x = -Math.PI / 2;
  const fg = new THREE.Group();
  fg.add(fl);
  tilted(place(fg, 0, yAt(0) + 0.12, 0));
  // v0.76 (Jonay): the ceiling in tiles, leaving open the shafts of the stairs (the slab used to cut the stairs in two:
  // a wall half way down seen from the plaza, and seen from above, a «floor» that hid the player up to the chest)
  {
    const us = [-hl, hl],
      vs = [-hw, hw];
    for (const h of holes) {
      us.push(clamp(h[0], -hl, hl), clamp(h[1], -hl, hl));
      vs.push(clamp(h[2], -hw, hw), clamp(h[3], -hw, hw));
    }
    const su = [...new Set(us)].sort((a, b) => a - b),
      sv = [...new Set(vs)].sort((a, b) => a - b);
    for (let i = 0; i + 1 < su.length; i++)
      for (let j = 0; j + 1 < sv.length; j++) {
        const u0 = su[i],
          u1 = su[i + 1],
          v0 = sv[j],
          v1 = sv[j + 1];
        if (u1 - u0 < 0.01 || v1 - v0 < 0.01) continue;
        const um = (u0 + u1) / 2,
          vm = (v0 + v1) / 2;
        if (holes.some((h) => um > h[0] && um < h[1] && vm > h[2] && vm < h[3])) continue;
        const ce = new THREE.Mesh(new THREE.PlaneGeometry(v1 - v0, (u1 - u0) / Math.cos(tilt)), M_.ceil);
        ce.rotation.x = Math.PI / 2;
        const cg = new THREE.Group();
        cg.add(ce);
        tilted(place(cg, um, yAt(um) + 0.12 + H, vm));
      }
  }
  // walls with gaps [side ('u+','u-','v+','v-'), centre, width]
  const wallSeg = (side, a, b) => {
    if (b - a < 0.05) return;
    const len = b - a,
      mid = (a + b) / 2;
    const alongU = side[0] === 'v';
    const m = new THREE.Mesh(new THREE.BoxGeometry(side[0] === 'u' ? len : 0.3, H, side[0] === 'u' ? 0.3 : len / Math.cos(tilt)), M_.wall);
    const um = side === 'u+' ? hl : side === 'u-' ? -hl : mid;
    const yb = yAt(um) + 0.12;
    if (side === 'v+') place(m, mid, yb + H / 2, hw);
    else if (side === 'v-') place(m, mid, yb + H / 2, -hw);
    else if (side === 'u+') place(m, hl, yb + H / 2, mid);
    else place(m, -hl, yb + H / 2, mid);
    if (alongU) tilted(m);
    // yellow-black band at bumper height
    const st = new THREE.Mesh(new THREE.BoxGeometry(side[0] === 'u' ? len : 0.32, 0.3, side[0] === 'u' ? 0.32 : len / Math.cos(tilt)), M_.stripe);
    st.position.copy(m.position);
    st.position.y = yb + 0.55;
    st.rotation.copy(m.rotation);
    g.add(st);
  };
  const { bayW, rows, uStart, uEnd, lines } = buildHallPart2(hl, hw, gaps, wallSeg, W);
  let nCars = 0;
  for (const [vc, face] of rows)
    for (let u = uStart; u <= uEnd + 0.01; u += bayW) {
      lines.push([u, vc]);
      if (u + bayW > uEnd + 0.01) continue;
      if (holes.some((h) => u + bayW > h[0] - 2 && u < h[1] + 2 && vc + 2.6 > h[2] && vc - 2.6 < h[3])) continue; // nobody parks under a stairwell
      if (Math.random() < dens) {
        const m = makeCarMesh(pick(['compact', 'sedan', 'suv', 'compact']), pickColor());
        const gg = m.g || m;
        const [x, z] = P(u + bayW / 2, vc);
        const yy = yAt(u + bayW / 2);
        gg.position.set(x, yy + 0.12, z);
        gg.rotation.y = ang + (face > 0 ? Math.PI / 2 : -Math.PI / 2);
        gg.userData.car = true;
        gg.traverse((q) => {
          if (q.isMesh) {
            q.castShadow = false;
            q.receiveShadow = false;
          }
        });
        g.add(gg);
        nCars++;
        for (const k of [-1.3, 0, 1.3]) {
          const [px, pz] = P(u + bayW / 2, vc + k);
          UGC.push([px, pz, 0.95, yy, gg]);
        }
      }
    }
  buildHallPart3(lines, M_, place, yAt, ang, hl, tilted);
  // columns (between back-to-back bays) and light strips over the lanes
  for (let u = uStart; u <= uEnd; u += bayW * 3) {
    const yb = yAt(u) + 0.12;
    const c = new THREE.Mesh(new THREE.BoxGeometry(0.55, H, 0.55), M_.col);
    place(c, u, yb + H / 2, 0);
    const [x, z] = P(u, 0);
    UGC.push([x, z, 0.4, yAt(u)]);
    for (const vc of [-10.4, 10.4]) {
      if (holes.some((h) => u > h[0] - 0.5 && u < h[1] + 0.5 && vc > h[2] - 0.5 && vc < h[3] + 0.5)) continue;
      const c2 = new THREE.Mesh(new THREE.BoxGeometry(0.5, H, 0.5), M_.col);
      place(c2, u, yb + H / 2, vc);
      const [x2, z2] = P(u, vc);
      UGC.push([x2, z2, 0.35, yAt(u)]);
    }
  }
  const { sx } = buildHallPart4(name, hl, M_, tilted, place, yAt, H, hw);
  for (const q of gaps) {
    if (q[2] >= W - 0.5) continue;
    const m = new THREE.Mesh(new THREE.PlaneGeometry(1.6, 0.4), sx);
    const u = q[0] === 'u+' ? hl - 4 : q[0] === 'u-' ? -hl + 4 : q[1];
    const v = q[0][0] === 'u' ? q[1] : q[0] === 'v+' ? hw - 3 : -hw + 3;
    place(m, u, yAt(u) + 0.12 + H - 0.35, v, q[0] === 'u+' ? 0 : q[0] === 'u-' ? Math.PI : Math.PI / 2);
  }
  buildHallPart5(g, o, P, hl, yAt, W, hw, H);
  return { nCars, yAt };
}
/** (v1.1.7, code quality) part of buildHall: v0.76: the long hall of La Trinidad is ~1200 small pieces: fuse those without a texture into one mesh per material */
function buildHallPart5(g, o, P, hl, yAt, W, hw, H) {
  // v0.76: the long hall of La Trinidad is ~1200 small pieces: fuse those without a texture into one mesh per material
  g.updateMatrixWorld(true);
  const byMat = new Map();
  g.traverse((m) => {
    if (!m.isMesh || m.material.map) return;
    for (let q = m.parent; q && q !== g; q = q.parent) if (q.userData.car) return;
    if (!byMat.has(m.material)) byMat.set(m.material, []);
    byMat.get(m.material).push(m);
  });
  for (const [mat, list] of byMat) {
    if (list.length < 2) continue;
    const mg = mergeGeos(
      list.map((m) => {
        const q = m.geometry.clone();
        q.applyMatrix4(m.matrixWorld);
        return q;
      })
    );
    for (const m of list) {
      m.parent.remove(m);
      m.geometry.dispose();
    }
    g.add(new THREE.Mesh(mg, mat));
  }
  scene.add(g);
  // v0.76 (Jonay: «no me deja correr por el carril principal»): one deck as wide as the hall, capped at the end walls.
  // With five overlapping strips the one picked changed across the lane and its clamp pushed you back to the side
  if (o.deck !== false) {
    const a = P(-hl + 0.4, 0),
      b = P(hl - 0.4, 0);
    TUNNEL_DECKS.push({
      type: 'path',
      pts: [
        [a[0], a[1], yAt(-hl + 0.4) + 0.12],
        [b[0], b[1], yAt(hl - 0.4) + 0.12]
      ],
      w: W,
      hw: hw - 0.15,
      road: true,
      tunnel: true,
      capped: true,
      ceil: H - 0.2,
      hall: true
    });
  }
}
/** (v1.1.7, code quality) part of buildHall: signs */
function buildHallPart4(name, hl, M_, tilted, place, yAt, H, hw) {
  for (const vl of [-7.25, 7.25])
    for (let u = -hl + 3; u < hl - 3; u += 5) {
      const l = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.06, 1.6), M_.light);
      tilted(place(l, u, yAt(u) + 0.12 + H - 0.05, vl));
    }
  // signs
  const sP = new THREE.MeshBasicMaterial({ map: pkSignTex('P  -1   ' + name.toUpperCase(), '#1d4f9c', '#fff', 1024, 128) });
  for (const s of [-1, 1]) {
    const u = s * hl * 0.5;
    const m = new THREE.Mesh(new THREE.PlaneGeometry(6, 0.75), sP);
    place(m, u, yAt(u) + 0.12 + 2.1, -hw + 0.2, -Math.PI / 2);
    const m2 = new THREE.Mesh(new THREE.PlaneGeometry(6, 0.75), sP);
    place(m2, u, yAt(u) + 0.12 + 2.1, hw - 0.2, Math.PI / 2);
  }
  const sx = new THREE.MeshBasicMaterial({ map: pkSignTex('SALIDA  ►', '#1f8a3c', '#fff') });
  return { sx };
}
/** (v1.1.7, code quality) part of buildHall: lane arrows and centre dashes */
function buildHallPart3(lines, M_, place, yAt, ang, hl, tilted) {
  for (const [u, vc] of lines) {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(0.12, 5), M_.line);
    m.rotation.x = -Math.PI / 2;
    const q = new THREE.Group();
    q.add(m);
    place(q, u, yAt(u) + 0.135, vc);
    q.rotation.y = ang + Math.PI / 2;
  }
  // lane arrows and centre dashes
  for (const vl of [-7.25, 7.25])
    for (let u = -hl + 4; u < hl - 4; u += 6) {
      const m = new THREE.Mesh(new THREE.PlaneGeometry(0.15, 2.6), M_.line);
      m.rotation.x = -Math.PI / 2;
      const q = new THREE.Group();
      q.add(m);
      tilted(place(q, u, yAt(u) + 0.135, vl));
    }
}
/** (v1.1.7, code quality) part of buildHall: bays: rows at v in [-15.5,-10.5], [-4, 0], [0, 4], [10.5, 15.5]; lanes at v = ±7.25 and cross lanes at both ends (7 m) */
function buildHallPart2(hl, hw, gaps, wallSeg, W) {
  for (const side of ['v+', 'v-', 'u+', 'u-']) {
    const ext = side[0] === 'v' ? hl : hw;
    const gs = gaps
      .filter((q) => q[0] === side)
      .map((q) => [q[1] - q[2] / 2, q[1] + q[2] / 2])
      .sort((p, q) => p[0] - q[0]);
    let a = -ext;
    for (const [s, e] of gs) {
      wallSeg(side, a, s);
      a = e;
    }
    wallSeg(side, a, ext);
  }
  // bays: rows at v in [-15.5,-10.5], [-4, 0], [0, 4], [10.5, 15.5]; lanes at v = ±7.25 and cross lanes at both ends (7 m)
  const openU = (s) => gaps.some((q) => q[0] === s && q[2] >= W - 0.5); // an end opening onto the next hall of a chain: bays and columns run on
  const bayW = 2.5,
    rows = [
      [-13, 1],
      [-2, -1],
      [2, 1],
      [13, -1]
    ];
  const uStart = -hl + (openU('u-') ? 1.5 : 7.5),
    uEnd = hl - (openU('u+') ? 1.5 : 7.5);
  const lines = [];
  return { bayW, rows, uStart, uEnd, lines };
}
/** (v1.1.7, code quality) part of buildHall */
function buildHallPart1(o, yF, L, F, hl, uc, g) {
  const y1 = o.y1 ?? yF,
    yAt = (u) => yF + (y1 - yF) * clamp((u + hl) / L, 0, 1),
    tilt = Math.atan2(y1 - yF, L),
    dens = o.density ?? 0.45;
  const P = (u, v) => F.W(uc + u, v);
  const ang = Math.atan2(F.ux, F.uz); // rotation.y so that local z = u
  const place = (mesh, u, y, v, rotY = 0) => {
    const [x, z] = P(u, v);
    mesh.position.set(x, y, z);
    mesh.rotation.y = ang + rotY;
    g.add(mesh);
    return mesh;
  };
  return { yAt, tilt, dens, P, ang, place };
}
function rampProfile(Lr, yF) {
  return (s, x, z) => lerp(heightAt(x, z), yF, smooth(0, 1, (s - 2) / Math.max(4, Lr - 8)));
}
// ramp from (x0,z0) on the surface to (x1,z1) inside the hall, built with the tunnel/cutting machinery
function buildRamp(x0, z0, x1, z1, yF, label, o = {}) {
  // o: w (width), wc (wall colour: the Indigo ones are blue)
  const Lr = Math.hypot(x1 - x0, z1 - z0);
  const c = [x0, z0, x1, z1];
  tunnelRoad(c, o.w || 6.8, 'asphalt', 8, rampProfile(Lr, yF), { H: 3.9, cover: 4.3, wc: o.wc, cutStreets: true });
  // entrance sign on a post at the top
  const M_ = pkMats();
  const dx = (x1 - x0) / Lr,
    dz = (z1 - z0) / Lr;
  const so = (o.w || 6.8) / 2 + 0.8;
  let px = x0 - dz * so,
    pz = z0 + dx * so;
  if (onCarriagewayEarly(px, pz, 0.4) || inAnyBuilding(px, pz)) {
    px = x0 + dz * so;
    pz = z0 - dx * so;
  }
  if (onCarriagewayEarly(px, pz, 0.4) || inAnyBuilding(px, pz)) return;
  /* v0.68: the post never on a carriageway (auditor) */ const y = heightAt(px, pz);
  const post = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 3.2, 8), M_.steel);
  post.position.set(px, y + 1.6, pz);
  scene.add(post);
  const sg = new THREE.Mesh(
    new THREE.BoxGeometry(1.1, 1.1, 0.08),
    new THREE.MeshStandardMaterial({ map: pkSignTex('P', '#1d4f9c', '#fff', 128, 128), roughness: 0.5 })
  );
  sg.position.set(px, y + 3.0, pz);
  sg.rotation.y = Math.atan2(-dx, -dz);
  scene.add(sg);
  const lb = new THREE.Mesh(new THREE.PlaneGeometry(2.6, 0.45), new THREE.MeshBasicMaterial({ map: pkSignTex(label, '#1d4f9c', '#fff', 512, 96) }));
  lb.position.set(px, y + 2.2, pz);
  lb.rotation.y = Math.atan2(-dx, -dz);
  scene.add(lb);
  {
    const lb2 = lb.clone();
    lb2.rotation.y += Math.PI;
    scene.add(lb2);
  } // v0.62: readable from both sides (DoubleSide showed it mirrored)
  COL.addCirc(px, pz, 0.12);
}
const STAIR_OPEN = 0.78; // fraction of the stair under the open shaft (the terrain hole stops 2.5 m before the foot: TCUTS)
// the ceiling hole of a stairwell, in a hall frame F (u along the hall, uc its centre): [u0, u1, v0, v1]
function stairHole(F, uc, x0, z0, ux, uz) {
  const L = 10,
    toU = (x, z) => (x - F.cx) * F.ux + (z - F.cz) * F.uz - uc,
    toV = (x, z) => -(x - F.cx) * F.uz + (z - F.cz) * F.ux;
  const a = [x0 - ux * 0.6, z0 - uz * 0.6],
    b = [x0 + ux * (L * STAIR_OPEN + 0.3), z0 + uz * (L * STAIR_OPEN + 0.3)],
    w = 1.35;
  const ua = [toU(...a), toU(...b)],
    va = [toV(...a), toV(...b)];
  return [
    Math.min(...ua) - (Math.abs(uz * F.ux - ux * F.uz) > 0.5 ? w : 0),
    Math.max(...ua) + (Math.abs(uz * F.ux - ux * F.uz) > 0.5 ? w : 0),
    Math.min(...va) - (Math.abs(ux * F.ux + uz * F.uz) > 0.5 ? w : 0),
    Math.max(...va) + (Math.abs(ux * F.ux + uz * F.uz) > 0.5 ? w : 0)
  ];
}
// pedestrian stairwell: a glass pavilion on the surface over a stair that goes down into the hall
function buildStairwell(x0, z0, ux, uz, yF, corr) {
  const { M_, L, g0, x1, z1, ang } = buildStairwellPart1(x0, z0, ux, uz, yF, corr);
  const { g } = buildStairwellPart2(x0, ux, z0, uz, x1, z1, ang, yF);
  const n = Math.ceil((g0 - yF) / 0.18);
  for (let i = 0; i < n; i++) {
    const t = (i + 0.5) / n;
    const st = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.18, L / n + 0.03), M_.col);
    st.position.set(0, lerp(g0, yF + 0.12, t) - 0.09, -L / 2 + t * L);
    g.add(st);
  }
  for (const s of [-1, 1]) {
    const wl = new THREE.Mesh(new THREE.BoxGeometry(0.15, g0 - yF + 1, L), M_.wall);
    wl.position.set(s * 1.25, (g0 + yF) / 2, 0);
    g.add(wl);
  }
  // v0.76: the shaft is open up to STAIR_OPEN of its length (where the hole in the ground ends); a lintel closes the gap
  // between the car park's ceiling and the ground beyond it
  {
    const yc = yF + 0.12 + 3.4,
      hh = g0 - yc;
    if (hh > 0.2) {
      const ln = new THREE.Mesh(new THREE.BoxGeometry(2.5, hh, 0.3), M_.wall);
      ln.position.set(0, yc + hh / 2, -L / 2 + L * STAIR_OPEN + 0.15);
      g.add(ln);
    }
  }
  // pavilion: glass box with a steel roof and a «P» sign
  const gy = g0;
  const pav = new THREE.Mesh(new THREE.BoxGeometry(3.0, 2.5, L * 0.55), M_.glass);
  pav.position.set(0, gy + 1.25, -L * 0.2);
  g.add(pav);
  const roof = new THREE.Mesh(new THREE.BoxGeometry(3.4, 0.15, L * 0.6), M_.steel);
  roof.position.set(0, gy + 2.55, -L * 0.2);
  g.add(roof);
  const sg = new THREE.Mesh(new THREE.PlaneGeometry(0.9, 0.9), new THREE.MeshBasicMaterial({ map: pkSignTex('P', '#1d4f9c', '#fff', 128, 128) }));
  sg.position.set(0, gy + 2.1, -L * 0.2 - L * 0.275 - 0.01);
  sg.rotation.y = Math.PI;
  g.add(sg);
  scene.add(g);
  // the pavilion's side walls stop people walking into the hole from the sides
  for (const s of [-1, 1]) {
    const ax = x0 + uz * s * 1.5,
      az = z0 - ux * s * 1.5;
    COL.addSeg(ax, az, ax + ux * L * 0.75, az + uz * L * 0.75);
  }
}
/** (v1.1.7, code quality) part of buildStairwell: keep the foot of the stairs clear: no parked cars under / in front of the stairwell */
function buildStairwellPart2(x0, ux, z0, uz, x1, z1, ang, yF) {
  // keep the foot of the stairs clear: no parked cars under / in front of the stairwell
  {
    const sx = x0 - ux,
      sz = z0 - uz,
      ex = x1 + ux * 4,
      ez = z1 + uz * 4,
      L2 = (ex - sx) ** 2 + (ez - sz) ** 2;
    for (let i = UGC.length - 1; i >= 0; i--) {
      const c = UGC[i];
      if (c[3] === undefined || Math.abs(c[3] - yF) > 0.6 || !c[4]) continue;
      const t = clamp(((c[0] - sx) * (ex - sx) + (c[1] - sz) * (ez - sz)) / L2, 0, 1);
      if (Math.hypot(c[0] - sx - (ex - sx) * t, c[1] - sz - (ez - sz) * t) < 2.6) {
        c[4].visible = false;
        const m = c[4];
        for (let j = UGC.length - 1; j >= 0; j--) if (UGC[j][4] === m) UGC.splice(j, 1);
        i = Math.min(i, UGC.length);
      }
    }
  }
  TCUTS.push([x0 - ux * 0.3, z0 - uz * 0.3, x1 - ux * 2.5, z1 - uz * 2.5, 1.35, 9000 + TCUTS.length]);
  const g = new THREE.Group();
  g.position.set((x0 + x1) / 2, 0, (z0 + z1) / 2);
  g.rotation.y = ang;
  return { g };
}
/** (v1.1.7, code quality) part of buildStairwell: underground corridor from the foot of the stairs to the hall */
function buildStairwellPart1(x0, z0, ux, uz, yF, corr) {
  const M_ = pkMats();
  const L = 10,
    g0 = heightAt(x0, z0);
  const x1 = x0 + ux * L,
    z1 = z0 + uz * L;
  const ang = Math.atan2(ux, uz);
  const dpts = [
    [x0 - ux * 0.5, z0 - uz * 0.5, g0 - 0.1],
    [x1, z1, yF + 0.12],
    [x1 + ux * 1.5, z1 + uz * 1.5, yF + 0.12]
  ];
  if (corr) {
    // underground corridor from the foot of the stairs to the hall
    const cx0 = x1 + ux * 1.5,
      cz0 = z1 + uz * 1.5,
      cx1 = corr[0],
      cz1 = corr[1];
    dpts.push([cx1, cz1, yF + 0.12]);
    const cl = Math.hypot(cx1 - cx0, cz1 - cz0),
      ca = Math.atan2(cx1 - cx0, cz1 - cz0);
    const cg = new THREE.Group();
    cg.position.set((cx0 + cx1) / 2, 0, (cz0 + cz1) / 2);
    cg.rotation.y = ca;
    const fl = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.1, cl + 2.6), M_.col);
    fl.position.y = yF + 0.07;
    cg.add(fl);
    const ce = new THREE.Mesh(new THREE.BoxGeometry(2.8, 0.12, cl + 2.6), M_.ceil);
    ce.position.y = yF + 2.75;
    cg.add(ce);
    for (const sd of [-1, 1]) {
      const wl = new THREE.Mesh(new THREE.BoxGeometry(0.12, 2.7, cl + 2.6), M_.wall);
      wl.position.set(sd * 1.32, yF + 1.45, 0);
      cg.add(wl);
    }
    const lt = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.05, cl * 0.8), M_.light);
    lt.position.y = yF + 2.68;
    cg.add(lt);
    scene.add(cg);
  }
  TUNNEL_DECKS.push({ type: 'path', pts: dpts, w: 2.4, hw: 1.0, tunnel: true, ceil: 2.6 });
  return { M_, L, g0, x1, z1, ang };
}
function buildCarParks() {
  // ---- Plaza del Cristo
  const c = CARPARK_SRC.cristo;
  if (c) {
    const F = pcaFrame(c);
    const uLen = F.u1 - F.u0;
    const uc = (F.u0 + F.u1) / 2 - 0;
    const vc = (F.v0 + F.v1) / 2;
    const F2 = { ...F, cx: F.W(0, vc)[0], cz: F.W(0, vc)[1] };
    F2.W = (u, v) => [F2.cx + F.ux * u - F.uz * v, F2.cz + F.uz * u + F.ux * v];
    const L = clamp(uLen - 2 * 34, 36, 80);
    let gmin = 1e9;
    for (let u = -L / 2; u <= L / 2; u += 6)
      for (let v = -15; v <= 15; v += 5) {
        const [x, z] = F2.W(uc + u, v);
        gmin = Math.min(gmin, heightAt(x, z));
      }
    const yF = gmin - 5.4; // deep enough for a tall ramp mouth (cars used to scrape the lintel)
    const gaps = [
      ['u+', 7.25, 8.6],
      ['u-', -7.25, 8.6],
      ['v+', -L / 4, 2.6],
      ['v-', L / 4, 2.6]
    ];
    const SW = [
      [-L / 4, 13.8, 1],
      [L / 4, -13.8, -1]
    ].map(([u, v, d]) => {
      const p = F2.W(uc + u - d * 5, v);
      return [p[0], p[1], F.ux * d, F.uz * d];
    });
    const r = buildHall(
      F2,
      uc,
      L,
      yF,
      'Plaza del Cristo',
      gaps,
      SW.map((q) => stairHole(F2, uc, ...q))
    );
    // vehicle ramps from both ends of the plaza (one each way, both usable)
    for (const [s, v] of [
      [1, 7.25],
      [-1, -7.25]
    ]) {
      const top = F2.W(uc + s * (L / 2 + 42), v),
        bot = F2.W(uc + s * (L / 2 - 3.5), v);
      buildRamp(top[0], top[1], bot[0], bot[1], yF, s > 0 ? 'ENTRADA · SALIDA' : 'PARKING DEL CRISTO');
    }
    // stairwells: pavilions over the plaza, stairs going down to the side aisles
    for (const q of SW) buildStairwell(q[0], q[1], q[2], q[3], yF);
    CARPARKS.push({ name: 'Parking del Cristo', x: F2.cx, z: F2.cz, F: F2, uc, L, yF });
    // the plaza on top: rows of Indian laurels, benches and lanterns around the edge, open centre for fairs
    const per = [];
    for (let i = 0; i < c.length; i += 2) per.push([c[i], c[i + 1]]);
    let acc0 = 0;
    for (let i = 0; i < per.length; i++) {
      const a = per[i],
        b = per[(i + 1) % per.length];
      const Ls = Math.hypot(b[0] - a[0], b[1] - a[1]);
      if (Ls < 1) continue;
      const nx = -(b[1] - a[1]) / Ls,
        nz = (b[0] - a[0]) / Ls;
      for (let s = 9 - (acc0 % 9); s < Ls; s += 9) {
        let x = a[0] + ((b[0] - a[0]) * s) / Ls,
          z = a[1] + ((b[1] - a[1]) * s) / Ls;
        let px = x + nx * 5,
          pz = z + nz * 5;
        if (!pip(px, pz, c)) {
          px = x - nx * 5;
          pz = z - nz * 5;
        }
        if (!pip(px, pz, c) || onCarriagewayEarly(px, pz)) continue;
        if (Math.random() < 0.85) TREES.push([px, pz, 0, rnd(1.0, 1.25), 1]);
        const bx = px + ((b[0] - a[0]) / Ls) * 4.5,
          bz = pz + ((b[1] - a[1]) / Ls) * 4.5;
        if (Math.random() < 0.5) PLAZA_PROPS.push(['bench', bx, bz, Math.atan2(nx, nz)]);
        else LAMPS.push([bx, bz, Math.atan2(nx, nz), true]);
      }
      acc0 += Ls;
    }
    PLAZA_PROPS.push(['kiosk', ...F2.W(uc, 0)]);
  }
  // ---- Avenida de La Trinidad: two Indigo car parks (v0.68, 05u_trinidad.js)
  try {
    trinidadParking();
  } catch (e) {
    console.error('trinidad parking', e);
  }
  console.log('car parks', CARPARKS.map((c) => c.name).join(', '), 'ugc', UGC.length);
}
// simple props for the plaza (benches and a kiosk), built after the scenery is ready
const PLAZA_PROPS = [];
function buildPlazaProps() {
  const wood = M(0x7a4a2a, 0.8),
    iron = M(0x2e3236, 0.5, 0.5),
    white = M(0xf2efe8, 0.8),
    green = M(0x2f6b3a, 0.6);
  for (const p of PLAZA_PROPS) {
    if (inCut(p[1], p[2], 1.2)) continue;
    const g = new THREE.Group();
    if (p[0] === 'bench') {
      const s = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.08, 0.45), wood);
      s.position.y = 0.45;
      const b = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.4, 0.06), wood);
      b.position.set(0, 0.7, -0.2);
      g.add(s, b);
      for (const k of [-0.8, 0.8]) {
        const l = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.45, 0.45), iron);
        l.position.set(k, 0.22, 0);
        g.add(l);
      }
      g.rotation.y = p[3] || 0;
      COL.addCirc(p[1], p[2], 0.5);
    } else if (p[0] === 'kiosk') {
      const base = new THREE.Mesh(new THREE.CylinderGeometry(1.8, 1.8, 2.6, 8), white);
      base.position.y = 1.3;
      const roof = new THREE.Mesh(new THREE.ConeGeometry(2.4, 1.2, 8), green);
      roof.position.y = 3.2;
      g.add(base, roof);
      COL.addCirc(p[1], p[2], 1.9);
    }
    g.position.set(p[1], heightAt(p[1], p[2]), p[2]);
    g.traverse((o) => {
      if (o.isMesh) {
        o.castShadow = true;
        o.receiveShadow = true;
      }
    });
    scene.add(g);
  }
}

// ============ plazas & parks: Plaza del Adelantado, Camino Largo, Parque de la Constitución and every other square / park ============
// Squares get a ring of trees, benches facing in, lanterns and a centrepiece; parks get paved paths (a loop and cross paths),
// benches and lamps along them, lawns, and in the bigger ones a playground. Hand-made pieces for the famous places.
const PK2 = { fountains: [], ducks: [] };
function flatArea(c) {
  let a = 0;
  for (let i = 0, j = c.length - 2; i < c.length; j = i, i += 2) a += (c[j] - c[i]) * (c[j + 1] + c[i + 1]);
  return Math.abs(a / 2);
}
function flatCentroid(c) {
  let x = 0,
    z = 0;
  const n = c.length / 2;
  for (let i = 0; i < c.length; i += 2) {
    x += c[i];
    z += c[i + 1];
  }
  return [x / n, z / n];
}
// inward offset of a polygon (per-vertex bisector; good enough for the mostly convex squares and parks)
function flatInset(c, d) {
  const n = c.length / 2;
  let s = 0;
  for (let i = 0, j = c.length - 2; i < c.length; j = i, i += 2) s += (c[j] - c[i]) * (c[j + 1] + c[i + 1]);
  const sg = s > 0 ? 1 : -1;
  const out = [];
  for (let i = 0; i < n; i++) {
    const p = (i - 1 + n) % n,
      q = (i + 1) % n;
    const ax = c[i * 2] - c[p * 2],
      az = c[i * 2 + 1] - c[p * 2 + 1],
      bx = c[q * 2] - c[i * 2],
      bz = c[q * 2 + 1] - c[i * 2 + 1];
    const la = Math.hypot(ax, az) || 1,
      lb = Math.hypot(bx, bz) || 1;
    const n1x = (-az / la) * sg,
      n1z = (ax / la) * sg,
      n2x = (-bz / lb) * sg,
      n2z = (bx / lb) * sg;
    let mx = n1x + n2x,
      mz = n1z + n2z;
    const ml = Math.hypot(mx, mz) || 1;
    mx /= ml;
    mz /= ml;
    const k = d / Math.max(0.35, mx * n1x + mz * n1z);
    out.push(c[i * 2] + mx * k, c[i * 2 + 1] + mz * k);
  }
  return pip(...flatCentroid(out), c) ? out : null;
}
function buildPlazasParks() {
  const { placed, paths, SGR, gSome, placedSome } = buildPlazasParksPart1();
  const bench = [],
    bin = [],
    bed = [],
    playground = [],
    bust = [];
  const { free, addPath, nearPath, benchAt, lampAt, tree } = buildPlazasParksPart2(placedSome, paths, gSome, SGR, bench, placed);
  const { along } = buildPlazasParksPart3();

  // ---------------- Plaza del Adelantado (the block ringed by the streets of the same name)
  {
    const corners = [
      [110.5, 33.5],
      [183.0, 37.5],
      [178.0, -26.5],
      [127.5, -37.0],
      [114.0, 16.5]
    ];
    const poly = corners.flat();
    const C = flatInset(poly, 1.0) || poly;
    const [cx, cz] = flatCentroid(C);
    // paving: light stone walks from the fountain to the middle of each side, and a ring round the fountain
    const ring = [];
    for (let i = 0; i <= 24; i++) {
      const a = (i / 24) * Math.PI * 2;
      ring.push(cx + Math.cos(a) * 9.5, cz + Math.sin(a) * 9.5);
    }
    addPath(ring, 3.2);
    for (let i = 0; i < corners.length; i++) {
      const a = corners[i],
        b = corners[(i + 1) % corners.length];
      const mx = (a[0] + b[0]) / 2,
        mz = (a[1] + b[1]) / 2;
      const dx = mx - cx,
        dz = mz - cz,
        L = Math.hypot(dx, dz);
      addPath([cx + (dx / L) * 11, cz + (dz / L) * 11, mx - (dx / L) * 1.5, mz - (dz / L) * 1.5], 3.0);
    }
    marbleFountain(cx, cz);
    placed.push([cx, cz, 6.2]);
    // flower beds round the fountain, benches on the ring facing it
    for (let i = 0; i < 8; i++) {
      const a = ((i + 0.5) / 8) * Math.PI * 2;
      const r = 7.0;
      bed.push([cx + Math.cos(a) * r, cz + Math.sin(a) * r, a, 2.2, 1.0]);
    }
    for (let i = 0; i < 10; i++) {
      const a = (i / 10) * Math.PI * 2 + 0.31;
      benchAt(cx + Math.cos(a) * 12.2, cz + Math.sin(a) * 12.2, cx, cz);
    }
    // the Indian laurels: rows inside the perimeter and among the walks (big old trees)
    const T = flatInset(poly, 3.2) || poly;
    along(T.concat(T.slice(0, 2)), 9.5, (x, z) => tree(x, z, 0, rnd(1.2, 1.45)));
    const T2 = flatInset(poly, 12) || null;
    if (T2)
      along(T2.concat(T2.slice(0, 2)), 10, (x, z) => {
        if (Math.hypot(x - cx, z - cz) > 15) tree(x, z, 0, rnd(1.25, 1.5));
      });
    // benches under the trees along the walks, lanterns at the corners of the walks
    for (const s of paths.slice()) {
      const dx = s[2] - s[0],
        dz = s[3] - s[1],
        L = Math.hypot(dx, dz);
      if (L < 8) continue;
      const ux = dx / L,
        uz = dz / L;
      for (let t = 5; t < L - 3; t += 7)
        for (const sg of [1, -1]) {
          const x = s[0] + ux * t - uz * sg * (s[4] / 2 + 0.8),
            z = s[1] + uz * t + ux * sg * (s[4] / 2 + 0.8);
          benchAt(x, z, x + uz * sg, z - ux * sg);
        }
    }
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      lampAt(cx + Math.cos(a) * 14.5, cz + Math.sin(a) * 14.5);
    }
    along(T.concat(T.slice(0, 2)), 17, (x, z) => lampAt(x, z), 4);
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2 + 0.6;
      const x = cx + Math.cos(a) * 12.4,
        z = cz + Math.sin(a) * 12.4;
      if (free(x, z, 0.4)) {
        bin.push([x, z, a]);
        placed.push([x, z, 0.4]);
      }
    }
    PK2.adelantado = [cx, cz];
  }
  buildPlazasParksPart4(along, benchAt, lampAt);
  buildPlazasParksPart5(along, tree);
  const { AT } = buildPlazasParksPart6(placed, playground, bust);
  for (const a of DATA.A) {
    const k = AT[a[0]];
    if (k !== 'park' && k !== 'garden') continue;
    const c = a[2];
    const ar = flatArea(c);
    if (ar < 900) continue;
    const big = ar > 6000;
    const loop = flatInset(c, big ? 6 : 4);
    if (!loop) continue;
    const [cx, cz] = flatCentroid(c);
    // loop path, and cross paths from the middle to the middle of the longest sides
    addPath(loop.concat(loop.slice(0, 2)), big ? 3.2 : 2.6);
    const sides = [];
    for (let i = 0; i < loop.length; i += 2) {
      const j = (i + 2) % loop.length;
      sides.push([Math.hypot(loop[j] - loop[i], loop[j + 1] - loop[i + 1]), (loop[i] + loop[j]) / 2, (loop[i + 1] + loop[j + 1]) / 2]);
    }
    sides.sort((p, q) => q[0] - p[0]);
    for (const s of sides.slice(0, ar > 3000 ? 3 : 2)) addPath([cx, cz, s[1], s[2]], 2.4);
    // a small roundel in the middle with a fountain or a big tree
    if (ar > 2500) {
      const ring = [];
      for (let i = 0; i <= 18; i++) {
        const t = (i / 18) * Math.PI * 2;
        ring.push(cx + Math.cos(t) * 5.5, cz + Math.sin(t) * 5.5);
      }
      addPath(ring, 2.4);
      if (
        ar > 7000 &&
        !PK2.fountains.some((f) => Math.hypot(f[0] - cx, f[1] - cz) < 80) &&
        !placedSome(cx, cz, 3, (p) => Math.hypot(p[0] - cx, p[1] - cz) < p[2] + 3)
      ) {
        stoneFountain(cx, cz, 2.6);
        placed.push([cx, cz, 3.2]);
      }
    }
    // benches on the loop facing the lawns, lamps
    along(loop.concat(loop.slice(0, 2)), big ? 16 : 13, (x, z, ux, uz) => {
      const px = x - uz * 2.2,
        pz = z + ux * 2.2;
      benchAt(px, pz, x, z) || benchAt(x + uz * 2.2, z - ux * 2.2, x, z);
    });
    along(loop.concat(loop.slice(0, 2)), 22, (x, z, ux, uz) => lampAt(x + uz * 1.8, z - ux * 1.8), 8);
    if (ar > 5000 && !playground.some((p) => Math.hypot(p[0] - cx, p[1] - cz) < 120)) {
      for (let t = 0; t < 10; t++) {
        const px = cx + rnd(-25, 25),
          pz = cz + rnd(-25, 25);
        if (pip(px, pz, c) && free(px, pz, 8) && !nearPath(px, pz, 6)) {
          playground.push([px, pz, Math.random() * 6]);
          placed.push([px, pz, 9]);
          break;
        }
      }
    }
    // flower beds at path junctions
    for (const s of sides.slice(0, 2)) {
      const x = s[1],
        z = s[2];
      for (const d of [-1, 1]) {
        const bx = x + d * 3.2,
          bz = z + d * 1.0;
        if (free(bx, bz, 1.2) && !nearPath(bx, bz, 0.6)) {
          bed.push([bx, bz, Math.random() * 3, 2.4, 1.2]);
          placed.push([bx, bz, 1.5]);
        }
      }
    }
  }
  buildPlazasParksPart7(AT, along, free, tree, benchAt, lampAt, placed, bed);
  buildPlazasParksPart8(bench, bin, bed, playground, bust, paths, placedSome, nearPath);
}
/** (v1.1.7, code quality) part of buildPlazasParks: keep paths and features clear of the trees scattered earlier */
function buildPlazasParksPart8(bench, bin, bed, playground, bust, paths, placedSome, nearPath) {
  // keep paths and features clear of the trees scattered earlier
  for (let i = TREES.length - 1; i >= 0; i--) {
    const t = TREES[i];
    if (t[4] === 1 && placedSome(t[0], t[1], 0, (p) => p[0] === t[0] && p[1] === t[1])) continue;
    if (
      nearPath(t[0], t[1], 1.0) ||
      placedSome(t[0], t[1], 0.6, (p) => Math.hypot(p[0] - t[0], p[1] - t[1]) < p[2] * 0.8 + 0.6 && !(p[0] === t[0] && p[1] === t[1]))
    )
      TREES.splice(i, 1);
  }
  buildParkProps(bench, bin, bed, playground, bust);
  console.log(
    'plazas/parks: paths',
    paths.length,
    'benches',
    bench.length,
    'beds',
    bed.length,
    'playgrounds',
    playground.length,
    'fountains',
    PK2.fountains.length
  );
}
/** (v1.1.7, code quality) part of buildPlazasParks: ---------------- every square: trees round the edge, benches facing in, lanterns, a centrepiece */
function buildPlazasParksPart7(AT, along, free, tree, benchAt, lampAt, placed, bed) {
  // ---------------- every square: trees round the edge, benches facing in, lanterns, a centrepiece
  const squares = [];
  for (const a of DATA.A) if (AT[a[0]] === 'square') squares.push(a[2]);
  for (const rd of DATA.R) {
    const c = rd[4];
    if (RTN[rd[0]] === 'pedestrian' && c.length >= 8 && c[0] === c[c.length - 2] && c[1] === c[c.length - 1]) squares.push(c.slice(0, -2));
  }
  for (const c of squares) {
    const ar = flatArea(c);
    if (ar < 250 || ar > 20000) continue;
    const [cx, cz] = flatCentroid(c);
    if (CARPARKS.some((p) => Math.hypot(p.x - cx, p.z - cz) < 60)) continue;
    if (PK2.adelantado && Math.hypot(PK2.adelantado[0] - cx, PK2.adelantado[1] - cz) < 45) continue;
    const hist = isHistoric(cx, cz);
    const edge = flatInset(c, 2.6);
    if (!edge) continue;
    along(edge.concat(edge.slice(0, 2)), hist ? 9 : 8, (x, z, ux, uz) => {
      if (Math.random() < 0.85) tree(x, z, hist ? 0 : Math.random() < 0.5 ? 1 : 3, hist ? rnd(1.1, 1.4) : rnd(0.85, 1.1));
    });
    along(
      edge.concat(edge.slice(0, 2)),
      hist ? 9 : 8,
      (x, z) => {
        benchAt(x + (cx - x) * 0.12, z + (cz - z) * 0.12, cx, cz);
      },
      hist ? 4.5 : 4
    );
    along(edge.concat(edge.slice(0, 2)), 18, (x, z) => lampAt(x + (cx - x) * 0.06, z + (cz - z) * 0.06), 9);
    if ((hist ? ar > 600 : ar > 1500) && free(cx, cz, 3) && !PK2.fountains.some((f) => Math.hypot(f[0] - cx, f[1] - cz) < 60)) {
      stoneFountain(cx, cz, ar > 1500 ? 3.2 : 2.3);
      placed.push([cx, cz, 4]);
      for (let i = 0; i < 4; i++) {
        const t = (i / 4) * Math.PI * 2 + 0.78;
        const bx = cx + Math.cos(t) * 5.5,
          bz = cz + Math.sin(t) * 5.5;
        if (free(bx, bz, 1)) bed.push([bx, bz, t, 2.0, 0.9]);
      }
    } else if (ar > 250 && free(cx, cz, 2)) tree(cx, cz, 0, 1.3);
  }
}
/** (v1.1.7, code quality) part of buildPlazasParks: ---------------- Parque de la Constitución: duck pond, playground, Martí and Bolívar busts */
function buildPlazasParksPart6(placed, playground, bust) {
  // ---------------- Parque de la Constitución: duck pond, playground, Martí and Bolívar busts
  {
    const a = DATA.A.find((q) => q[1] >= 0 && /Parque de la Constituci/.test(STR[q[1]]));
    if (a) {
      const c = a[2];
      const [cx, cz] = flatCentroid(c);
      const pc = [cx - 14, cz + 6];
      duckPond(pc[0], pc[1], 11, 6.5);
      placed.push([pc[0], pc[1], 12]);
      for (const p of DATA.P) {
        const n = STR[p[0]];
        if (n === 'José Martí' || n === 'Simón Bolivar') {
          bust.push([p[2], p[3], n === 'José Martí' ? 'JOSÉ MARTÍ' : 'SIMÓN BOLÍVAR']);
          placed.push([p[2], p[3], 2]);
        }
      }
      playground.push([cx + 22, cz - 4, 0.3]);
      placed.push([cx + 22, cz - 4, 9]);
      PK2.constitucion = [cx, cz];
    }
  }
  // ---------------- every park / garden: paths, benches, lamps, a playground in the big ones
  const AT = DATA.AT;
  return { AT };
}
/** (v1.1.7, code quality) part of buildPlazasParks: two rows of palms, one on each outer edge of the whole walk (the ways inside it are lanes of the same promenade) */
function buildPlazasParksPart5(along, tree) {
  // two rows of palms, one on each outer edge of the whole walk (the ways inside it are lanes of the same promenade)
  {
    const ways = DATA.R.filter((r) => r[1] >= 0 && STR[r[1]] === 'Avenida Universidad' && RTN[r[0]] === 'service');
    const P = [];
    for (const r of ways) along(r[4], 3, (x, z) => P.push([x, z, r[2]]), 0);
    if (P.length > 4) {
      let a = P[0],
        b = P[0];
      for (const p of P)
        for (const q of P)
          if (p[0] < q[0] + 1e9 && Math.hypot(p[0] - q[0], p[1] - q[1]) > Math.hypot(a[0] - b[0], a[1] - b[1])) {
            a = p;
            b = q;
          }
      const L = Math.hypot(b[0] - a[0], b[1] - a[1]),
        ux = (b[0] - a[0]) / L,
        uz = (b[1] - a[1]) / L;
      for (let t = 4; t < L - 4; t += 7) {
        let lo = 1e9,
          hi = -1e9;
        for (const p of P) {
          const s2 = (p[0] - a[0]) * ux + (p[1] - a[1]) * uz;
          if (Math.abs(s2 - t) > 22) continue;
          const v = -(p[0] - a[0]) * uz + (p[1] - a[1]) * ux;
          lo = Math.min(lo, v - p[2] / 2);
          hi = Math.max(hi, v + p[2] / 2);
        }
        if (lo > hi) continue;
        for (const v of [lo - 1.4, hi + 1.4]) {
          const x = a[0] + ux * t - uz * v,
            z = a[1] + uz * t + ux * v;
          if (onCarriageway(x, z, 0.3)) {
            PK2.palmFail = (PK2.palmFail || 0) + 1;
            continue;
          }
          if (tree(x, z, 1, rnd(1.15, 1.35))) PK2.palms = (PK2.palms || 0) + 1;
          else PK2.palmFail2 = (PK2.palmFail2 || 0) + 1;
        }
      }
      console.log('camino largo axis', a, b, L);
    }
  }
}
/** (v1.1.7, code quality) part of buildPlazasParks: ---------------- Camino Largo: the 700 m walk lined with ~200 Canary palms, benches and lanterns */
function buildPlazasParksPart4(along, benchAt, lampAt) {
  // ---------------- Camino Largo: the 700 m walk lined with ~200 Canary palms, benches and lanterns
  {
    const ways = DATA.R.filter((r) => r[1] >= 0 && STR[r[1]] === 'Avenida Universidad' && RTN[r[0]] === 'service');
    for (const rd of ways) {
      const c = rd[4];
      const w = rd[2];
      along(
        c,
        24,
        (x, z, ux, uz) => {
          const sg = Math.random() < 0.5 ? 1 : -1;
          const px = x - uz * sg * (w / 2 + 2.4),
            pz = z + ux * sg * (w / 2 + 2.4);
          benchAt(px, pz, x, z);
        },
        10
      );
      along(
        c,
        21,
        (x, z, ux, uz) => {
          const px = x + uz * (w / 2 + 0.9),
            pz = z - ux * (w / 2 + 0.9);
          lampAt(px, pz);
        },
        6
      );
    }
  }
}
/** (v1.1.7, code quality) part of buildPlazasParks: walk along a polyline every `step` metres */
function buildPlazasParksPart3() {
  // walk along a polyline every `step` metres
  const along = (pts, step, fn, start = step / 2) => {
    let acc = start;
    for (let i = 0; i < pts.length - 2; i += 2) {
      const x1 = pts[i],
        z1 = pts[i + 1],
        x2 = pts[i + 2],
        z2 = pts[i + 3],
        L = Math.hypot(x2 - x1, z2 - z1);
      if (L < 0.1) continue;
      const ux = (x2 - x1) / L,
        uz = (z2 - z1) / L;
      while (acc < L) {
        fn(x1 + ux * acc, z1 + uz * acc, ux, uz);
        acc += step;
      }
      acc -= L;
    }
  };
  return { along };
}
/** (v1.1.7, code quality) part of buildPlazasParks */
function buildPlazasParksPart2(placedSome, paths, gSome, SGR, bench, placed) {
  const free = (x, z, r) =>
    !placedSome(x, z, r, (p) => Math.hypot(p[0] - x, p[1] - z) < p[2] + r) &&
    !COL.nearSeg(x, z, r) &&
    !onCarriagewayEarly(x, z, r * 0.6) &&
    !inPitch(x, z, r) &&
    !inAnyBuilding(x, z);
  const addPath = (pts, w = 2.6) => {
    ribbon(pts, w, 'footway', YOFF.footway + 0.005, 2.4, w / 2.4);
    for (let i = 0; i < pts.length - 2; i += 2) paths.push([pts[i], pts[i + 1], pts[i + 2], pts[i + 3], w]);
  };
  const nearPath = (x, z, m) =>
    gSome(SGR, x, z, m, (s) => {
      const dx = s[2] - s[0],
        dz = s[3] - s[1],
        L2 = dx * dx + dz * dz || 1;
      const t = clamp(((x - s[0]) * dx + (z - s[1]) * dz) / L2, 0, 1);
      return Math.hypot(x - s[0] - dx * t, z - s[1] - dz * t) < s[4] / 2 + m;
    });
  const benchAt = (x, z, faceX, faceZ) => {
    if (!free(x, z, 0.7)) return false;
    bench.push([x, z, Math.atan2(faceX - x, faceZ - z)]);
    placed.push([x, z, 0.9]);
    return true;
  };
  const lampAt = (x, z) => {
    if (!free(x, z, 0.4)) return;
    LAMPS.push([x, z, 0, true]);
    placed.push([x, z, 0.5]);
  };
  const tree = (x, z, type, s) => {
    if (!free(x, z, 1.0) || nearPath(x, z, 1.2)) return false;
    TREES.push([x, z, type, s, 1]);
    placed.push([x, z, type === 0 ? 2.0 : 1.2]);
    return true;
  };
  return { free, addPath, nearPath, benchAt, lampAt, tree };
}
/** (v1.1.7, code quality) part of buildPlazasParks: v0.77: both lists go into a 16 m grid as well (the loops over every tree × every disc took ~3 s of the load) */
function buildPlazasParksPart1() {
  const placed = []; // [x,z,r] keep-out discs (features), used to clear trees and avoid overlaps
  const paths = []; // segments [x1,z1,x2,z2,w]
  // v0.77: both lists go into a 16 m grid as well (the loops over every tree × every disc took ~3 s of the load)
  const GC = 16,
    gk = (a, b) => a * 100003 + b,
    PGR = new Map(),
    SGR = new Map();
  const gAdd = (G, x0, z0, x1, z1, it) => {
    for (let a = Math.floor(x0 / GC); a <= Math.floor(x1 / GC); a++)
      for (let b = Math.floor(z0 / GC); b <= Math.floor(z1 / GC); b++) {
        const k = gk(a, b);
        let l = G.get(k);
        if (!l) G.set(k, (l = []));
        l.push(it);
      }
  };
  const gSome = (G, x, z, r, fn) => {
    for (let a = Math.floor((x - r) / GC); a <= Math.floor((x + r) / GC); a++)
      for (let b = Math.floor((z - r) / GC); b <= Math.floor((z + r) / GC); b++) {
        const l = G.get(gk(a, b));
        if (l) for (const it of l) if (fn(it)) return true;
      }
    return false;
  };
  placed.push = function (...its) {
    for (const p of its) {
      Array.prototype.push.call(this, p);
      gAdd(PGR, p[0] - p[2], p[1] - p[2], p[0] + p[2], p[1] + p[2], p);
    }
    return this.length;
  };
  paths.push = function (...its) {
    for (const g of its) {
      Array.prototype.push.call(this, g);
      const h = g[4] / 2;
      gAdd(SGR, Math.min(g[0], g[2]) - h, Math.min(g[1], g[3]) - h, Math.max(g[0], g[2]) + h, Math.max(g[1], g[3]) + h, g);
    }
    return this.length;
  };
  const placedSome = (x, z, r, fn) => gSome(PGR, x, z, r, fn);
  return { placed, paths, SGR, gSome, placedSome };
}
// ---- instanced furniture
function buildParkProps(bench, bin, bed, playground, bust) {
  const { o, inst, hedge, flower } = buildParkPropsPart1(bench);
  buildParkPropsPart2(inst, bin, hedge, bed, flower, o);
  // playgrounds: soft red floor, swings, slide, climbing frame, spring riders
  for (const [x, z, h] of playground) {
    buildParkPropsEach(x, z, h);
  }
  buildParkPropsPart3(bust);
}
/** (v1.1.7, code quality) the body of a loop of buildParkProps, split out of it */
function buildParkPropsEach(x, z, h) {
  const { g, y, Y, Gm, steel } = buildParkPropsEachPart1(x, z);
  // climbing dome
  const dome = new THREE.Mesh(
    new THREE.SphereGeometry(1.4, 8, 5, 0, Math.PI * 2, 0, Math.PI / 2),
    new THREE.MeshStandardMaterial({ color: 0xe03131, wireframe: true })
  );
  dome.position.set(0, 0.05, 3.2);
  g.add(dome);
  // spring riders
  for (const [sx, col] of [
    [-3.5, Gm],
    [3.8, Y]
  ]) {
    const sp = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.5, 8), steel);
    sp.position.set(sx, 0.3, 3);
    g.add(sp);
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.45, 0.9), col);
    body.position.set(sx, 0.75, 3);
    g.add(body);
  }
  g.position.set(x, y, z);
  g.rotation.y = h;
  g.traverse((m) => {
    if (m.isMesh) {
      m.castShadow = true;
      m.receiveShadow = true;
    }
  });
  scene.add(g);
  for (const [px, pz] of [
    [-3, -2.5],
    [2.5, -1.5],
    [0, 3.2]
  ]) {
    const c = Math.cos(h),
      s = Math.sin(h);
    COL.addCirc(x + px * c + pz * s, z - px * s + pz * c, 1.2);
  }
}
