/** (v1.1.7, code quality) part of buildParkProps: classic park bench: wooden slats on cast-iron sides (faces +z) */
function buildParkPropsPart1(bench) {
  const o = new THREE.Object3D();
  const inst = (geo, mat, arr, f) => {
    if (!arr.length) return;
    const m = new THREE.InstancedMesh(geo, mat, arr.length);
    arr.forEach((p, i) => {
      o.position.set(p[0], heightAt(p[0], p[1]) + 0.1, p[1]);
      o.rotation.set(0, p[2] || 0, 0);
      o.scale.set(1, 1, 1);
      if (f) f(o, p);
      o.updateMatrix();
      m.setMatrixAt(i, o.matrix);
    });
    m.castShadow = true;
    m.receiveShadow = true;
    scene.add(m);
  };
  const wood = M(0x8a5a32, 0.75),
    iron = M(0x22262a, 0.45, 0.6),
    stone = M(0xd8d2c4, 0.8),
    hedge = new THREE.MeshStandardMaterial({ color: 0x3c6a2a, roughness: 0.95, flatShading: true }),
    flower = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.8 });
  // classic park bench: wooden slats on cast-iron sides (faces +z)
  const slats = [];
  for (let k = 0; k < 4; k++) {
    const g = new THREE.BoxGeometry(1.9, 0.04, 0.09);
    g.translate(0, 0.45, 0.16 - k * 0.11);
    slats.push(g);
  }
  for (let k = 0; k < 3; k++) {
    const g = new THREE.BoxGeometry(1.9, 0.09, 0.035);
    g.rotateX(-0.22);
    g.translate(0, 0.62 + k * 0.12, -0.24 - k * 0.025);
    slats.push(g);
  }
  inst(mergeGeos(slats), wood, bench);
  const side = [];
  for (const x of [-0.85, 0.85]) {
    const a = new THREE.BoxGeometry(0.06, 0.45, 0.06);
    a.translate(x, 0.22, 0.17);
    const b = new THREE.BoxGeometry(0.06, 0.9, 0.06);
    b.rotateX(-0.18);
    b.translate(x, 0.45, -0.2);
    const c = new THREE.BoxGeometry(0.06, 0.05, 0.5);
    c.translate(x, 0.43, -0.02);
    const d = new THREE.BoxGeometry(0.06, 0.05, 0.42);
    d.translate(x, 0.66, 0.02);
    side.push(a, b, c, d);
  }
  inst(mergeGeos(side), iron, bench);
  bench.forEach((p) => COL.addCirc(p[0], p[1], 0.55));
  return { o, inst, hedge, flower };
}
// ---- neoclassical marble fountain (Plaza del Adelantado, Genoa marble, 1870): octagonal basin, pedestal, two bowls and a finial
function marbleFountain(x, z) {
  const { g, y, mar, vein, water, sheet } = marbleFountainPart1(x, z);
  const { bowl, f1 } = marbleFountainPart2(mar, g, water, sheet, x, z);
  const sh2 = new THREE.Mesh(
    new THREE.LatheGeometry(
      [
        [0, 0],
        [0.22, 0],
        [0.16, 0.2],
        [0.14, 0.8],
        [0.2, 0.95],
        [0, 0.95]
      ].map((p) => new THREE.Vector2(p[0], p[1])),
      14
    ),
    mar
  );
  sh2.position.y = 3.75;
  g.add(sh2);
  const f2 = bowl(1.0, 4.7);
  // finial: a small pine-cone on a knob, with the jet
  addMesh(g, new THREE.SphereGeometry(0.2, 12, 8), mar, 0, 5.3, 0);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.14, 0.45, 10), mar);
  cone.position.y = 5.65;
  g.add(cone);
  const jet = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.05, 0.8, 6), sheet);
  jet.position.y = 6.15;
  g.add(jet);
  // four little lion-head spouts on the pedestal pouring into the basin
  for (let i = 0; i < 4; i++) {
    const a = (i * Math.PI) / 2;
    const sp = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 6), vein);
    sp.position.set(Math.sin(a) * 0.68, 1.6, Math.cos(a) * 0.68);
    g.add(sp);
    const arc = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.05, 1.0, 6), sheet);
    arc.position.set(Math.sin(a) * 1.05, 1.15, Math.cos(a) * 1.05);
    arc.rotation.set(Math.cos(a) * 0.7, 0, -Math.sin(a) * 0.7);
    g.add(arc);
  }
  fuseGroup(g, (m) => m.material === sheet || m.material === water);
  g.position.set(x, y, z);
  g.traverse((m) => {
    if (m.isMesh && m.material !== sheet) {
      m.castShadow = true;
      m.receiveShadow = true;
    }
  });
  scene.add(g);
  COL.addCirc(x, z, 5.4);
  // the falling water shimmers
  const t0 = performance.now();
  f1.onBeforeRender = () => {
    const t = (performance.now() - t0) / 1000;
    sheet.opacity = 0.3 + Math.sin(t * 7) * 0.05;
    f1.scale.set(1 + Math.sin(t * 9) * 0.01, 1, 1 + Math.cos(t * 8) * 0.01);
  };
  return g;
}
/** (v1.1.7, code quality) part of marbleFountain: lower bowl (scalloped look via 16 segments) and water sheet falling from its lip */
function marbleFountainPart2(mar, g, water, sheet, x, z) {
  const shaft = new THREE.Mesh(
    new THREE.LatheGeometry(
      [
        [0.0, 0],
        [0.42, 0],
        [0.42, 0.1],
        [0.3, 0.25],
        [0.26, 0.9],
        [0.32, 1.05],
        [0.36, 1.15],
        [0, 1.15]
      ].map((p) => new THREE.Vector2(p[0], p[1])),
      20
    ),
    mar
  );
  shaft.position.y = 2.2;
  g.add(shaft);
  // lower bowl (scalloped look via 16 segments) and water sheet falling from its lip
  const bowl = (r, y0) => {
    const pts = [
      [0, 0],
      [0.25, 0],
      [r * 0.55, 0.12],
      [r * 0.92, 0.32],
      [r, 0.42],
      [r * 0.96, 0.46],
      [r * 0.5, 0.36],
      [0, 0.34]
    ].map((p) => new THREE.Vector2(p[0], p[1]));
    const m = new THREE.Mesh(new THREE.LatheGeometry(pts, 16), mar);
    m.position.y = y0;
    g.add(m);
    const w2 = new THREE.Mesh(new THREE.CircleGeometry(r * 0.9, 16), water);
    w2.rotation.x = -Math.PI / 2;
    w2.position.y = y0 + 0.4;
    g.add(w2);
    const fall = new THREE.Mesh(new THREE.CylinderGeometry(r * 1.0, r * 1.12, y0 + 0.42 - 0.72, 24, 1, true), sheet);
    fall.position.y = (y0 + 0.42 + 0.72) / 2;
    g.add(fall);
    PK2.fountains.push([x, z]);
    return fall;
  };
  const f1 = bowl(2.0, 3.35);
  return { bowl, f1 };
}
/** (v1.1.7, code quality) part of marbleFountain: basin: octagonal wall with moulded rim and steps */
function marbleFountainPart1(x, z) {
  const g = new THREE.Group();
  const y = heightAt(x, z) + 0.12;
  const mar = new THREE.MeshStandardMaterial({ color: 0xeeebe4, roughness: 0.35 });
  const vein = new THREE.MeshStandardMaterial({ color: 0xd9d4ca, roughness: 0.4 });
  const water = new THREE.MeshStandardMaterial({ color: 0x4d8ea3, roughness: 0.05, metalness: 0.25, transparent: true, opacity: 0.85 });
  const sheet = new THREE.MeshStandardMaterial({
    color: 0xcfe8f0,
    roughness: 0.1,
    transparent: true,
    opacity: 0.35,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  // basin: octagonal wall with moulded rim and steps
  addMesh(g, new THREE.CylinderGeometry(5.6, 5.8, 0.2, 8), vein, 0, 0.1, 0, Math.PI / 8);
  const wall = new THREE.Mesh(new THREE.CylinderGeometry(5.0, 5.1, 0.75, 8, 1, true), mar);
  wall.position.y = 0.55;
  wall.rotation.y = Math.PI / 8;
  g.add(wall);
  const inner = new THREE.Mesh(new THREE.CylinderGeometry(4.7, 4.7, 0.75, 8, 1, true), mar);
  inner.material = mar;
  inner.position.y = 0.55;
  inner.rotation.y = Math.PI / 8;
  g.add(inner);
  inner.material.side = THREE.DoubleSide;
  const rim = new THREE.Mesh(new THREE.RingGeometry(4.65, 5.25, 8), mar);
  rim.rotation.x = -Math.PI / 2;
  rim.rotation.z = Math.PI / 8;
  rim.position.y = 0.93;
  g.add(rim);
  const wt = new THREE.Mesh(new THREE.CircleGeometry(4.7, 8), water);
  wt.rotation.x = -Math.PI / 2;
  wt.rotation.z = Math.PI / 8;
  wt.position.y = 0.72;
  g.add(wt);
  // pedestal (square, with mouldings) and shaft
  addMesh(g, new THREE.BoxGeometry(1.6, 0.3, 1.6), vein, 0, 0.85, 0);
  addMesh(g, new THREE.BoxGeometry(1.3, 1.1, 1.3), mar, 0, 1.5, 0);
  addMesh(g, new THREE.BoxGeometry(1.55, 0.18, 1.55), vein, 0, 2.12, 0);
  return { g, y, mar, vein, water, sheet };
}
// smaller basalt-and-stone fountain for other squares and park roundels
function stoneFountain(x, z, r = 2.4) {
  const g = new THREE.Group();
  const y = heightAt(x, z) + 0.12;
  const bas = M(0x55524c, 0.85),
    st = M(0xd8d2c4, 0.6);
  const water = new THREE.MeshStandardMaterial({ color: 0x4d8ea3, roughness: 0.05, metalness: 0.25 });
  const wl = new THREE.Mesh(new THREE.CylinderGeometry(r, r + 0.1, 0.6, 12, 1, true), bas);
  wl.position.y = 0.3;
  wl.material.side = THREE.DoubleSide;
  g.add(wl);
  const rim = new THREE.Mesh(new THREE.RingGeometry(r - 0.28, r + 0.15, 12), st);
  rim.rotation.x = -Math.PI / 2;
  rim.position.y = 0.61;
  g.add(rim);
  const wt = new THREE.Mesh(new THREE.CircleGeometry(r - 0.25, 12), water);
  wt.rotation.x = -Math.PI / 2;
  wt.position.y = 0.48;
  g.add(wt);
  addMesh(g, new THREE.CylinderGeometry(0.28, 0.4, 1.5, 10), st, 0, 1.1, 0);
  const b = new THREE.Mesh(
    new THREE.LatheGeometry(
      [
        [0, 0],
        [0.2, 0],
        [r * 0.3, 0.12],
        [r * 0.38, 0.22],
        [r * 0.36, 0.26],
        [0, 0.22]
      ].map((p) => new THREE.Vector2(p[0], p[1])),
      14
    ),
    st
  );
  b.position.y = 1.8;
  g.add(b);
  addMesh(g, new THREE.SphereGeometry(0.16, 10, 8), st, 0, 2.15, 0);
  fuseGroup(g);
  g.position.set(x, y, z);
  g.traverse((m) => {
    if (m.isMesh) {
      m.castShadow = true;
      m.receiveShadow = true;
    }
  });
  scene.add(g);
  COL.addCirc(x, z, r + 0.1);
  PK2.fountains.push([x, z]);
  return g;
}
// raised oval pond with a stone kerb, a little island and ducks paddling about
function duckPond(x, z, rx, rz) {
  const g = new THREE.Group();
  const y = heightAt(x, z) + 0.1;
  const st = M(0x8f8a80, 0.85);
  const water = new THREE.MeshStandardMaterial({ color: 0x3f7d6f, roughness: 0.08, metalness: 0.2 });
  const shape = new THREE.Shape();
  shape.absellipse(0, 0, rx, rz, 0, Math.PI * 2);
  const wt = new THREE.Mesh(new THREE.ShapeGeometry(shape, 40), water);
  wt.rotation.x = -Math.PI / 2;
  wt.position.y = 0.32;
  g.add(wt);
  for (let i = 0; i < 40; i++) {
    const a = (i / 40) * Math.PI * 2,
      a2 = ((i + 1) / 40) * Math.PI * 2;
    const px = Math.cos(a) * rx,
      pz = Math.sin(a) * rz,
      qx = Math.cos(a2) * rx,
      qz = Math.sin(a2) * rz;
    const L = Math.hypot(qx - px, qz - pz);
    const k = new THREE.Mesh(new THREE.BoxGeometry(L + 0.05, 0.5, 0.45), st);
    k.position.set((px + qx) / 2, 0.25, (pz + qz) / 2);
    k.rotation.y = -Math.atan2(qz - pz, qx - px);
    g.add(k);
  }
  const isl = new THREE.Mesh(new THREE.CylinderGeometry(1.4, 1.8, 0.5, 10), M(0x4f7a32, 0.95));
  isl.position.set(rx * 0.35, 0.3, 0);
  g.add(isl);
  g.position.set(x, y, z);
  scene.add(g);
  for (let i = 0; i < 40; i++) {
    const a = (i / 40) * Math.PI * 2;
    COL.addSeg(
      x + Math.cos(a) * (rx + 0.2),
      z + Math.sin(a) * (rz + 0.2),
      x + Math.cos(a + Math.PI / 20) * (rx + 0.2),
      z + Math.sin(a + Math.PI / 20) * (rz + 0.2)
    );
  }
  TREES.push([x + rx * 0.35, z, 1, 0.8, 1]);
  // ducks: body + head + beak, white or mallard-brown; swim slowly round
  const ducks = [];
  const body = M(0xf4f1ea, 0.7),
    brown = M(0x7a5a3a, 0.7),
    green = M(0x1f5e3a, 0.4),
    beak = M(0xf08c00, 0.6);
  for (let i = 0; i < 7; i++) {
    const d = new THREE.Group();
    d.userData.noMerge = true;
    const mal = i % 2 === 0;
    const b = new THREE.Mesh(new THREE.SphereGeometry(0.22, 8, 6), mal ? brown : body);
    b.scale.set(1, 0.7, 1.5);
    d.add(b);
    const h = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), mal ? green : body);
    h.position.set(0, 0.2, 0.25);
    d.add(h);
    const bk = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.14, 6), beak);
    bk.rotation.x = Math.PI / 2;
    bk.position.set(0, 0.18, 0.4);
    d.add(bk);
    d.position.y = 0.38;
    g.add(d);
    ducks.push({
      d,
      a: Math.random() * 6.28,
      r: 0.45 + Math.random() * 0.35,
      sp: (0.08 + Math.random() * 0.1) * (Math.random() < 0.5 ? 1 : -1),
      ph: Math.random() * 6
    });
  }
  wt.onBeforeRender = () => {
    const t = performance.now() / 1000;
    for (const k of ducks) {
      const a = k.a + t * k.sp;
      const px = Math.cos(a) * rx * k.r,
        pz = Math.sin(a) * rz * k.r;
      k.d.position.x = px;
      k.d.position.z = pz;
      k.d.position.y = 0.38 + Math.sin(t * 2 + k.ph) * 0.015;
      k.d.rotation.y = Math.atan2(-Math.sin(a) * rx * Math.sign(k.sp), Math.cos(a) * rz * Math.sign(k.sp));
    }
  };
  PK2.ducks.push(g);
  return g;
}

// ============ La Concepción: parish church + its bell tower, modelled from photos (key landmark of the story) ============
// Footprint: OSM outline (the tower block is cut out of it in 04_world.js → CONC_CARVE). Everything here is built in
// metres on the real outline and merged per material (few draw calls).
//  - Tower (28 m): dark basalt ashlar, 4 bodies separated by cornices, windows with little iron balconies, clock,
//    belfry with two arches per side and bells, octagonal lantern with arches, small dome and cross. Wooden Canarian
//    gallery and iron fence at the foot of its west face.
//  - Church: cream plaster walls on a dark basalt plinth, double teja eaves, three naves (raised central nave with
//    oculi), arched stained-glass windows with reddish stone frames, baroque stone portal + blind arch on the north
//    flank next to the tower, and the tall white head block (plaza end) with dark stone pilasters and two rows of windows.

const CONCM = {};
function concMaterials() {
  if (CONCM.basalt) return CONCM;
  const { tex, R, ashlar } = concMaterialsPart1();
  concMaterialsPart2(ashlar, tex, R);
  concMaterialsPart3(tex, R);
  concMaterialsPart4(tex);
  return CONCM;
}
/** (v1.1.7, code quality) part of concMaterials */
function concMaterialsPart4(tex) {
  const winT = tex(
    128,
    192,
    (x, W, H) => {
      x.fillStyle = '#5a3418';
      x.fillRect(0, 0, W, H);
      x.fillStyle = '#26323a';
      for (let r = 0; r < 4; r++)
        for (let c = 0; c < 2; c++) {
          x.fillRect(12 + c * 56, 12 + r * 44, 48, 36);
          x.fillStyle = 'rgba(160,190,210,0.25)';
          x.fillRect(14 + c * 56, 14 + r * 44, 18, 30);
          x.fillStyle = '#26323a';
        }
    },
    false
  );
  CONCM.win = new THREE.MeshStandardMaterial({ map: winT, roughness: 0.4 });
  const clockT = tex(
    256,
    256,
    (x, W) => {
      x.fillStyle = '#f4f1e6';
      x.beginPath();
      x.arc(128, 128, 126, 0, 7);
      x.fill();
      x.strokeStyle = '#111';
      x.lineWidth = 6;
      x.beginPath();
      x.arc(128, 128, 118, 0, 7);
      x.stroke();
      x.fillStyle = '#111';
      x.font = 'bold 26px serif';
      x.textAlign = 'center';
      x.textBaseline = 'middle';
      ['XII', 'I', 'II', 'III', 'IIII', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI'].forEach((n, i) => {
        const a = (i / 12) * Math.PI * 2;
        x.fillText(n, 128 + Math.sin(a) * 92, 128 - Math.cos(a) * 92);
      });
      x.lineCap = 'round';
      x.lineWidth = 9;
      x.beginPath();
      x.moveTo(128, 128);
      x.lineTo(128 + Math.sin(-1.05) * 55, 128 - Math.cos(-1.05) * 55);
      x.stroke();
      x.lineWidth = 6;
      x.beginPath();
      x.moveTo(128, 128);
      x.lineTo(128 + Math.sin(1.05) * 85, 128 - Math.cos(1.05) * 85);
      x.stroke();
    },
    false
  );
  CONCM.clock = new THREE.MeshStandardMaterial({ map: clockT, roughness: 0.6 });
  for (const k of ['plaster', 'white', 'basalt', 'tile', 'stone']) CONCM[k].side = THREE.DoubleSide;
}
/** (v1.1.7, code quality) part of concMaterials */
function concMaterialsPart3(tex, R) {
  const glassT = tex(
    128,
    256,
    (x, W, H) => {
      const cols = ['#2e4f8f', '#8f2e3a', '#c9a23a', '#2f7a4e', '#5b3f8a', '#d9c69a'];
      for (let i = 0; i < 90; i++) {
        x.fillStyle = cols[(R() * cols.length) | 0];
        x.beginPath();
        const cx = R() * W,
          cy = R() * H;
        x.moveTo(cx, cy);
        for (let k = 0; k < 4; k++) x.lineTo(cx + (R() - 0.5) * 60, cy + (R() - 0.5) * 60);
        x.fill();
      }
      x.strokeStyle = '#1a1a1a';
      x.lineWidth = 3;
      for (let i = 0; i < 40; i++) {
        x.beginPath();
        x.moveTo(R() * W, R() * H);
        x.lineTo(R() * W, R() * H);
        x.stroke();
      }
      x.lineWidth = 4;
      for (let yy = 32; yy < H; yy += 32) {
        x.beginPath();
        x.moveTo(0, yy);
        x.lineTo(W, yy);
        x.stroke();
      }
    },
    false
  );
  CONCM.glass = new THREE.MeshStandardMaterial({
    map: glassT,
    emissiveMap: glassT,
    emissive: 0xffffff,
    emissiveIntensity: 0.18,
    roughness: 0.3,
    metalness: 0.2
  });
}
/** (v1.1.7, code quality) part of concMaterials */
function concMaterialsPart2(ashlar, tex, R) {
  CONCM.white.color.setRGB(1.04, 1.05, 1.08);
  CONCM.redStone = new THREE.MeshStandardMaterial({ color: 0xa8674a, roughness: 0.85 });
  CONCM.portal = new THREE.MeshStandardMaterial({ map: ashlar(true), color: 0xb9b2a8, roughness: 0.9 });
  CONCM.tile = new THREE.MeshStandardMaterial({
    map: tex(128, 64, (x, W, H) => {
      x.fillStyle = '#7a3a26';
      x.fillRect(0, 0, W, H);
      for (let i = 0; i < 8; i++) {
        const g = x.createLinearGradient(i * 16, 0, i * 16 + 16, 0);
        g.addColorStop(0, '#5a2a1c');
        g.addColorStop(0.5, '#b8654a');
        g.addColorStop(1, '#5a2a1c');
        x.fillStyle = g;
        x.fillRect(i * 16 + 1, 0, 14, H);
      }
    }),
    roughness: 0.85
  });
  CONCM.iron = new THREE.MeshStandardMaterial({ color: 0x1b1b1d, roughness: 0.5, metalness: 0.6 });
  CONCM.dark = new THREE.MeshStandardMaterial({ color: 0x141312, roughness: 1 });
  CONCM.bell = new THREE.MeshStandardMaterial({ color: 0x8a6a30, roughness: 0.35, metalness: 0.85 });
  CONCM.wood = new THREE.MeshStandardMaterial({ color: 0x6b3f22, roughness: 0.75 });
  const doorT = tex(
    256,
    512,
    (x, W, H) => {
      x.fillStyle = '#5a3017';
      x.fillRect(0, 0, W, H);
      for (const lx of [0, W / 2])
        for (let r = 0; r < 7; r++)
          for (let c = 0; c < 2; c++) {
            const px = lx + 14 + c * 54,
              py = 70 + r * 62;
            x.fillStyle = '#3d1f0e';
            x.fillRect(px, py, 46, 52);
            x.fillStyle = '#7a4524';
            x.fillRect(px + 6, py + 6, 34, 40);
            x.fillStyle = '#5a3017';
            x.fillRect(px + 12, py + 12, 22, 28);
          }
      x.fillStyle = '#2a150a';
      x.fillRect(W / 2 - 3, 0, 6, H);
      for (let i = 0; i < 600; i++) {
        x.fillStyle = `rgba(0,0,0,${R() * 0.12})`;
        x.fillRect(R() * W, R() * H, 1, 6 + R() * 20);
      }
    },
    false
  );
  CONCM.door = new THREE.MeshStandardMaterial({ map: doorT, roughness: 0.7 });
}
/** (v1.1.7, code quality) part of concMaterials: basalt ashlar (2.4 m tile): courses of 0.4 m, blocks 0.5-1.2 m, dark grey with brownish blocks, light mortar */
function concMaterialsPart1() {
  const tex = (w, h, draw, rep = true) => {
    const c = mkCanvas(w, h),
      x = c.getContext('2d');
    draw(x, w, h);
    const t = new THREE.CanvasTexture(c);
    t.colorSpace = THREE.SRGBColorSpace;
    if (rep) t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.anisotropy = 4;
    return t;
  };
  const R = mulberry(777);
  // basalt ashlar (2.4 m tile): courses of 0.4 m, blocks 0.5-1.2 m, dark grey with brownish blocks, light mortar
  const ashlar = (dark) =>
    tex(512, 512, (x, W, H) => {
      x.fillStyle = '#6a6259';
      x.fillRect(0, 0, W, H);
      const rows = 6,
        rh = H / rows;
      for (let r = 0; r < rows; r++) {
        let px = -R() * 60;
        while (px < W) {
          const bw = 55 + R() * 150;
          const t = R();
          const base = dark ? (t < 0.35 ? [74, 62, 52] : t < 0.7 ? [56, 52, 49] : [66, 58, 50]) : t < 0.5 ? [120, 104, 90] : [104, 94, 86];
          const k = 0.82 + R() * 0.32;
          x.fillStyle = `rgb(${(base[0] * k) | 0},${(base[1] * k) | 0},${(base[2] * k) | 0})`;
          x.fillRect(px + 2, r * rh + 2, bw - 4, rh - 4);
          for (let s = 0; s < 40; s++) {
            x.fillStyle = `rgba(${R() < 0.5 ? '20,18,16' : '150,135,115'},${0.05 + R() * 0.1})`;
            x.fillRect(px + R() * bw, r * rh + R() * rh, 2 + R() * 7, 2 + R() * 5);
          }
          if (R() < 0.12) {
            x.fillStyle = 'rgba(150,140,90,0.25)';
            x.beginPath();
            x.arc(px + R() * bw, r * rh + R() * rh, 6 + R() * 12, 0, 7);
            x.fill();
          } // lichen
          px += bw;
        }
      }
    });
  CONCM.basalt = new THREE.MeshStandardMaterial({ map: ashlar(true), roughness: 0.95 });
  CONCM.stone = new THREE.MeshStandardMaterial({ map: ashlar(false), roughness: 0.9 }); // lighter mouldings / cornices
  stoneWorld(CONCM.basalt, false, 0.85); // v1.4.1: the grain of the photo of basalt over the painted blocks (02_textures.js)
  stoneWorld(CONCM.stone, false, 0.7);
  CONCM.basalt.userData.texw = CONCM.stone.userData.texw = 'canteria';
  CONCM.plaster = new THREE.MeshStandardMaterial({
    map: tex(256, 256, (x, W, H) => {
      x.fillStyle = '#efe5cc';
      x.fillRect(0, 0, W, H);
      for (let i = 0; i < 2500; i++) {
        x.fillStyle = `rgba(${R() < 0.5 ? '120,100,70' : '255,255,245'},${R() * 0.06})`;
        x.fillRect(R() * W, R() * H, 1 + R() * 4, 1 + R() * 4);
      }
    }),
    roughness: 0.92
  });
  CONCM.white = new THREE.MeshStandardMaterial({ map: CONCM.plaster.map, color: 0xffffff, roughness: 0.9 });
  plasterWorld(CONCM.plaster, 1, 1.7, 'iglesia', 2.4); // v1.4.1: Poly Haven plaster (02_textures.js)
  plasterWorld(CONCM.white, 0, 1.5, 'enlucido', 2.4);
  return { tex, R, ashlar };
}

// ---- geometry buckets: everything is merged per material
function concBuckets() {
  const map = new Map();
  const get = (m) => {
    let b = map.get(m);
    if (!b) map.set(m, (b = { p: [], n: [], u: [] }));
    return b;
  };
  return {
    geo(g, mat, M) {
      if (g.index) g = g.toNonIndexed();
      g.applyMatrix4(M);
      const b = get(mat);
      const P = g.attributes.position.array,
        N = g.attributes.normal.array,
        U = g.attributes.uv ? g.attributes.uv.array : new Float32Array((P.length / 3) * 2);
      for (let i = 0; i < P.length; i++) {
        b.p.push(P[i]);
        b.n.push(N[i]);
      }
      for (let i = 0; i < U.length; i++) b.u.push(U[i]);
      g.dispose();
    },
    // quad a-b-c-d (counter-clockwise seen from outside), uv in metres / s
    quad(mat, a, b, c, d, s = 3) {
      const B = get(mat);
      const e1 = [b[0] - a[0], b[1] - a[1], b[2] - a[2]],
        e2 = [d[0] - a[0], d[1] - a[1], d[2] - a[2]];
      let nx = e1[1] * e2[2] - e1[2] * e2[1],
        ny = e1[2] * e2[0] - e1[0] * e2[2],
        nz = e1[0] * e2[1] - e1[1] * e2[0];
      const nl = Math.hypot(nx, ny, nz) || 1;
      nx /= nl;
      ny /= nl;
      nz /= nl;
      const L = Math.hypot(e1[0], e1[2]) || Math.hypot(e1[0], e1[1], e1[2]);
      const H = Math.hypot(e2[0], e2[1], e2[2]);
      const uv = { a: [0, a[1] / s], b: [L / s, b[1] / s], c: [L / s, c[1] / s], d: [0, d[1] / s] };
      if (Math.abs(e2[1]) < 0.01) {
        uv.c[1] = uv.b[1] + H / s;
        uv.d[1] = uv.a[1] + H / s;
      }
      for (const [P, k] of [
        [a, 'a'],
        [b, 'b'],
        [c, 'c'],
        [a, 'a'],
        [c, 'c'],
        [d, 'd']
      ]) {
        B.p.push(P[0], P[1], P[2]);
        B.n.push(nx, ny, nz);
        B.u.push(uv[k][0], uv[k][1]);
      }
    },
    finish(group) {
      for (const [mat, b] of map) {
        const g = new THREE.BufferGeometry();
        g.setAttribute('position', new THREE.Float32BufferAttribute(b.p, 3));
        g.setAttribute('normal', new THREE.Float32BufferAttribute(b.n, 3));
        g.setAttribute('uv', new THREE.Float32BufferAttribute(b.u, 2));
        g.computeBoundingSphere();
        const m = new THREE.Mesh(g, mat);
        m.castShadow = true;
        m.receiveShadow = true;
        group.add(m);
      }
    }
  };
}
// box with UVs in metres (texture tile = s metres)
function cBox(w, h, d, s = 2.4) {
  const g = new THREE.BoxGeometry(w, h, d);
  const uv = g.attributes.uv;
  const D = [
    [d, h],
    [d, h],
    [w, d],
    [w, d],
    [w, h],
    [w, h]
  ];
  for (let f = 0; f < 6; f++)
    for (let i = 0; i < 4; i++) {
      const k = f * 4 + i;
      uv.setXY(k, (uv.getX(k) * D[f][0]) / s, (uv.getY(k) * D[f][1]) / s);
    }
  return g;
}
// local frame → world matrix
// v0.85.1 (audit v0.81): the helper objects are made once for the whole church, not once per frame of reference
// (it only runs while the city is being built; each call still returns its own matrix, which the caller keeps)
const CF_ = { q: null, e: null, v: null, s: null, one: null };
function cFrame(ox, oy, oz, ang) {
  if (!CF_.q) {
    CF_.q = new THREE.Quaternion();
    CF_.e = new THREE.Euler();
    CF_.v = new THREE.Vector3();
    CF_.s = new THREE.Vector3();
    CF_.one = new THREE.Vector3(1, 1, 1);
  }
  const base = new THREE.Matrix4().makeRotationY(ang).setPosition(ox, oy, oz),
    { q, e, v, s, one } = CF_;
  return (x, y, z, ry = 0, rx = 0, rz = 0, sc = null) => {
    e.set(rx, ry, rz, 'YXZ');
    q.setFromEuler(e);
    return new THREE.Matrix4().compose(v.set(x, y, z), q, sc ? s.set(sc[0], sc[1], sc[2]) : one).premultiply(base);
  };
}
// arch-topped shape (w wide, h total height incl. semicircle), base at y=0
function archShape(w, h, x0 = 0) {
  const s = new THREE.Shape(),
    r = w / 2;
  s.moveTo(x0 - r, 0);
  s.lineTo(x0 + r, 0);
  s.lineTo(x0 + r, h - r);
  s.absarc(x0, h - r, r, 0, Math.PI, false);
  s.lineTo(x0 - r, 0);
  return s;
}
function archPath(w, h, x0 = 0, y0 = 0) {
  const s = new THREE.Path(),
    r = w / 2;
  s.moveTo(x0 - r, y0);
  s.lineTo(x0 + r, y0);
  s.lineTo(x0 + r, y0 + h - r);
  s.absarc(x0, y0 + h - r, r, 0, Math.PI, false);
  s.lineTo(x0 - r, y0);
  return s;
}
function shapeUV(g, w, h, x0 = 0) {
  const p = g.attributes.position,
    uv = g.attributes.uv;
  for (let i = 0; i < p.count; i++) uv.setXY(i, (p.getX(i) - x0 + w / 2) / w, p.getY(i) / h);
  return g;
}
// arched frame (ring) of thickness t around an opening w×h, depth d
function archFrame(w, h, t, d) {
  const s = archShape(w + 2 * t, h + t);
  s.holes.push(archPath(w, h));
  return new THREE.ExtrudeGeometry(s, { depth: d, bevelEnabled: false, curveSegments: 12 });
}

function buildConcepcion(ch) {
  const M = concMaterials();
  const B = concBuckets();
  const root = new THREE.Group();
  const { pts, F, U, V, pip, outN } = buildConcepcionPart1(root, ch);
  let { bot, H1, H2, sE, uE, side } = buildConcepcionPart2(ch, F, U); // >0: head block
  const { Pm, Pe, onCut, T } = buildConcepcionPart3(pts, side);
  // ---------- walls, plinth, eaves
  const wallsOf = (P, top, mat, head) => {
    for (let i = 0; i < P.length; i++) {
      const p = P[i],
        q = P[(i + 1) % P.length];
      const L = Math.hypot(q[0] - p[0], q[1] - p[1]);
      if (L < 0.05) continue;
      // inner face of the tower (church wall hidden inside it)
      if (T && Math.hypot((p[0] + q[0]) / 2 - T.x, (p[1] + q[1]) / 2 - T.z) < T.w * 0.45) continue;
      if (onCut(p) && onCut(q)) {
        if (head) B.quad(mat, [p[0], H1 - 0.4, p[1]], [q[0], H1 - 0.4, q[1]], [q[0], top, q[1]], [p[0], top, p[1]]);
        continue;
      } // step between nave roof and head block
      const [ox, oz] = outN(p, q);
      B.quad(mat, [p[0], bot, p[1]], [q[0], bot, q[1]], [q[0], top, q[1]], [p[0], top, p[1]]);
      // basalt plinth
      const gt = Math.max(heightAt(p[0], p[1]), heightAt(q[0], q[1])) + 1.05,
        o = 0.08;
      const P2 = [p[0] + ox * o, p[1] + oz * o],
        Q2 = [q[0] + ox * o, q[1] + oz * o];
      B.quad(M.basalt, [P2[0], bot, P2[1]], [Q2[0], bot, Q2[1]], [Q2[0], gt, Q2[1]], [P2[0], gt, P2[1]], 2.4);
      B.quad(M.basalt, [P2[0], gt, P2[1]], [Q2[0], gt, Q2[1]], [q[0], gt, q[1]], [p[0], gt, p[1]], 2.4);
      // eaves: plaster moulding + double row of tejas
      const m1 = 0.22,
        m2 = 0.5;
      B.quad(
        M.white,
        [p[0], top - 0.55, p[1]],
        [q[0], top - 0.55, q[1]],
        [q[0] + ox * m1, top - 0.3, q[1] + oz * m1],
        [p[0] + ox * m1, top - 0.3, p[1] + oz * m1],
        1
      );
      B.quad(
        M.tile,
        [p[0] + ox * m1, top - 0.3, p[1] + oz * m1],
        [q[0] + ox * m1, top - 0.3, q[1] + oz * m1],
        [q[0] + ox * m1, top - 0.14, q[1] + oz * m1],
        [p[0] + ox * m1, top - 0.14, p[1] + oz * m1],
        0.5
      );
      B.quad(
        M.tile,
        [p[0] + ox * m1, top - 0.14, p[1] + oz * m1],
        [q[0] + ox * m1, top - 0.14, q[1] + oz * m1],
        [q[0] + ox * m2, top - 0.14, q[1] + oz * m2],
        [p[0] + ox * m2, top - 0.14, p[1] + oz * m2],
        0.5
      );
      B.quad(
        M.tile,
        [p[0] + ox * m2, top - 0.14, p[1] + oz * m2],
        [q[0] + ox * m2, top - 0.14, q[1] + oz * m2],
        [q[0] + ox * m2, top + 0.06, q[1] + oz * m2],
        [p[0] + ox * m2, top + 0.06, p[1] + oz * m2],
        0.5
      );
    }
  };
  buildConcepcionPart4(wallsOf, Pm, H1, M, Pe, H2);
  const { portals } = buildConcepcionPart5(sE, F, uE, H1, Pe, V, B, M);
  const { winAt } = buildConcepcionPart6(T, outN, B, M, Pm, onCut, portals);
  buildConcepcionPart7(Pm, onCut, T, portals, winAt, H1);
  buildConcepcionPart8(portals, outN, B, M);
  buildConcepcionPart9(Pe, onCut, outN, H2, bot, B, M);
  // ---------- the tower
  if (T) {
    const w = T.w,
      x0 = T.x,
      z0 = T.z;
    let y0 = 1e9;
    for (const [sx, sz] of [
      [-1, -1],
      [1, -1],
      [1, 1],
      [-1, 1]
    ])
      y0 = Math.min(y0, heightAt(x0 + (sx * w) / 2, z0 + (sz * w) / 2));
    y0 -= 0.3;
    const fr = cFrame(x0, y0, z0, T.ang);
    const hw = w / 2;
    // which faces are free (the church leans on one) and which one looks west (towards Callejón la Parra)
    const faces = [0, 1, 2, 3].map((k) => {
      const a = (k * Math.PI) / 2 + T.ang;
      const nx = Math.sin(a),
        nz = Math.cos(a);
      return { k, a: (k * Math.PI) / 2, nx, nz, free: !pip(x0 + nx * (hw + 1.2), z0 + nz * (hw + 1.2)) };
    });
    let west = faces[0],
      wd = -2;
    for (const f of faces) {
      if (!f.free) continue;
      const dx = -544 - x0,
        dz = -368 - z0,
        dl = Math.hypot(dx, dz);
      const d = (f.nx * dx + f.nz * dz) / dl;
      if (d > wd) {
        wd = d;
        west = f;
      }
    }
    const onFace = (f, x, y, out = 0) => fr(Math.sin(f.a) * (hw + out) + Math.cos(f.a) * x, y, Math.cos(f.a) * (hw + out) - Math.sin(f.a) * x, f.a);
    const lv = [0, 6.2, 10.4, 14.4, 18.6]; // bodies
    B.geo(cBox(w + 0.4, 1.3, w + 0.4), M.basalt, fr(0, 0.65, 0));
    for (let i = 0; i < 4; i++) {
      const h = lv[i + 1] - lv[i];
      B.geo(cBox(w, h, w), M.basalt, fr(0, lv[i] + h / 2, 0));
      for (const sx of [-1, 1]) for (const sz of [-1, 1]) B.geo(cBox(0.7, h, 0.7), M.basalt, fr(sx * (hw - 0.27), lv[i] + h / 2, sz * (hw - 0.27))); // corner pilasters
      B.geo(cBox(w + 0.55, 0.32, w + 0.55), M.stone, fr(0, lv[i + 1] - 0.05, 0));
      B.geo(cBox(w + 0.3, 0.18, w + 0.3), M.stone, fr(0, lv[i + 1] - 0.3, 0));
    }
    for (const f of faces) {
      if (!f.free) continue;
      // windows with little iron balconies on bodies 2-4 (+ grated window low on body 1)
      const win = (y, ww, hh, balc) => {
        B.geo(shapeUV(new THREE.PlaneGeometry(ww, hh), ww, hh), M.win, onFace(f, 0, y + hh / 2, 0.03));
        for (const [fx, fy, fw, fh] of [
          [0, y + hh + 0.12, ww + 0.5, 0.24],
          [-ww / 2 - 0.12, y + hh / 2, 0.24, hh],
          [ww / 2 + 0.12, y + hh / 2, 0.24, hh]
        ])
          B.geo(cBox(fw, fh, 0.16), M.stone, onFace(f, fx, fy, 0.06));
        if (balc) {
          B.geo(cBox(ww + 0.7, 0.14, 0.55), M.stone, onFace(f, 0, y - 0.07, 0.27));
          B.geo(cBox(ww + 0.6, 0.05, 0.05), M.iron, onFace(f, 0, y + 0.9, 0.52));
          for (let bx = -ww / 2 - 0.25; bx <= ww / 2 + 0.26; bx += 0.14) B.geo(cBox(0.03, 0.9, 0.03), M.iron, onFace(f, bx, y + 0.45, 0.52));
          for (const sx of [-1, 1]) B.geo(cBox(0.05, 0.05, 0.5), M.iron, onFace(f, sx * (ww / 2 + 0.3), y + 0.9, 0.28));
        } else for (let bx = -ww / 2 + 0.12; bx < ww / 2; bx += 0.18) B.geo(cBox(0.035, hh, 0.035), M.iron, onFace(f, bx, y + hh / 2, 0.08));
      };
      win(2.2, 1.0, 1.3, false);
      win(7.4, 1.2, 1.8, true);
      win(11.5, 1.2, 1.8, true);
      // clock (body 4) on the three free faces
      B.geo(cBox(2.1, 2.1, 0.12), M.stone, onFace(f, 0, 16.4, 0.04));
      B.geo(new THREE.CircleGeometry(0.85, 32), M.clock, onFace(f, 0, 16.4, 0.12));
      win(14.7, 0.9, 0.7, false);
    }
    // belfry: two arched openings per side, bells, iron railing
    const bh = 4.2,
      by = lv[4];
    B.geo(cBox(w - 1.4, bh, w - 1.4), M.dark, fr(0, by + bh / 2, 0));
    for (const f of faces) {
      const s = new THREE.Shape();
      s.moveTo(-hw, 0);
      s.lineTo(hw, 0);
      s.lineTo(hw, bh);
      s.lineTo(-hw, bh);
      s.closePath();
      for (const ax of [-1.45, 1.45]) s.holes.push(archPath(1.7, 3.2, ax, 0.45));
      const g = new THREE.ExtrudeGeometry(s, { depth: 0.7, bevelEnabled: false, curveSegments: 10 });
      g.translate(0, 0, -0.7);
      const uv = g.attributes.uv;
      for (let i = 0; i < uv.count; i++) uv.setXY(i, uv.getX(i) / 2.4, uv.getY(i) / 2.4);
      B.geo(g, M.basalt, onFace(f, 0, by, 0));
      for (const ax of [-1.45, 1.45]) {
        B.geo(new THREE.CylinderGeometry(0.28, 0.5, 0.75, 14, 1, true), M.bell, onFace(f, ax, by + 2.2, -0.75));
        B.geo(new THREE.SphereGeometry(0.29, 10, 6, 0, Math.PI * 2, 0, Math.PI / 2), M.bell, onFace(f, ax, by + 2.56, -0.75));
        B.geo(cBox(1.75, 0.05, 0.05), M.iron, onFace(f, ax, by + 1.35, 0.05));
        for (let bx = -0.8; bx <= 0.81; bx += 0.16) B.geo(cBox(0.03, 0.9, 0.03), M.iron, onFace(f, ax + bx, by + 0.9, 0.05));
      }
    }
    const ty = by + bh;
    B.geo(cBox(w + 0.7, 0.45, w + 0.7), M.stone, fr(0, ty + 0.2, 0));
    B.geo(cBox(w + 0.45, 0.25, w + 0.45), M.stone, fr(0, ty - 0.12, 0));
    for (const sx of [-1, 1])
      for (const sz of [-1, 1]) {
        B.geo(cBox(0.45, 0.6, 0.45), M.stone, fr(sx * (hw + 0.1), ty + 0.7, sz * (hw + 0.1)));
        B.geo(new THREE.SphereGeometry(0.26, 10, 8), M.stone, fr(sx * (hw + 0.1), ty + 1.2, sz * (hw + 0.1)));
      }
    // octagonal lantern with arches, cornice, small dome, cross
    const r8 = w * 0.36,
      oh = 3.0,
      oy = ty + 0.42;
    B.geo(new THREE.CylinderGeometry(r8, r8, oh, 8), M.basalt, fr(0, oy + oh / 2, 0, Math.PI / 8));
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      const ap = r8 * Math.cos(Math.PI / 8) + 0.02;
      const g = shapeUV(new THREE.ShapeGeometry(archShape(0.8, 1.9), 8), 0.8, 1.9);
      B.geo(g, M.dark, fr(Math.sin(a) * ap, oy + 0.5, Math.cos(a) * ap, a));
      B.geo(archFrame(0.8, 1.9, 0.14, 0.1), M.stone, fr(Math.sin(a) * (ap - 0.06), oy + 0.5, Math.cos(a) * (ap - 0.06), a));
    }
    B.geo(new THREE.CylinderGeometry(r8 + 0.35, r8 + 0.2, 0.4, 8), M.stone, fr(0, oy + oh + 0.2, 0, Math.PI / 8));
    B.geo(new THREE.SphereGeometry(r8 * 0.92, 16, 8, 0, Math.PI * 2, 0, Math.PI / 2), M.basalt, fr(0, oy + oh + 0.4, 0, 0, 0, 0, [1, 0.8, 1]));
    const top = oy + oh + 0.4 + r8 * 0.75;
    B.geo(new THREE.SphereGeometry(0.22, 10, 8), M.stone, fr(0, top + 0.15, 0));
    B.geo(cBox(0.1, 1.3, 0.1), M.iron, fr(0, top + 0.9, 0));
    B.geo(cBox(0.7, 0.1, 0.1), M.iron, fr(0, top + 1.2, 0));
    // wooden Canarian gallery at the foot of the west face + iron fence with plants
    {
      const f = west;
      B.geo(cBox(4.4, 0.22, 1.2), M.wood, onFace(f, -0.6, 4.3, 0.6));
      B.geo(cBox(4.4, 1.6, 0.08), M.win, onFace(f, -0.6, 5.2, 1.18));
      for (const sx of [-1, 1]) B.geo(cBox(0.08, 1.6, 1.1), M.wood, onFace(f, -0.6 + sx * 2.18, 5.2, 0.62));
      for (let bx = -2.6; bx <= 1.41; bx += 0.55) B.geo(cBox(0.08, 1.6, 0.1), M.wood, onFace(f, bx, 5.2, 1.2));
      B.geo(cBox(4.6, 0.1, 0.1), M.wood, onFace(f, -0.6, 4.75, 1.22));
      B.geo(cBox(4.9, 0.12, 1.5), M.tile, onFace(f, -0.6, 6.15, 0.68, 0, -0.35));
      for (let bx = -hw; bx <= hw + 0.01; bx += 0.15) B.geo(cBox(0.03, 1.4, 0.03), M.iron, onFace(f, bx, 0.7, 1.7));
      for (const y of [0.12, 1.35]) B.geo(cBox(w, 0.05, 0.05), M.iron, onFace(f, 0, y, 1.7));
      B.geo(cBox(w - 0.4, 0.4, 1.3), M.basalt, onFace(f, 0, 0.2, 0.9));
      B.geo(new THREE.IcosahedronGeometry(0.5, 0), new THREE.MeshStandardMaterial({ color: 0x3f6b35, roughness: 1 }), onFace(f, 1.6, 0.6, 0.9));
    }
    // collisions: the tower square
    const C = [
      [-1, -1],
      [1, -1],
      [1, 1],
      [-1, 1]
    ].map(([sx, sz]) => {
      const v = new THREE.Vector3(sx * (hw + 0.2), 0, sz * (hw + 0.2)).applyMatrix4(fr(0, 0, 0));
      return [v.x, v.z];
    });
    for (let i = 0; i < 4; i++) COL.addSeg(C[i][0], C[i][1], C[(i + 1) % 4][0], C[(i + 1) % 4][1]);
    if (west.free) {
      const a = new THREE.Vector3(-hw, 0, 0),
        b = new THREE.Vector3(hw, 0, 0);
      const m1 = onFace(west, -hw, 0, 1.7),
        m2 = onFace(west, hw, 0, 1.7);
      a.set(0, 0, 0).applyMatrix4(m1);
      b.set(0, 0, 0).applyMatrix4(m2);
      COL.addSeg(a.x, a.z, b.x, b.z);
    }
    // story hooks (Boca Papa sits at the foot of the tower, on the side away from the church)
    const tw = { x: x0, z: z0, ang: T.ang, w };
    {
      const o = 7.5,
        nx = x0 - ch.cx,
        nz = z0 - ch.cz,
        nl = Math.hypot(nx, nz) || 1;
      CONC_TOWER.x = x0 + (nx / nl) * o;
      CONC_TOWER.z = z0 + (nz / nl) * o;
    }
    CONC_TOWER.ok = true;
    CONC_TOWER.tw = tw;
    CONC_TOWER.pts = ch.pts;
    CONC_TOWER.y0 = y0;
    CONC_TOWER.h = top + 1.6;
  }
  B.finish(root);
  scene.add(root);
  CONC_TOWER.group = root;
}
/** (v1.1.7, code quality) part of buildConcepcion: ---------- head block: dark basalt pilasters + two rows of windows */
function buildConcepcionPart9(Pe, onCut, outN, H2, bot, B, M) {
  // ---------- head block: dark basalt pilasters + two rows of windows
  for (let i = 0; i < Pe.length; i++) {
    const p = Pe[i],
      q = Pe[(i + 1) % Pe.length];
    const L = Math.hypot(q[0] - p[0], q[1] - p[1]);
    if (L < 2 || (onCut(p) && onCut(q))) continue;
    const [ox, oz] = outN(p, q);
    const ang = Math.atan2(ox, oz);
    const nb = Math.max(1, Math.round(L / 6.5));
    const g0 = Math.min(heightAt(p[0], p[1]), heightAt(q[0], q[1]));
    for (let k = 0; k <= nb; k++) {
      const t = k / nb;
      const x = p[0] + (q[0] - p[0]) * t + ox * 0.12,
        z = p[1] + (q[1] - p[1]) * t + oz * 0.12;
      const ph = H2 - 0.5 - bot;
      B.geo(cBox(0.95, ph, 0.26), M.basalt, cFrame(x, bot + ph / 2, z, ang)(0, 0, 0));
    }
    for (let k = 0; k < nb; k++) {
      const t = (k + 0.5) / nb;
      const x = p[0] + (q[0] - p[0]) * t + ox * 0.04,
        z = p[1] + (q[1] - p[1]) * t + oz * 0.04;
      const fr = cFrame(x, g0, z, ang);
      for (const [y, w, h] of [
        [2.6, 1.3, 0.9],
        [7.6, 1.25, 2.1],
        [10.9, 1.25, 2.1]
      ]) {
        if (g0 + y + h > H2 - 0.8) continue;
        B.geo(shapeUV(new THREE.PlaneGeometry(w, h), w, h), M.win, fr(0, y + h / 2, 0.02));
        for (const [fx, fy, fw, fh] of [
          [0, y - 0.1, w + 0.5, 0.2],
          [0, y + h + 0.1, w + 0.5, 0.22],
          [-w / 2 - 0.13, y + h / 2, 0.26, h],
          [w / 2 + 0.13, y + h / 2, 0.26, h]
        ])
          B.geo(cBox(fw, fh, 0.14), M.basalt, fr(fx, fy, 0.06));
      }
    }
  }
}
/** (v1.1.7, code quality) part of buildConcepcion: ---------- portals */
function buildConcepcionPart8(portals, outN, B, M) {
  // ---------- portals
  for (const po of portals) {
    const [ox, oz] = outN(po.p, po.q);
    const x = po.p[0] + (po.q[0] - po.p[0]) * po.t,
      z = po.p[1] + (po.q[1] - po.p[1]) * po.t;
    const y = heightAt(x, z) - 0.05;
    const fr = cFrame(x, y, z, Math.atan2(ox, oz));
    if (po.kind === 'blind') {
      B.geo(shapeUV(new THREE.ShapeGeometry(archShape(3.6, 5.6), 12), 3.6, 5.6), M.white, fr(0, 0, 0.02));
      B.geo(archFrame(3.6, 5.6, 0.32, 0.22), M.portal, fr(0, 0, -0.02));
      continue;
    }
    B.geo(shapeUV(new THREE.ShapeGeometry(archShape(2.7, 4.7), 12), 2.7, 4.7), M.door, fr(0, 0, 0.04));
    B.geo(archFrame(2.7, 4.7, 0.45, 0.3), M.portal, fr(0, 0, 0));
    for (const sx of [-1, 1]) {
      B.geo(cBox(0.7, 1.1, 0.6), M.portal, fr(sx * 2.15, 0.55, 0.3));
      B.geo(new THREE.CylinderGeometry(0.2, 0.23, 3.6, 12), M.portal, fr(sx * 2.15, 2.9, 0.38));
      B.geo(cBox(0.62, 0.35, 0.62), M.portal, fr(sx * 2.15, 4.85, 0.34));
      B.geo(cBox(2.1, 0.32, 0.55), M.portal, fr(sx * 1.55, 5.95, 0.3, 0, 0, sx * -0.38)); // broken pediment
      B.geo(cBox(0.36, 0.5, 0.36), M.portal, fr(sx * 2.55, 5.55, 0.3));
      B.geo(new THREE.ConeGeometry(0.16, 0.9, 6), M.portal, fr(sx * 2.55, 6.25, 0.3));
      B.geo(new THREE.SphereGeometry(0.12, 8, 6), M.portal, fr(sx * 2.55, 6.75, 0.3));
    }
    B.geo(cBox(5.0, 0.42, 0.62), M.portal, fr(0, 5.25, 0.3));
    B.geo(cBox(1.15, 1.35, 0.32), M.portal, fr(0, 6.2, 0.22));
    B.geo(cBox(0.7, 0.7, 0.36), M.redStone, fr(0, 6.25, 0.26)); // coat of arms
    B.geo(cBox(0.8, 0.45, 0.5), M.portal, fr(0, 7.1, 0.25));
    B.geo(cBox(0.18, 1.2, 0.18), M.portal, fr(0, 7.9, 0.25));
    B.geo(cBox(0.75, 0.16, 0.18), M.portal, fr(0, 8.15, 0.25));
  }
}
/** (v1.1.7, code quality) part of buildConcepcion */
function buildConcepcionPart7(Pm, onCut, T, portals, winAt, H1) {
  for (let i = 0; i < Pm.length; i++) {
    const p = Pm[i],
      q = Pm[(i + 1) % Pm.length];
    const L = Math.hypot(q[0] - p[0], q[1] - p[1]);
    if (L < 7 || (onCut(p) && onCut(q))) continue;
    for (let m = 4; m < L - 3; m += 8.5) {
      const t = m / L;
      const x = p[0] + (q[0] - p[0]) * t,
        z = p[1] + (q[1] - p[1]) * t;
      if (T && Math.hypot(x - T.x, z - T.z) < 7) continue;
      if (portals.some((o) => o.p === p && Math.abs(o.t - t) * L < 3.6)) continue;
      winAt(p, q, t, H1 - 5.6, 1.5, 3.0);
    }
  }
}
/** (v1.1.7, code quality) part of buildConcepcion: portal: on the flank next to the tower (the long edge whose end is nearest to the tower) */
function buildConcepcionPart6(T, outN, B, M, Pm, onCut, portals) {
  const winAt = (p, q, t, y, wdt, ht) => {
    const [ox, oz] = outN(p, q);
    const x = p[0] + (q[0] - p[0]) * t + ox * 0.03,
      z = p[1] + (q[1] - p[1]) * t + oz * 0.03;
    const fr = cFrame(x, y, z, Math.atan2(ox, oz));
    B.geo(shapeUV(new THREE.ShapeGeometry(archShape(wdt, ht), 10), wdt, ht), M.glass, fr(0, 0, 0));
    B.geo(archFrame(wdt, ht, 0.22, 0.14), M.redStone, fr(0, 0, -0.04));
  };
  // portal: on the flank next to the tower (the long edge whose end is nearest to the tower)
  let pe = null;
  if (T) {
    let bd = 1e9;
    for (let i = 0; i < Pm.length; i++) {
      const p = Pm[i],
        q = Pm[(i + 1) % Pm.length];
      const L = Math.hypot(q[0] - p[0], q[1] - p[1]);
      if (L < 14 || (onCut(p) && onCut(q))) continue;
      const d0 = Math.hypot(p[0] - T.x, p[1] - T.z),
        d1 = Math.hypot(q[0] - T.x, q[1] - T.z),
        d = Math.min(d0, d1);
      if (d < 16 && d < bd) {
        bd = d;
        pe = { p, q, L, fromP: d0 < d1 };
      }
    }
  }
  if (pe) {
    const at = (m) => (pe.fromP ? m / pe.L : 1 - m / pe.L);
    portals.push({ p: pe.p, q: pe.q, t: at(3.6), kind: 'portal' }, { p: pe.p, q: pe.q, t: at(10.5), kind: 'blind' });
  }
  // second (side) portal: middle of the longest edge on the other flank
  {
    let best = null,
      bl = 0;
    for (let i = 0; i < Pm.length; i++) {
      const p = Pm[i],
        q = Pm[(i + 1) % Pm.length];
      const L = Math.hypot(q[0] - p[0], q[1] - p[1]);
      if (onCut(p) && onCut(q)) continue;
      if (pe && p === pe.p) continue;
      if (T && Math.min(Math.hypot(p[0] - T.x, p[1] - T.z), Math.hypot(q[0] - T.x, q[1] - T.z)) < 20) continue;
      if (L > bl) {
        bl = L;
        best = { p, q };
      }
    }
    if (best && bl > 20) portals.push({ p: best.p, q: best.q, t: 0.5, kind: 'portal' });
  }
  return { winAt };
}
/** (v1.1.7, code quality) part of buildConcepcion: ---------- raised central nave (clerestory with oculi) over the three naves */
function buildConcepcionPart5(sE, F, uE, H1, Pe, V, B, M) {
  // ---------- raised central nave (clerestory with oculi) over the three naves
  {
    let va = 1e9,
      vb = -1e9;
    for (const p of Pe) {
      va = Math.min(va, V(p));
      vb = Math.max(vb, V(p));
    }
    const vc = (va + vb) / 2,
      hw = Math.min(5.2, (vb - va) * 0.22);
    const uW = (sE > 0 ? F.u0 : F.u1) + sE * 2.5;
    const ua = Math.min(uW, uE),
      ub = Math.max(uW, uE);
    const y0 = H1 - 0.3,
      y1 = H1 + 3.0;
    for (const sv of [-1, 1]) {
      const a = F.W(sv > 0 ? ua : ub, vc + sv * hw),
        b = F.W(sv > 0 ? ub : ua, vc + sv * hw);
      B.quad(M.plaster, [a[0], y0, a[1]], [b[0], y0, b[1]], [b[0], y1, b[1]], [a[0], y1, a[1]]);
      const Ln = ub - ua;
      for (let k = 3; k < Ln - 2; k += 6.5) {
        const u = ua + k;
        const c = F.W(u, vc + sv * (hw + 0.04));
        const fr = cFrame(c[0], (y0 + y1) / 2 + 0.2, c[1], Math.atan2(F.vx * sv, F.vz * sv));
        B.geo(new THREE.CircleGeometry(0.55, 20), M.glass, fr(0, 0, 0.02));
        B.geo(new THREE.TorusGeometry(0.62, 0.11, 6, 20), M.redStone, fr(0, 0, 0.02));
      }
    }
    {
      const uu = sE > 0 ? ua : ub;
      const a = F.W(uu, vc - hw),
        b = F.W(uu, vc + hw);
      const sgn = sE > 0 ? 1 : -1;
      const [p, q] = sgn > 0 ? [b, a] : [a, b];
      B.quad(M.plaster, [p[0], y0, p[1]], [q[0], y0, q[1]], [q[0], y1, q[1]], [p[0], y1, p[1]]);
    }
    gableRoof(F, y1, 2.0, ua, ub, vc - hw, vc + hw);
  }
  // ---------- arched stained-glass windows on the nave walls
  const portals = [];
  return { portals };
}
/** (v1.1.7, code quality) part of buildConcepcion */
function buildConcepcionPart4(wallsOf, Pm, H1, M, Pe, H2) {
  wallsOf(Pm, H1, M.plaster, false);
  wallsOf(Pe, H2, M.white, true);
  const roofOf = (P, top, din) => {
    if (P.length < 3) return;
    let cx = 0,
      cz = 0;
    for (const p of P) {
      cx += p[0];
      cz += p[1];
    }
    cx /= P.length;
    cz /= P.length;
    const A = polyArea(P);
    const Q = P;
    const tris = THREE.ShapeUtils.triangulateShape(
      Q.map((p) => new THREE.Vector2(p[0], p[1])),
      []
    );
    hipRoof(Q, cx, cz, top, Math.abs(A), tris, din);
  };
  roofOf(Pm, H1, 3.2);
  roofOf(Pe, H2, 3.6);
}
/** (v1.1.7, code quality) part of buildConcepcion */
function buildConcepcionPart3(pts, side) {
  const clip = (P, keepHead) => {
    const out = [];
    for (let i = 0; i < P.length; i++) {
      const a = P[i],
        b = P[(i + 1) % P.length];
      const sa = keepHead ? side(a) : -side(a),
        sb = keepHead ? side(b) : -side(b);
      if (sa >= 0) out.push(a);
      if (sa >= 0 !== sb >= 0) {
        const t = sa / (sa - sb);
        out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
      }
    }
    return out;
  };
  const Pm = clip(pts, false),
    Pe = clip(pts, true);
  const onCut = (p) => Math.abs(side(p)) < 0.02;
  const T = CONC_CARVE.ok ? CONC_CARVE : null;
  return { Pm, Pe, onCut, T };
}
/** (v1.1.7, code quality) part of buildConcepcion: head block at the Plaza de la Concepción end */
function buildConcepcionPart2(ch, F, U) {
  const bot = ch.bmin - 0.6,
    H1 = ch.bmax + 10.5,
    H2 = ch.bmax + 14.8;
  // head block at the Plaza de la Concepción end
  const plaza = centroidOfNamedWays('Plaza de la Concepción');
  let sE = 1;
  if (plaza) {
    const e0 = F.W(F.u0, 0),
      e1 = F.W(F.u1, 0);
    sE = Math.hypot(e1[0] - plaza[0], e1[1] - plaza[1]) < Math.hypot(e0[0] - plaza[0], e0[1] - plaza[1]) ? 1 : -1;
  }
  const uEnd = sE > 0 ? F.u1 : F.u0,
    uE = uEnd - sE * 24;
  const side = (p) => sE * (U(p) - uE);
  return { bot, H1, H2, sE, uE, side };
}
/** (v1.1.7, code quality) part of buildConcepcion: outward normal convention (checked once) */
function buildConcepcionPart1(root, ch) {
  root.name = 'La Concepción';
  const pts = ch.pts;
  const n = pts.length;
  const F = axisFrame(pts, ch.cx, ch.cz);
  const U = (p) => (p[0] - ch.cx) * F.ux + (p[1] - ch.cz) * F.uz,
    V = (p) => (p[0] - ch.cx) * F.vx + (p[1] - ch.cz) * F.vz;
  const pip = (x, z) => {
    let c = false;
    for (let i = 0, j = n - 1; i < n; j = i++) {
      const a = pts[i],
        b = pts[j];
      if (a[1] > z !== b[1] > z && x < ((b[0] - a[0]) * (z - a[1])) / (b[1] - a[1]) + a[0]) c = !c;
    }
    return c;
  };
  // outward normal convention (checked once)
  let osg = 1;
  {
    let bi = 0,
      bl = 0;
    for (let i = 0; i < n; i++) {
      const L = Math.hypot(pts[(i + 1) % n][0] - pts[i][0], pts[(i + 1) % n][1] - pts[i][1]);
      if (L > bl) {
        bl = L;
        bi = i;
      }
    }
    const p = pts[bi],
      q = pts[(bi + 1) % n];
    const ox = (q[1] - p[1]) / bl,
      oz = -(q[0] - p[0]) / bl;
    if (pip((p[0] + q[0]) / 2 + ox * 0.8, (p[1] + q[1]) / 2 + oz * 0.8)) osg = -1;
  }
  const outN = (p, q) => {
    const L = Math.hypot(q[0] - p[0], q[1] - p[1]) || 1;
    return [(osg * (q[1] - p[1])) / L, (osg * -(q[0] - p[0])) / L];
  };
  return { pts, F, U, V, pip, outN };
}

// ============ hand-placed houses missing from OpenStreetMap ============
// Casa del hermano de Jonay — Av. San Miguel de Chimisay / Av. El Cardonal (Google Maps 28.452009, -16.298734 →
// game (1591, 3924)). White 2-storey corner house with a small rooftop room (torreta), grey door, black-framed
// windows and a whitewashed boundary wall. Reference photos: docs/referencias/chimisay/
const CUSTOM_HOUSES = [{ name: 'Casa del hermano', x: 1587, z: 3924, ang: Math.atan2(-28, 22), w: 9, d: 7.5, floors: 2, turret: true }];
function buildCustomHouses() {
  const M = concMaterials();
  const B = concBuckets();
  const root = new THREE.Group();
  root.name = 'casas';
  const white = new THREE.MeshStandardMaterial({ map: M.plaster.map, color: 0xffffff, roughness: 0.9 });
  white.color.setRGB(1.08, 1.09, 1.1);
  plasterWorld(white, 0, 1.5, 'enlucido', 2.4); // v1.4.1: Poly Haven plaster
  const grey = new THREE.MeshStandardMaterial({ color: 0x6d7378, roughness: 0.6, metalness: 0.2 });
  const frame = new THREE.MeshStandardMaterial({ color: 0x151515, roughness: 0.5 });
  const glass = new THREE.MeshStandardMaterial({ color: 0x2b3640, roughness: 0.15, metalness: 0.5 });
  const sill = new THREE.MeshStandardMaterial({ color: 0x8e8a84, roughness: 0.8 });
  for (const h of CUSTOM_HOUSES) {
    buildCustomHousesEach(h, B, white, sill, grey, glass, frame);
  }
  B.finish(root);
  scene.add(root);
}
/** (v1.1.7, code quality) the body of a loop of buildCustomHouses, split out of it */
function buildCustomHousesEach(h, B, white, sill, grey, glass, frame) {
  let { y0, fr, fh, H, faces } = buildCustomHousesEachPart1(h, B, white, sill, grey);
  for (const [a, len, dep] of faces) {
    const on = (x, y, o = 0) => fr(Math.sin(a) * (dep / 2 + o) + Math.cos(a) * x, y, Math.cos(a) * (dep / 2 + o) - Math.sin(a) * x, a);
    const nW = Math.max(1, Math.floor(len / 3.2));
    for (let f = 0; f < h.floors; f++)
      for (let k = 0; k < nW; k++) {
        const x = ((k + 0.5) / nW) * len - len / 2;
        if (a === 0 && f === 0 && k === 0) continue;
        const y = f * fh + 1.0 + (f ? 0.2 : 0.3),
          ww = 1.1,
          wh = 1.3;
        B.geo(cBox(ww, wh, 0.04), glass, on(x, y + wh / 2, 0.01));
        for (const [fx, fy, fw, fhh] of [
          [0, y, ww + 0.16, 0.08],
          [0, y + wh, ww + 0.16, 0.08],
          [-ww / 2, y + wh / 2, 0.08, wh],
          [ww / 2, y + wh / 2, 0.08, wh],
          [0, y + wh / 2, 0.05, wh]
        ])
          B.geo(cBox(fw, fhh, 0.08), frame, on(x + fx, fy, 0.04));
        B.geo(cBox(ww + 0.3, 0.07, 0.22), sill, on(x, y - 0.04, 0.1));
      }
    if (a === 0) {
      const x = (0.5 / nW) * len - len / 2;
      B.geo(cBox(1.1, 2.3, 0.06), grey, on(x, 1.15 + 0.35, 0.02));
      B.geo(cBox(1.35, 0.1, 0.5), sill, on(x, 2.85, 0.25));
      B.geo(cBox(1.3, 0.35, 0.6), sill, on(x, 0.17, 0.3));
    }
  }
  // whitewashed boundary wall along the side (garden/patio)
  B.geo(cBox(0.25, 1.6, h.d, 3), white, fr(h.w / 2 + 2.2, 0.8, 0));
  B.geo(cBox(2.2, 1.6, 0.25, 3), white, fr(h.w / 2 + 1.1, 0.8, -h.d / 2));
  B.geo(cBox(0.35, 0.08, h.d, 3), sill, fr(h.w / 2 + 2.2, 1.64, 0));
  // collisions
  const C = [
    [-1, -1],
    [1, -1],
    [1, 1],
    [-1, 1]
  ].map(([sx, sz]) => {
    const v = new THREE.Vector3((sx * h.w) / 2, 0, (sz * h.d) / 2).applyMatrix4(fr(0, 0, 0));
    return [v.x, v.z];
  });
  for (let i = 0; i < 4; i++) COL.addSeg(C[i][0], C[i][1], C[(i + 1) % 4][0], C[(i + 1) % 4][1]);
  {
    const a = new THREE.Vector3(h.w / 2 + 2.2, 0, -h.d / 2).applyMatrix4(fr(0, 0, 0)),
      b = new THREE.Vector3(h.w / 2 + 2.2, 0, h.d / 2).applyMatrix4(fr(0, 0, 0)),
      c = new THREE.Vector3(h.w / 2, 0, -h.d / 2).applyMatrix4(fr(0, 0, 0));
    COL.addSeg(a.x, a.z, b.x, b.z);
    COL.addSeg(c.x, c.z, a.x, a.z);
  }
  BUILD.push({ pts: C, cx: h.x, cz: h.z, top: y0 + H, bmax: y0, style: 1, name: h.name, H });
}
/** (v1.1.7, code quality) part of buildCustomHousesEach: body + plinth + parapet with coping */
function buildCustomHousesEachPart1(h, B, white, sill, grey) {
  let y0 = 1e9;
  for (const [sx, sz] of [
    [-1, -1],
    [1, -1],
    [1, 1],
    [-1, 1]
  ]) {
    const c = Math.cos(h.ang),
      s = Math.sin(h.ang);
    y0 = Math.min(y0, heightAt(h.x + ((sx * h.w) / 2) * c + ((sz * h.d) / 2) * s, h.z - ((sx * h.w) / 2) * s + ((sz * h.d) / 2) * c));
  }
  y0 -= 0.25;
  const fr = cFrame(h.x, y0, h.z, h.ang);
  const fh = 3.0,
    H = h.floors * fh + 0.4;
  // body + plinth + parapet with coping
  B.geo(cBox(h.w, H, h.d, 3), white, fr(0, H / 2, 0));
  B.geo(cBox(h.w + 0.08, 0.7, h.d + 0.08, 2), sill, fr(0, 0.35, 0));
  for (const [px, pz, pw, pd] of [
    [0, h.d / 2 - 0.1, h.w, 0.2],
    [0, -h.d / 2 + 0.1, h.w, 0.2],
    [h.w / 2 - 0.1, 0, 0.2, h.d],
    [-h.w / 2 + 0.1, 0, 0.2, h.d]
  ]) {
    B.geo(cBox(pw, 0.9, pd, 3), white, fr(px, H + 0.45, pz));
    B.geo(cBox(pw + 0.12, 0.08, pd + 0.12, 3), sill, fr(px, H + 0.94, pz));
  }
  B.geo(cBox(h.w - 0.4, 0.1, h.d - 0.4, 3), sill, fr(0, H + 0.05, 0)); // terrace floor
  // rooftop room (torreta) with its own little parapet and a door
  if (h.turret) {
    const tw = 3.2,
      td = 3.0,
      th = 2.6;
    B.geo(cBox(tw, th, td, 3), white, fr(-h.w / 2 + tw / 2 + 0.6, H + th / 2, -h.d / 2 + td / 2 + 0.6));
    B.geo(cBox(tw + 0.12, 0.1, td + 0.12, 3), sill, fr(-h.w / 2 + tw / 2 + 0.6, H + th + 0.05, -h.d / 2 + td / 2 + 0.6));
    B.geo(cBox(0.85, 2.0, 0.06), grey, fr(-h.w / 2 + tw / 2 + 0.6, H + 1.0, -h.d / 2 + td + 0.63));
  }
  // windows (black frames) on the 4 faces, door on the street face (+z local)
  const faces = [
    [0, h.w, h.d],
    [Math.PI, h.w, h.d],
    [Math.PI / 2, h.d, h.w],
    [-Math.PI / 2, h.d, h.w]
  ];
  return { y0, fr, fh, H, faces };
}

// ============ Finca España: pabellón del Complejo Deportivo Islas Canarias (vacío en OSM) ============
// Grey concrete hall next to the football pitch (C. Tacoronte / C. Tinguaro): mono-pitch white roof that overhangs
// the corner, a band of sea-green glass and dark louvres under it, purple pillars on the ground floor and the sign
// over the entrance. Reference photos: docs/referencias/finca_espana/
const PABELLON = { x0: 1905, x1: 1943, z0: 1291, z1: 1349, H: 13 };
function buildPabellon() {
  const M = concMaterials();
  const B = concBuckets();
  const root = new THREE.Group();
  root.name = 'pabellon';
  const mt = (c, r = 0.85, m = 0) => new THREE.MeshStandardMaterial({ color: c, roughness: r, metalness: m, side: THREE.DoubleSide });
  const conc = mt(0x9b9c98, 0.95),
    roof = mt(0xf0f0ec, 0.6),
    sea = new THREE.MeshStandardMaterial({ color: 0x7fc2b4, roughness: 0.15, metalness: 0.4 }),
    louv = mt(0x2b2e31, 0.6, 0.3),
    purple = mt(0x7a3e8e, 0.6),
    glass = new THREE.MeshStandardMaterial({ color: 0x24323c, roughness: 0.1, metalness: 0.5 });
  const { x0, x1, z0, z1, H } = PABELLON;
  let { cx, cz, W, D, g0, fr } = buildPabellonPart1(x0, x1, z0, z1, B, H, conc, sea);
  B.geo(cBox(W + 0.12, 1.2, D + 0.12), louv, fr(0, H - 2.6 + 2.0, 0));
  for (let x = -W / 2; x <= W / 2; x += 0.6) for (const sd of [-1, 1]) B.geo(cBox(0.08, 1.2, 0.25), louv, fr(x, H - 0.6, sd * (D / 2 + 0.12)));
  // mono-pitch roof rising to the north-west corner, overhanging it
  B.geo(cBox(W + 7, 0.5, D + 6), roof, fr(-1.5, H + 0.6, -1.5, 0, 0.05, -0.04));
  for (const [px, pz] of [
    [-W / 2 - 3, -D / 2 - 2.5],
    [-W / 2 - 3, 0],
    [0, -D / 2 - 2.5]
  ]) {
    B.geo(new THREE.CylinderGeometry(0.25, 0.25, H, 10), M.iron, fr(px, H / 2, pz));
    COL.addCirc(cx + px, cz + pz, 0.35);
  }
  // ground floor on C. Tacoronte (north): glazed entrance between purple pillars + sign
  B.geo(cBox(W - 6, 3.2, 0.12), glass, fr(0, 1.8, -D / 2 - 0.05));
  for (let x = -W / 2 + 3; x <= W / 2 - 3; x += 4) B.geo(cBox(0.6, 3.6, 0.6), purple, fr(x, 1.8, -D / 2 - 0.4));
  const sg = bigSign('COMPLEJO DEPORTIVO ISLAS CANARIAS', 18, 1.3, '#ffffff', '#1f4e8c');
  sg.position.set(cx, g0 + 4.6, z0 - 0.7);
  sg.rotation.y = Math.PI;
  root.add(sg);
  for (const [ax, az, bx, bz] of [
    [x0, z0, x1, z0],
    [x1, z0, x1, z1],
    [x1, z1, x0, z1],
    [x0, z1, x0, z0]
  ])
    COL.addSeg(ax, az, bx, bz);
  BUILD.push({
    pts: [
      [x0, z0],
      [x1, z0],
      [x1, z1],
      [x0, z1]
    ],
    cx,
    cz,
    top: g0 + H,
    bmax: g0,
    style: 3,
    name: 'Pabellón Islas Canarias',
    H
  });
  LABELS.push(['Complejo Deportivo Islas Canarias', cx, cz, 2]);
  B.finish(root);
  scene.add(root);
}
/** (v1.1.7, code quality) part of buildPabellon: upper band: sea-green glass + dark louvres all round */
function buildPabellonPart1(x0, x1, z0, z1, B, H, conc, sea) {
  const cx = (x0 + x1) / 2,
    cz = (z0 + z1) / 2,
    W = x1 - x0,
    D = z1 - z0;
  let g0 = 1e9;
  for (const [x, z] of [
    [x0, z0],
    [x1, z0],
    [x1, z1],
    [x0, z1]
  ])
    g0 = Math.min(g0, heightAt(x, z));
  g0 -= 0.3;
  const fr = cFrame(cx, g0, cz, 0);
  B.geo(cBox(W, H - 2.6, D, 3), conc, fr(0, (H - 2.6) / 2, 0));
  // upper band: sea-green glass + dark louvres all round
  B.geo(cBox(W + 0.1, 1.4, D + 0.1), sea, fr(0, H - 2.6 + 0.7, 0));
  return { cx, cz, W, D, g0, fr };
}

// ============ starting corner (El Blanco) + Calle Marqués de Celada ============
