      m.castShadow = im.castShadow;
      m.receiveShadow = im.receiveShadow;
      m.renderOrder = im.renderOrder;
      m.name = 'inst';
      m.matrixAutoUpdate = false;
      m.updateMatrix();
      scene.add(m);
      lodAdd(m, small && !im.userData.tree, im.userData.lo);
