/** (v1.1.7, code quality) part of buildAtrio: patio floor (red tiles) */
function buildAtrioPart2(top, yU, arc, PI, M, r, a, yL) {
  {
    const h = Math.min(7, top - yU - 7.6);
    if (h > 2.5) arc(PI - 0.8, PI + 0.8, yU + 7.5, yU + 7.5 + h, M(atrioCanvas('mural', 512, 512), 0xffffff, 0.9), r - 0.1);
  }
  // patio floor (red tiles)
  {
    const fg = new THREE.CircleGeometry(r - 0.01, 48);
    fg.rotateX(-PI / 2);
    const fl = new THREE.Mesh(fg, new THREE.MeshStandardMaterial({ color: 0xa05a46, roughness: 0.8 }));
    fl.position.set(a.x, yL + 0.03, a.z);
    fl.receiveShadow = true;
    scene.add(fl);
  }
  const stone = [0.56, 0.55, 0.52],
    iron = [0.13, 0.13, 0.14],
    pave = [0.64, 0.62, 0.58];
  const V = (p, y) => [p[0], y, p[1]];
  return { stone, iron, pave, V };
}
/** (v1.1.7, code quality) part of buildAtrio: a piece of the ring (psi from A to B, height y0..y1), seen from inside */
function buildAtrioPart1(a, F, r, top, PI, th) {
  const W = acc(a.x, a.z, 'trim');
  const up = [0, 1, 0];
  const M = (tex, col = 0xffffff, rough = 0.85, emis = 0) =>
    new THREE.MeshStandardMaterial({
      map: tex || null,
      color: col,
      roughness: rough,
      side: THREE.BackSide,
      emissive: emis ? 0xffffff : 0x000000,
      emissiveMap: emis ? tex : null,
      emissiveIntensity: emis
    });
  // a piece of the ring (psi from A to B, height y0..y1), seen from inside
  const arc = (A, B, y0, y1, mat, rr = r) => {
    if (B - A < 1e-3 || y1 - y0 < 0.02) return null;
    const m = new THREE.Mesh(
      new THREE.CylinderGeometry(rr, rr, y1 - y0, Math.max(3, Math.ceil(((B - A) / (2 * PI)) * 56)), 1, true, th(B), B - A),
      mat
    );
    m.position.set(a.x, (y0 + y1) / 2, a.z);
    m.receiveShadow = true;
    scene.add(m);
    return m;
  };
  const mh = Math.asin(Math.min(0.95, (F.hw + 0.15) / r)),
    Y0 = top + 0.4;
  return { W, up, M, arc, mh, Y0 };
}

// ============ v1.0.4: buildings of the Catastro that the OSM lacks, and walls, garden walls and fences ============
// Jonay, 3-nov: «hay muchos huecos que no existen en la realidad» (Callejón Montaraz: «puede que haya huecos dentro pero
// eso no se ve, hay un muro») and «además de los edificios hay que repasar muros y vallas/cercas que rodean jardines y
// zonas como la universidad». DATA.CB and DATA.BW come from tools/catastro_add.py (build.py puts them in the data).

// the parts of buildings of the Catastro that no building of the map covers: into DATA.B like any other building
function addCatastro() {
  const CB = DATA.CB || [];
  let n = 0;
  for (const [fl, c] of CB) {
    let cx = 0,
      cz = 0;
    const k = c.length / 2;
    for (let i = 0; i < c.length; i += 2) {
      cx += c[i];
      cz += c[i + 1];
    }
    cx /= k;
    cz /= k;
    const R = mulberry((Math.round(cx * 7.3) * 92821 + Math.round(cz * 13.1)) | 0),
      r = R();
    const lv = Math.max(1, Math.min(14, fl)),
      hist = isHistoric(cx, cz);
    const style = lv >= 4 ? 2 : hist ? 0 : 1,
      roofT = style === 0 ? (r < 0.7 ? 1 : 0) : style === 1 && r < 0.25 ? 1 : 0;
    DATA.B.push([Math.round((lv * (style === 0 ? 3.6 : 3.1) + 0.6) * 10), style, lv, roofT, -1, Math.floor(R() * 1e6), c]);
    n++;
  }
  console.log('catastro: edificios añadidos', n);
  return n;
}

// garden walls along the street side of the blocks that the game fills with houses along the edge (05q_inicio.js): where
// there is no house, a whitewashed wall closes the courtyards, as in the street (Callejón Montaraz)
function inicioTapias() {
  const out = [];
  if (!INICIO.blocks) return out;
  const cand = (x, z) => {
    const l = [];
    for (const pc of INICIO.parcels) if (Math.abs(pc.cx - x) < 30 && Math.abs(pc.cz - z) < 30) l.push(pc.poly);
    return l;
  };
  for (const P0 of INICIO.blocks) {
    const P = insetPoly(P0, 0.5),
      m = P.length;
    let run = [];
    const flush = () => {
      if (run.length >= 3) {
        let L = 0;
        for (let i = 1; i < run.length; i++) L += Math.hypot(run[i][0] - run[i - 1][0], run[i][1] - run[i - 1][1]);
        if (L >= 2) out.push(['tapia', 0, '', run.flat()]);
      }
      run = [];
    };
    for (let i = 0; i < m; i++) {
      const a = P[i],
        b = P[(i + 1) % m],
        L = Math.hypot(b[0] - a[0], b[1] - a[1]),
        n = Math.max(1, Math.round(L));
      for (let t = 0; t < n; t++) {
        const x = a[0] + ((b[0] - a[0]) * t) / n,
          z = a[1] + ((b[1] - a[1]) * t) / n;
        const inB = cand(x, z).some((p) => pip(x, z, p.flat ? p.flat() : p)) || wallBuildingAt(x, z);
        if (inB) flush();
        else run.push([x, z]);
      }
    }
    flush();
  }
  return out;
}

// v1.0.5 (Jonay: «los muros no deberían dejar pasar entre muro y edificio»): a wall that stops next to a building (it was cut
// there, or the garden wall runs up to a house) goes on into it, past the 0.75 m the facade is drawn inside its plan
// iron railing: a bar on the left of each tile, a rail at the top and one near the bottom (alphaTest cuts the rest)
function railTex() {
  const cv = document.createElement('canvas');
  cv.width = 16;
  cv.height = 64;
  const x = cv.getContext('2d');
  x.fillStyle = '#fff';
  x.fillRect(0, 0, 3, 64);
  x.fillRect(0, 0, 16, 4);
  x.fillRect(0, 55, 16, 3);
  const t = new THREE.CanvasTexture(cv);
  t.wrapS = THREE.RepeatWrapping;
  t.magFilter = THREE.LinearFilter;
  t.anisotropy = 4;
  return t;
}
let WALL_BI = null;
function wallBuildingAt(x, z) {
  // DATA.B in 25 m cells (built once): inAnyBuilding goes through every building
  if (!WALL_BI) {
    WALL_BI = new Map();
    for (const b of DATA.B) {
      const c = b[6];
      if (!c || c.length < 6) continue;
      let x0 = 1e9,
        z0 = 1e9,
        x1 = -1e9,
        z1 = -1e9;
      for (let i = 0; i < c.length; i += 2) {
        x0 = Math.min(x0, c[i]);
        x1 = Math.max(x1, c[i]);
        z0 = Math.min(z0, c[i + 1]);
        z1 = Math.max(z1, c[i + 1]);
      }
      for (let i = Math.floor(x0 / 25); i <= Math.floor(x1 / 25); i++)
        for (let j = Math.floor(z0 / 25); j <= Math.floor(z1 / 25); j++) {
          const k = i * 100000 + j;
          let l = WALL_BI.get(k);
          if (!l) WALL_BI.set(k, (l = []));
          l.push(c);
        }
    }
  }
  const l = WALL_BI.get(Math.floor(x / 25) * 100000 + Math.floor(z / 25));
  if (!l) return false;
  for (const c of l) if (pip(x, z, c)) return true;
  return false;
}
function wallIntoBuildings(c) {
  const o = c.slice(),
    n = o.length;
  const grow = (ix, jx) => {
    // end point ix, the point before it jx
    const x = o[ix],
      z = o[ix + 1],
      dx = x - o[jx],
      dz = z - o[jx + 1],
      L = Math.hypot(dx, dz);
    if (L < 0.05) return;
    for (let t = 0.25; t <= 2.5; t += 0.25)
      if (wallBuildingAt(x + (dx / L) * t, z + (dz / L) * t)) {
        o[ix] = x + (dx / L) * (t + 1);
        o[ix + 1] = z + (dz / L) * (t + 1);
        return;
      }
  };
  grow(0, 2);
  grow(n - 2, n - 4);
  return o;
}
function deadEndFences() {
  const FAST = /V[ií]a de Ronda|Autopista|Autov[ií]a/i,
    isFast = (r) => r[0] <= 2 || FAST.test(r[1] >= 0 ? DATA.S[r[1]] || '' : '');
  const deg = new Map(),
    K = (x, z) => Math.round(x * 2) + ',' + Math.round(z * 2);
  for (const r of DATA.R) {
    const c = r[4];
    for (let i = 0; i < c.length; i += 2) {
      const k = K(c[i], c[i + 1]);
      deg.set(k, (deg.get(k) || 0) + (i === 0 || i === c.length - 2 ? 1 : 2));
    }
  }
  const fastSegs = [];
  for (const r of DATA.R)
    if (isFast(r) && !(r[3] & 6)) {
      const c = r[4];
      for (let i = 0; i + 3 < c.length; i += 2) fastSegs.push([c[i], c[i + 1], c[i + 2], c[i + 3], r[2] / 2]);
    }
  const out = [];
  for (const r of DATA.R) {
    if (isFast(r) || r[0] > 12 || r[3] & 6) continue;
    const c = r[4],
      n = c.length;
    for (const [i, j] of [
      [0, 2],
      [n - 2, n - 4]
    ]) {
      if (deg.get(K(c[i], c[i + 1])) !== 1) continue; // a real dead end
      const x = c[i],
        z = c[i + 1];
      let best = 1e9;
      for (const f of fastSegs) {
        if (Math.abs(f[0] - x) > 60 && Math.abs(f[2] - x) > 60) continue;
        const dx = f[2] - f[0],
          dz = f[3] - f[1],
          L2 = dx * dx + dz * dz || 1,
          t = clamp(((x - f[0]) * dx + (z - f[1]) * dz) / L2, 0, 1);
        best = Math.min(best, Math.hypot(x - f[0] - dx * t, z - f[1] - dz * t) - f[4]);
      }
      if (best > 18) continue;
      const dx = x - c[j],
        dz = z - c[j + 1],
        L = Math.hypot(dx, dz) || 1,
        ux = dx / L,
        uz = dz / L,
        hw = r[2] / 2 + 1.6,
        ex = x - ux * 0.5,
        ez = z - uz * 0.5;
      out.push(['fence', 1.4, 'metal', [ex - uz * hw, ez + ux * hw, ex + uz * hw, ez - ux * hw], true]);
    }
  } // (true: it stands on the carriageway on purpose)
  console.log('vallas al final de calles junto a vías rápidas', out.length);
  return out;
}
const WALLS = { n: 0, km: 0, meshes: [] };
function buildWalls() {
  let { list, nt, KIND, MAT, COLS, CELLS } = buildWallsPart1();
  const { bucket, quad } = buildWallsPart2(CELLS);
  let km = 0,
    n = 0;
  const { pieces } = buildWallsPart3(list);
  for (const [kind, h, mat0, c0] of pieces) {
    const K = KIND[kind];
    if (!K || c0.length < 4) continue;
    const c = wallIntoBuildings(c0);
    const H = h > 0.4 && h < 6 ? h : K[0],
      T = K[1],
      mat = K[2];
    const R = mulberry((Math.round(c[0] * 3) * 7919 + Math.round(c[1] * 3)) | 0);
    const pal = COLS[mat],
      col = pal ? pal[Math.floor(R() * pal.length)] : [1, 1, 1];
    const shade = (k) => col.map((v) => v * k);
    let run = 0;
    // v1.0.6 (Jonay: «tampoco debería haber huecos entre muros, deberían ser continuos»): mitred corners (each vertex offset
    // along the bisector, so the faces of two pieces meet) and the two ends pushed out half a thickness (where two walls of
    // the map meet they overlap instead of leaving a wedge)
    const nv = c.length / 2,
      off = [];
    for (let v = 0; v < nv; v++) {
      const nrm = (a, b) => {
        const dx = c[2 * b] - c[2 * a],
          dz = c[2 * b + 1] - c[2 * a + 1],
          L = Math.hypot(dx, dz) || 1;
        return [-dz / L, dx / L];
      };
      const n1 = v > 0 ? nrm(v - 1, v) : null,
        n2 = v < nv - 1 ? nrm(v, v + 1) : null;
      if (!n1 || !n2) {
        const q = n1 || n2;
        off.push([(q[0] * T) / 2, (q[1] * T) / 2]);
        continue;
      }
      let mx = n1[0] + n2[0],
        mz = n1[1] + n2[1];
      const ml = Math.hypot(mx, mz);
      if (ml < 0.2) {
        off.push([(n1[0] * T) / 2, (n1[1] * T) / 2]);
        continue;
      } // almost turning back: plain
      mx /= ml;
      mz /= ml;
      const cs = Math.max(0.35, mx * n1[0] + mz * n1[1]);
      off.push([(mx * T) / 2 / cs, (mz * T) / 2 / cs]);
    }
    if (T > 0.06 && nv >= 2)
      for (const [e, f] of [
        [0, 1],
        [nv - 1, nv - 2]
      ]) {
        const dx = c[2 * e] - c[2 * f],
          dz = c[2 * e + 1] - c[2 * f + 1],
          L = Math.hypot(dx, dz) || 1;
        c[2 * e] += ((dx / L) * T) / 2;
        c[2 * e + 1] += ((dz / L) * T) / 2;
      }
    for (let i = 0; i + 3 < c.length; i += 2) {
      const ax = c[i],
        az = c[i + 1],
        bx = c[i + 2],
        bz = c[i + 3],
        L = Math.hypot(bx - ax, bz - az);
      if (L < 0.05) continue;
      const oa = off[i / 2],
        ob = off[i / 2 + 1],
        k = Math.max(1, Math.ceil(L / 5));
      km += L; // pieces of up to 5 m following the ground
      let gmin = 1e9,
        gmax = -1e9;
      const b = bucket(mat, ax, az);
      for (let j = 0; j < k; j++) {
        const t0_ = j / k,
          t1_ = (j + 1) / k;
        const x0 = ax + (bx - ax) * t0_,
          z0 = az + (bz - az) * t0_,
          x1 = ax + (bx - ax) * t1_,
          z1 = az + (bz - az) * t1_;
        const ox0 = oa[0] + (ob[0] - oa[0]) * t0_,
          oz0 = oa[1] + (ob[1] - oa[1]) * t0_,
          ox1 = oa[0] + (ob[0] - oa[0]) * t1_,
          oz1 = oa[1] + (ob[1] - oa[1]) * t1_;
        const g0 = heightAt(x0, z0),
          g1 = heightAt(x1, z1);
        gmin = Math.min(gmin, g0, g1);
        gmax = Math.max(gmax, g0, g1);
        const y0 = g0 - 0.4,
          y1 = g1 - 0.4,
          t0 = g0 + H,
          t1 = g1 + H;
        if (mat === 'valla') {
          quad(b, [x0, g0 - 0.03, z0], [x1, g1 - 0.03, z1], [x1, t1, z1], [x0, t0, z0], col, [
            (run + (L * j) / k) / 0.13,
            (run + (L * (j + 1)) / k) / 0.13
          ]);
          continue;
        } // bars every 13 cm
        quad(b, [x0 + ox0, y0, z0 + oz0], [x1 + ox1, y1, z1 + oz1], [x1 + ox1, t1, z1 + oz1], [x0 + ox0, t0, z0 + oz0], shade(0.94)); // one side
        if (T > 0.06) {
          quad(b, [x1 - ox1, y1, z1 - oz1], [x0 - ox0, y0, z0 - oz0], [x0 - ox0, t0, z0 - oz0], [x1 - ox1, t1, z1 - oz1], shade(0.9)); // the other side
          quad(
            b,
            [x0 + ox0, t0, z0 + oz0],
            [x1 + ox1, t1, z1 + oz1],
            [x1 - ox1, t1, z1 - oz1],
            [x0 - ox0, t0, z0 - oz0],
            shade(mat === 'cal' ? 0.8 : 1)
          ); // the top
        }
      }
      if (T > 0.06)
        for (const [ex, ez, s, o, end] of [
          [ax, az, -1, oa, i === 0],
          [bx, bz, 1, ob, i + 4 >= c.length]
        ]) {
          if (!end) continue;
          const g = heightAt(ex, ez); // only the two ends of the wall get a face
          quad(
            b,
            [ex - o[0] * s, g - 0.4, ez - o[1] * s],
            [ex + o[0] * s, g - 0.4, ez + o[1] * s],
            [ex + o[0] * s, g + H, ez + o[1] * s],
            [ex - o[0] * s, g + H, ez - o[1] * s],
            shade(0.86)
          );
        }
      COL.addSeg(ax, az, bx, bz, gmin - 0.5, gmax + H);
      run += L;
    }
    n++;
  }
  buildWallsPart4(CELLS, MAT);
  WALLS.n = n;
  WALLS.km = Math.round(km / 100) / 10;
  console.log('muros y vallas', n, 'tapias del inicio', nt, WALLS.km, 'km', CELLS.size, 'mallas');
  return n;
}
/** (v1.1.7, code quality) part of buildWalls */
function buildWallsPart4(CELLS, MAT) {
  for (const b of CELLS.values()) {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(b.p, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(b.c, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(b.uv, 2));
    g.computeVertexNormals();
    const m = new THREE.Mesh(g, MAT[b.mat]);
    m.castShadow = b.mat !== 'valla';
    m.receiveShadow = true;
    m.userData.muros = true;
    scene.add(m);
    WALLS.meshes.push(m);
  }
}
/** (v1.1.7, code quality) part of buildWalls: v1.0.8 (Jonay: «aquí se choca el coche», Vía de Ronda X 378, Y −270): a wall of the map under a carriageway as the game */
function buildWallsPart3(list) {
  // v1.0.8 (Jonay: «aquí se choca el coche», Vía de Ronda X 378, Y −270): a wall of the map under a carriageway as the game
  // draws it (wider than in the OSM, or raised over the ground) is cut there; it collided unseen under the road
  // v1.1.1 (Jonay, X 498, Y −493: «por aquí no se debería poder acceder a la Vía de Ronda, debería haber vallado»): a
  // street that ends (dead end) next to a fast road it doesn't join gets a metal fence across its end
  try {
    for (const w of deadEndFences()) list.push(w);
  } catch (e) {
    console.error('vallas fin de calle', e);
  }
  const pieces = [];
  const simp = (r) => {
    const o = [r[0], r[1]];
    for (let k = 2; k + 3 < r.length + 2 && k < r.length - 2; k += 2) {
      const ax = o[o.length - 2],
        az = o[o.length - 1],
        bx = r[k],
        bz = r[k + 1],
        ex = r[k + 2],
        ez = r[k + 3];
      const L = Math.hypot(ex - ax, ez - az) || 1;
      if (Math.abs((bx - ax) * (ez - az) - (bz - az) * (ex - ax)) / L > 0.12) o.push(bx, bz);
    }
    o.push(r[r.length - 2], r[r.length - 1]);
    return o;
  }; // back to the corners
  for (const w of list) {
    const [kind, h, mat0, c0, keep] = w;
    let run = [];
    const flush = () => {
      if (run.length >= 4) pieces.push([kind, h, mat0, simp(run)]);
      run = [];
    };
    for (let i = 0; i + 3 < c0.length; i += 2) {
      const ax = c0[i],
        az = c0[i + 1],
        bx = c0[i + 2],
        bz = c0[i + 3],
        L = Math.hypot(bx - ax, bz - az),
        n = Math.max(1, Math.ceil(L / 0.75));
      for (let t = i ? 1 : 0; t <= n; t++) {
        const x = ax + ((bx - ax) * t) / n,
          z = az + ((bz - az) * t) / n;
        if (!keep && onCarriagewayEarly(x, z, 0.4)) flush();
        else run.push(x, z);
      }
    }
    flush();
  }
  return { pieces };
}
/** (v1.1.7, code quality) part of buildWalls */
function buildWallsPart2(CELLS) {
  const CS = 300;
  const bucket = (mat, x, z) => {
    const k = mat + ':' + Math.floor(x / CS) + ',' + Math.floor(z / CS);
    let b = CELLS.get(k);
    if (!b) {
      b = { mat, p: [], c: [], uv: [] };
      CELLS.set(k, b);
    }
    return b;
  };
  const quad = (b, a1, a2, b2, b1, col, uv) => {
    b.p.push(...a1, ...a2, ...b2, ...a1, ...b2, ...b1);
    for (let i = 0; i < 6; i++) b.c.push(...col);
    const [u0, u1] = uv || [0, 0];
    b.uv.push(u0, 0, u1, 0, u1, 1, u0, 0, u1, 1, u0, 1);
  };
  return { bucket, quad };
}
/** (v1.1.7, code quality) part of buildWalls: height (m above the ground), thickness, material */
function buildWallsPart1() {
  const list = (DATA.BW || []).slice();
  let nt = 0;
  try {
    const t = inicioTapias();
    nt = t.length;
    for (const w of t) list.push(w);
  } catch (e) {
    console.error('tapias', e);
  }
  // height (m above the ground), thickness, material
  const KIND = {
    wall: [2.2, 0.3, 'cal'],
    tapia: [2.6, 0.3, 'cal'],
    city_wall: [3.2, 0.6, 'piedra'],
    retaining_wall: [1.1, 0.45, 'piedra'],
    fence: [1.8, 0.05, 'valla'],
    wire_fence: [1.6, 0.04, 'valla'],
    wood_fence: [1.3, 0.07, 'madera'],
    hedge: [1.4, 0.9, 'seto']
  };
  const MAT = {
    cal: plasterWorld(new THREE.MeshStandardMaterial({ color: 0xffffff, vertexColors: true, roughness: 0.95 }), 1, 0.95, 'cal', 2.4), // v1.4.1: whitewash (Poly Haven plaster)
    piedra: (() => {
      const m = new THREE.MeshStandardMaterial({ color: 0xffffff, vertexColors: true, roughness: 1 });
      stoneWorld(m, false); // v1.4.0: stone walls with the photo of basalt (02_textures.js)
      return m;
    })(),
    valla: new THREE.MeshStandardMaterial({
      color: 0x343a36,
      roughness: 0.55,
      metalness: 0.5,
      map: railTex(),
      alphaTest: 0.5,
      side: THREE.DoubleSide
    }), // v1.0.6: iron bars and rails, not a see-through grey panel (Jonay: «¿esto qué es?»)
    madera: new THREE.MeshStandardMaterial({ color: 0x86663f, roughness: 0.9 }),
    seto: new THREE.MeshStandardMaterial({ color: 0xffffff, vertexColors: true, roughness: 1 })
  };
  const COLS = {
    cal: [
      [0.93, 0.91, 0.86],
      [0.95, 0.94, 0.9],
      [0.89, 0.85, 0.77],
      [0.92, 0.88, 0.8]
    ],
    piedra: [
      [0.42, 0.4, 0.38],
      [0.5, 0.47, 0.43],
      [0.36, 0.35, 0.34]
    ],
    seto: [
      [0.22, 0.38, 0.18],
      [0.26, 0.42, 0.2]
    ]
  };
  const CELLS = new Map();
  return { list, nt, KIND, MAT, COLS, CELLS };
}

// ============ Hierba y matojos (v1.3.1) ============
// Jonay (10-nov): «algo de hierba en los descampados». Matas de hierba verde en parques, jardines y zonas de hierba;
// hierba seca y matojos en los descampados (el terreno abierto que no es edificio, calle, plaza, campo ni huerta), y
// de todo un poco en prados y matorral. Los modelos son de Blender (tools/blender/hierba_blender.py, en DATA.ARB.hierba).
// Solo se plantan alrededor de la cámara (celdas de 20 m hasta ~65 m), con una semilla fija por celda: cada sitio
// tiene siempre las mismas matas, y nunca hay más de unas miles a la vez.
const HIERBA = {
  on: false,
  cell: 40,
  radius: 110,
  cx: null,
  cz: null,
  cache: new Map(),
  meshes: null,
  kinds: ['hierba_verde', 'hierba_seca', 'matojo']
};

// the class of the ground at every 4 m: 0 open land (descampado), 1 green (park, garden, grass), 2 meadow/scrub,
// 3 nothing (buildings, streets, paths, squares, pitches, water, fields, the paved old town)
function hierbaRaster() {
  const W = 2048,
    H = Math.round((W * SPLAT.h) / SPLAT.w),
    sx = W / SPLAT.w,
    c = mkCanvas(W, H),
    x = c.getContext('2d');
  const P = (px, pz) => [(px - SPLAT.x0) * sx, (pz - SPLAT.z0) * sx];
  const poly = (coords, fill, stroke = 0) => {
    x.beginPath();
    for (let i = 0; i < coords.length; i += 2) {
      const p = P(coords[i], coords[i + 1]);
      i ? x.lineTo(p[0], p[1]) : x.moveTo(p[0], p[1]);
    }
    x.closePath();
    x.fillStyle = fill;
    x.fill();
    if (stroke) {
      x.lineWidth = stroke * sx;
      x.strokeStyle = fill;
      x.stroke();
    }
  };
  const C = ['rgb(0,0,0)', 'rgb(85,0,0)', 'rgb(170,0,0)', 'rgb(255,0,0)'],
    AT = DATA.AT;
  x.fillStyle = C[0];
  x.fillRect(0, 0, W, H);
  poly(HIST_CORE.flat(), C[3]); // (the paved old town; its parks and gardens go on top)
  for (const a of DATA.A) {
    const t = AT[a[0]];
    if (['park', 'garden', 'grass', 'playground'].includes(t)) poly(a[2], C[1]);
    else if (['meadow', 'scrub'].includes(t)) poly(a[2], C[2]);
    else if (['pitch', 'water', 'farmland', 'cemetery', 'square', 'parking', 'sports', 'forest', 'orchard'].includes(t)) poly(a[2], C[3]);
  }
  for (const b of DATA.B) poly(b[6], C[3], 6);
  x.lineCap = 'round';
  x.strokeStyle = C[3];
  for (const r of DATA.R) {
    const cc = r[4];
    if (cc.length < 4) continue;
    x.lineWidth = (r[0] <= 13 ? r[2] + 5 : Math.max(2.4, r[2]) + 1.5) * sx; // (v1.3.2: the pavements too, 2.1 m each side, and the whole path)
    x.beginPath();
    for (let i = 0; i < cc.length; i += 2) {
      const p = P(cc[i], cc[i + 1]);
      i ? x.lineTo(p[0], p[1]) : x.moveTo(p[0], p[1]);
    }
    x.stroke();
  }
  // v1.3.2 (Jonay, Av. de los Menceyes X 251, Y 854: «más hierba en edificios, vías del tren»): none on the tram track
  // and its stops (the track, 7.2 m, and the platforms beside it)
  if (DATA.T && DATA.T.length > 3) {
    x.lineWidth = 16 * sx;
    x.beginPath();
    for (let i = 0; i < DATA.T.length; i += 2) {
      const p = P(DATA.T[i], DATA.T[i + 1]);
      i ? x.lineTo(p[0], p[1]) : x.moveTo(p[0], p[1]);
    }
    x.stroke();
  }
  const d = x.getImageData(0, 0, W, H).data,
    R = new Uint8Array(W * H);
  for (let i = 0; i < R.length; i++) {
    const v = d[i * 4];
    R[i] = v < 40 ? 0 : v < 125 ? 1 : v < 210 ? 2 : 3;
  }
  // v1.3.2 (Jonay: «la hierba no puede crecer en las aceras ni en las carreteras ni adoquines», Av. Leonardo Torriani
  // X 113, Y 432): in town the open land between a street and the façades is paved (wide pavements, forecourts), not
  // a descampado: no open-land grass within 12 m of a street or 8 m of a building (parks and gardens keep theirs)
  x.fillStyle = '#000';
  x.fillRect(0, 0, W, H);
  x.strokeStyle = '#fff';
  for (const b of DATA.B) {
    const cc = b[6];
    x.lineWidth = 16 * sx;
    x.beginPath();
    for (let i = 0; i < cc.length; i += 2) {
      const p = P(cc[i], cc[i + 1]);
      i ? x.lineTo(p[0], p[1]) : x.moveTo(p[0], p[1]);
    }
    x.closePath();
    x.stroke();
  }
  for (const r of DATA.R) {
    const cc = r[4];
    if (cc.length < 4 || r[0] > 13) continue;
    x.lineWidth = (r[2] + 24) * sx;
    x.beginPath();
    for (let i = 0; i < cc.length; i += 2) {
      const p = P(cc[i], cc[i + 1]);
      i ? x.lineTo(p[0], p[1]) : x.moveTo(p[0], p[1]);
    }
    x.stroke();
  }
  const u = x.getImageData(0, 0, W, H).data;
  for (let i = 0; i < R.length; i++) if (R[i] === 0 && u[i * 4] > 127) R[i] = 3;
  return { W, H, sx, R };
}
function hierbaClass(x, z) {
  const M = HIERBA.raster,
    i = Math.floor((x - SPLAT.x0) * M.sx),
    j = Math.floor((z - SPLAT.z0) * M.sx);
  return i < 0 || j < 0 || i >= M.W || j >= M.H ? 3 : M.R[j * M.W + i];
}
// the tufts of one cell: [kind, x, y, z, turn, size] (fixed seed per cell)
function hierbaCell(ci, cj) {
  const key = ci + ',' + cj;
  let L = HIERBA.cache.get(key);
  if (L) return L;
  L = [];
  const rnd = mulberry((ci * 73856093) ^ (cj * 19349663)),
    S = HIERBA.cell;
  // tries per cell (the class decides how many become tufts): green dense, open land in patches
  for (let k = 0; k < 380; k++) {
    const x = ci * S + rnd() * S,
      z = cj * S + rnd() * S,
      cl = hierbaClass(x, z);
    if (cl === 3 || !inPlayArea(x, z, 2)) continue;
    const patch = 0.5 + 0.5 * Math.sin(x * 0.11 + Math.sin(z * 0.07) * 2.3) * Math.cos(z * 0.09 - x * 0.03);
    let kind = -1;
    const u = rnd();
    if (cl === 1) kind = u < 0.7 ? 0 : -1;
    else if (cl === 2) kind = u < 0.35 ? 1 : u < 0.55 ? 0 : u < 0.62 ? 2 : -1;
    else kind = patch < 0.4 ? -1 : u < 0.5 ? 1 : u < 0.56 ? 2 : -1;
    if (kind < 0) continue;
    // v1.3.2: the 4 m raster is coarse: each tuft checked for real off streets and pavements, the tram and buildings
    if (onAnyPaved(x, z, 2.6) || nearTram(x, z, 6) || treeInBuilding(x, z)) continue;
    L.push([kind, x, heightAt(x, z), z, rnd() * 6.28, kind === 2 ? 0.8 + rnd() * 0.7 : 1.0 + rnd() * 0.8]);
  }
  HIERBA.cache.set(key, L);
  if (HIERBA.cache.size > 900) HIERBA.cache.delete(HIERBA.cache.keys().next().value);
  return L;
}
function buildHierba() {
  const H = DATA.ARB && DATA.ARB.hierba;
  if (!H) return;
  HIERBA.raster = hierbaRaster();
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, side: THREE.DoubleSide });
  const CAP = [12000, 9000, 1500];
  HIERBA.meshes = HIERBA.kinds.map((k, i) => {
    const g = arbGeo(H[k]),
      m = new THREE.InstancedMesh(g, mat, CAP[i]);
    m.count = 0;
    m.castShadow = false;
    m.receiveShadow = true;
    m.frustumCulled = false; // (the instances move around the camera; the bounding sphere would go stale)
    m.userData.noMerge = true; // (05w_optimiza.js must not split it into fixed cells)
    m.name = 'hierba';
    scene.add(m);
    return m;
  });
  HIERBA.on = true;
  updateHierba(true);
}
function updateHierba(force) {
  if (!HIERBA.on) return;
  const S = HIERBA.cell,
    p = camera.position,
    ci = Math.floor(p.x / S),
    cj = Math.floor(p.z / S);
  if (!force && ci === HIERBA.cx && cj === HIERBA.cz) return;
  HIERBA.cx = ci;
  HIERBA.cz = cj;
  const n = Math.ceil(HIERBA.radius / S),
    o = HIERBA.o || (HIERBA.o = new THREE.Object3D()),
    cnt = [0, 0, 0];
  for (let a = -n; a <= n; a++)
    for (let b = -n; b <= n; b++) {
      if ((a * a + b * b) * S * S > (HIERBA.radius + S) * (HIERBA.radius + S)) continue;
      for (const t of hierbaCell(ci + a, cj + b)) {
        const m = HIERBA.meshes[t[0]];
        if (cnt[t[0]] >= m.instanceMatrix.count) continue;
        o.position.set(t[1], t[2], t[3]);
        o.rotation.set(0, t[4], 0);
        o.scale.setScalar(t[5]);
        o.updateMatrix();
        m.setMatrixAt(cnt[t[0]]++, o.matrix);
      }
    }
  HIERBA.meshes.forEach((m, i) => {
    m.count = cnt[i];
    m.instanceMatrix.needsUpdate = true;
  });
}

// ============ humans & vehicle meshes ============
// v1.2.8 (Jonay, after the cars went 5 % down: «reduce todos los pj un 5 % también»): every person (player, people in the
// street, mission characters) is drawn 5 % smaller; the mission people keep their sizes relative to the rest
const HUMAN_SCALE = 0.95;
const matCache = new Map();
function M(color, rough = 0.8, metal = 0, extra) {
  const k = color + ':' + rough + ':' + metal + (extra ? JSON.stringify(extra) : '');
  let m = matCache.get(k);
  if (!m) {
    m = new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: metal, ...(extra || {}) });
    matCache.set(k, m);
  }
  return m;
}
const GEO = {
  capsule: (r, l) => new THREE.CapsuleGeometry(r, l, 4, 8)
};
const SKIN = [0xf1c7a5, 0xe0ac86, 0xc68b63, 0x9a6444, 0x6e4630, 0xf5d3bb];
const SHIRT = [0xffffff, 0x1f3b73, 0xb3261e, 0x2e7d32, 0xf2c14e, 0x333333, 0x7b4b94, 0x4fa3d1, 0xe07a5f, 0x9e9e9e, 0x0f766e, 0xf4a261];
const PANTS = [0x2b3a55, 0x1d1d1d, 0x4a4036, 0x6b705c, 0x3a506b, 0x8d7b68, 0x222831];
const HAIR = [0x1a1410, 0x3b2a1e, 0x6b4a2b, 0xb58b52, 0x8c8c8c, 0x0d0d0d];
function makeHumanLegacy(o = {}) {
  const skin = o.skin ?? pick(SKIN),
    shirt = o.shirt ?? pick(SHIRT),
    pants = o.pants ?? pick(PANTS),
    hair = o.hair ?? pick(HAIR);
  const root = new THREE.Group();
  root.userData.noMerge = true;
  /* v0.77: never fused (05w_optimiza.js) */ const body = new THREE.Group();
  const { mSkin, mShirt, mPants, mShoe, mHair, hips } = makeHumanLegacyPart1(root, body, o, skin, shirt, pants, hair);
  const { torso, head } = makeHumanLegacyPart2(hips, mShirt, mSkin, o, mHair);
  const limb = (parent, x, y, r1, l1, r2, l2, m1, m2, endGeo, endMat) => {
    const p = new THREE.Group();
    p.position.set(x, y, 0);
    parent.add(p);
    const u = new THREE.Mesh(GEO.capsule(r1, l1), m1);
    u.position.y = -l1 / 2 - r1 * 0.3;
    p.add(u);
    const j = new THREE.Group();
    j.position.y = -l1 - r1 * 0.5;
    p.add(j);
    const lo = new THREE.Mesh(GEO.capsule(r2, l2), m2);
    lo.position.y = -l2 / 2 - r2 * 0.3;
    j.add(lo);
    const e = new THREE.Mesh(endGeo, endMat);
    e.position.y = -l2 - r2 * 0.6;
    j.add(e);
    if (endGeo.type === 'BoxGeometry') e.position.z = 0.05;
    return { p, j, e };
  };
  const armL = limb(
    torso,
    -0.23,
    0.48,
    0.055,
    0.22,
    0.045,
    0.2,
    o.shortSleeve === false ? mShirt : mShirt,
    mSkin,
    new THREE.SphereGeometry(0.05, 8, 6),
    mSkin
  );
  const armR = limb(torso, 0.23, 0.48, 0.055, 0.22, 0.045, 0.2, mShirt, mSkin, new THREE.SphereGeometry(0.05, 8, 6), mSkin);
  const legL = limb(hips, -0.1, -0.05, 0.08, 0.34, 0.065, 0.34, mPants, mPants, new THREE.BoxGeometry(0.11, 0.08, 0.26), mShoe);
  const legR = limb(hips, 0.1, -0.05, 0.08, 0.34, 0.065, 0.34, mPants, mPants, new THREE.BoxGeometry(0.11, 0.08, 0.26), mShoe);
  armL.p.rotation.z = 0.08;
  armR.p.rotation.z = -0.08;
  root.traverse((m) => {
    if (m.isMesh) {
      m.castShadow = true;
    }
  });
  ACTORS.set(root, { r: 170, dr: 40, thr: 0.07 }); // v1.0.0
  const H = { root, body, hips, torso, head, armL, armR, legL, legR, phase: Math.random() * 6, pose: 'walk' };
  return H;
}
/** (v1.1.7, code quality) part of makeHumanLegacy */
function makeHumanLegacyPart2(hips, mShirt, mSkin, o, mHair) {
  const torso = new THREE.Group();
  hips.add(torso);
  const chest = new THREE.Mesh(GEO.capsule(0.17, 0.3), mShirt);
  chest.position.y = 0.3;
  chest.scale.set(1.08, 1, 0.72);
  torso.add(chest);
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.06, 0.1, 8), mSkin);
  neck.position.y = 0.58;
  torso.add(neck);
  const head = new THREE.Group();
  head.position.y = 0.7;
  torso.add(head);
  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 12), mSkin);
  skull.scale.set(0.9, 1.05, 1);
  head.add(skull);
  const hairM = new THREE.Mesh(new THREE.SphereGeometry(0.128, 16, 10, 0, Math.PI * 2, 0, o.longHair ? Math.PI * 0.75 : Math.PI * 0.5), mHair);
  hairM.position.y = 0.015;
  hairM.position.z = -0.01;
  head.add(hairM);
  if (o.longHair) {
    const h2 = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.25, 0.08), mHair);
    h2.position.set(0, -0.08, -0.08);
    head.add(h2);
  }
  const nose = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.04, 0.04), mSkin);
  nose.position.set(0, -0.01, 0.12);
  head.add(nose);
  const eyeM = M(0x111111, 0.3);
  [-0.04, 0.04].forEach((x) => {
    const e = new THREE.Mesh(new THREE.SphereGeometry(0.014, 6, 6), eyeM);
    e.position.set(x, 0.02, 0.105);
    head.add(e);
  });
  if (o.cap) {
    const c = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.13, 0.07, 14), M(o.cap, 0.8));
    c.position.y = 0.08;
    head.add(c);
    const v = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.015, 0.12), M(o.cap, 0.8));
    v.position.set(0, 0.05, 0.14);
    head.add(v);
  }
  return { torso, head };
}
/** (v1.1.7, code quality) part of makeHumanLegacy */
function makeHumanLegacyPart1(root, body, o, skin, shirt, pants, hair) {
  root.add(body);
  const s = o.scale ?? rnd(0.92, 1.06);
  body.scale.setScalar(s * HUMAN_SCALE);
  const mSkin = M(skin, 0.7),
    mShirt = M(shirt, 0.9),
    mPants = M(pants, 0.9),
    mShoe = M(o.shoes ?? pick([0x111111, 0xeeeeee, 0x5a3b22]), 0.6),
    mHair = M(hair, 0.9);
  const hips = new THREE.Group();
  hips.position.y = 0.95;
  body.add(hips);
  const pelvis = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.2, 0.2), mPants);
  hips.add(pelvis);
  return { mSkin, mShirt, mPants, mShoe, mHair, hips };
}
function animHumanLegacy(H, dt, speed, state = 'ground') {
  // speed m/s
  const b = H;
  if (state === 'down') {
    b.body.rotation.x = lerp(b.body.rotation.x, -Math.PI / 2, 0.2);
    b.body.position.y = lerp(b.body.position.y, 0.2, 0.2);
    return;
  }
  b.body.rotation.x = lerp(b.body.rotation.x, 0, 0.2);
  b.body.position.y = lerp(b.body.position.y, 0, 0.2);
  if (state === 'air') {
    b.legL.p.rotation.x = -0.6;
    b.legL.j.rotation.x = 0.9;
    b.legR.p.rotation.x = 0.2;
    b.legR.j.rotation.x = 0.4;
    b.armL.p.rotation.x = -2.2;
    b.armR.p.rotation.x = -2.2;
    return;
  }
  const run = clamp((speed - 2) / 4, 0, 1);
  b.phase += dt * (speed > 0.1 ? 2.2 + speed * 1.25 : 0);
  const a = speed > 0.1 ? 0.45 + run * 0.45 : 0;
  const s = Math.sin(b.phase),
    c = Math.cos(b.phase);
  b.legL.p.rotation.x = s * a;
  b.legR.p.rotation.x = -s * a;
  b.legL.j.rotation.x = Math.max(0, -c) * a * 1.6 + 0.05;
  b.legR.j.rotation.x = Math.max(0, c) * a * 1.6 + 0.05;
  b.armL.p.rotation.x = -s * a * 0.9;
  b.armR.p.rotation.x = s * a * 0.9;
  b.armL.j.rotation.x = -0.2 - run * 1.1;
  b.armR.j.rotation.x = -0.2 - run * 1.1;
  b.torso.rotation.x = run * 0.22;
  b.torso.rotation.y = s * 0.08 * a;
  b.hips.position.y = 0.95 + Math.abs(c) * 0.04 * a - run * 0.04 + (speed < 0.1 ? Math.sin(performance.now() / 700) * 0.005 : 0);
}

