  Urbano: 155,
  Utilitario: 175,
  Compacto: 200,
  Berlina: 190,
  Crossover: 180,
  SUV: 190,
  Todoterreno: 170,
  'Pick-up': 165,
  Furgoneta: 160,
  'Furgón': 145,
  'Camión': 120,
  'Grúa': 120,
  'Camión de basura': 100,
  Emergencias: 145,
  'Agrícola': 40,
  Taxi: 185,
  Patrulla: 200,
  Deportivo: 200,
  Scooter: 100,
  Maxiscooter: 150,
  Naked: 200,
  Ciclomotor: 60
