    gancho1: { tl: -10, sF: 172, eF: -20, sB: 30, eB: -100, hF: 30, kF: -40, hB: -10, kB: -60, dy: -4 },
    spinA: { tl: -6, sF: 120, eF: -20, sB: 110, eB: -20, hF: 95, kF: -4, hB: 10, kB: -40, dy: -6 },
    spinB: { tl: 6, sF: 100, eF: -30, sB: 120, eB: -30, hF: 20, kF: -60, hB: 95, kB: -4, dy: -6 },
