// ============ BKSHEET (v0.99.4, Jonay: «el basket perfecto, aplica ya»): the basketball players drawn with the
// GandalfHardcore pack (tank top), each one built once from his look (skin, jersey, shorts, hair, beard) out of the
// layers of BK_DATA, and the frame of the sheet for each state of 09f_basket2d.js. Until the layers have loaded the
// game draws its old players.
const BKSHEET = (() => {
  const IM = {};
  let loaded = 0,
    total = 0;
  function img(src) {
    if (!IM[src]) {
      const im = new Image();
      total++;
      im.onload = () => {
        loaded++;
      };
      im.src = src;
      IM[src] = im;
    }
    return IM[src];
  }
  /** starts loading the layers; true once they are all in */
  function ready() {
    if (!total) {
      for (const k in BK_DATA.skins) img(BK_DATA.skins[k].src);
      img(BK_DATA.shorts);
      img(BK_DATA.shirt);
      img(BK_DATA.shoes);
      for (const k in BK_DATA.hair) img(BK_DATA.hair[k]);
    }
    return loaded === total;
  }
  const rgb = (n, d) => {
    const v = (n ?? d) >>> 0;
    return [(v >> 16) & 255, (v >> 8) & 255, v & 255];
  };
  const mul = (c, f) => c.map((v) => Math.max(0, Math.min(255, Math.round(f <= 1 ? v * f : v + (255 - v) * (f - 1)))));
  const ramp = (c) => [mul(c, 0.5), mul(c, 0.72), c, mul(c, 1.25)]; // tones 0–3 with the colour as the third
  const rampTop = (c) => [mul(c, 0.45), mul(c, 0.66), mul(c, 0.84), c]; // the jersey: its main tone (3) is the colour
  /** a layer of tone indices painted with a ramp onto x */
  function tinted(x, src, R) {
    const im = IM[src],
      t = document.createElement('canvas');
    t.width = im.width;
    t.height = im.height;
    const g = t.getContext('2d');
    g.drawImage(im, 0, 0);
    const d = g.getImageData(0, 0, t.width, t.height),
      a = d.data;
    for (let i = 0; i < a.length; i += 4) {
      if (!a[i + 3] || (a[i] === 19 && a[i + 1] === 19 && a[i + 2] === 28)) continue;
      const q = R[Math.min(3, a[i] >> 6)];
      a[i] = q[0];
      a[i + 1] = q[1];
      a[i + 2] = q[2];
    }
    g.putImageData(d, 0, 0);
    x.drawImage(t, 0, 0);
  }
  const C = new Map(),
    AC = new Map();
  const keyOf = (look, seed) =>
    JSON.stringify([look.skin, look.shirt, look.pants, look.hair, look.hairStyle, look.beard, look.shoes, hairOf(look, seed)]);
  /** v0.99.6 (Jonay: «deberían ser con distintos aspectos, son todos iguales»): the pack has 4 skins and 3 hair layers;
   *  most of the game's hair styles (parted, long, simple…) fell on the same short hair, so those take one by the
   *  player (seed): short, afro, beard or shaved */
  function hairOf(look, seed) {
    const s = look.hairStyle || '';
    if (/afro/i.test(s)) return 'afro';
    if (look.beard) return 'beard';
    if (/buzz|fade|bald/i.test(s)) return null;
    if (look.hair === undefined && !seed) return null;
    return seed ? ['short', 'afro', 'beard', 'short', null, 'beard'][seed % 6] : 'short';
  }
  /** the sheet (800 × 448, frames of 80 × 64 facing left) of a look, built once */
  function sheet(look, seed = 0) {
    const key = keyOf(look, seed);
    if (C.has(key)) return C.get(key);
    const c = document.createElement('canvas');
    c.width = 800;
    c.height = 448;
    const x = c.getContext('2d');
    const sk = rgb(look.skin, 0xd9a47c);
    let best = null,
      bd = Infinity;
    for (const k in BK_DATA.skins) {
      const q = BK_DATA.skins[k].col,
        d = (q[0] - sk[0]) ** 2 + (q[1] - sk[1]) ** 2 + (q[2] - sk[2]) ** 2;
      if (d < bd) {
        bd = d;
        best = k;
      }
    }
    x.drawImage(IM[BK_DATA.skins[best].src], 0, 0);
    tinted(x, BK_DATA.shorts, ramp(rgb(look.pants, 0x333344)));
    x.drawImage(IM[BK_DATA.shoes], 0, 0);
    tinted(x, BK_DATA.shirt, rampTop(rgb(look.shirt, 0x777777)));
    const hs = hairOf(look, seed);
    if (hs) tinted(x, BK_DATA.hair[hs], ramp(rgb(look.hair, 0x222222)));
    C.set(key, c);
    return c;
  }
  /** v0.99.6: the new animations of a look (BK_ANIM: tiro, robo, rebote, tapon, m360, molino, espaldas, piernas): a
   *  strip of 80 × 64 frames built once from its sheet with the pixel map */
  function anim(look, seed = 0) {
    const key = keyOf(look, seed);
    if (AC.has(key)) return AC.get(key);
    const sh = sheet(look, seed),
      M = BK_ANIM.map,
      n = M.length,
      W = 80 * n,
      sd = sh.getContext('2d').getImageData(0, 0, 800, 448).data;
    const c = document.createElement('canvas');
    c.width = W;
    c.height = 64;
    const x = c.getContext('2d'),
      od = x.createImageData(W, 64),
      o = od.data;
    M.forEach((rr, i) => {
      for (let k = 0; k < rr.length; k += 5) {
        const y = rr[k],
          x0 = rr[k + 1],
          m = rr[k + 2],
          s0 = rr[k + 3],
          t0 = rr[k + 4];
        for (let j = 0; j < m; j++) {
          const si = (t0 * 800 + s0 + j) * 4,
            di = (y * W + i * 80 + x0 + j) * 4;
          o[di] = sd[si];
          o[di + 1] = sd[si + 1];
          o[di + 2] = sd[si + 2];
          o[di + 3] = sd[si + 3];
        }
      }
    });
    x.putImageData(od, 0, 0);
    AC.set(key, c);
    return c;
  }
  /** [row, frame] for a state key of the game (idle0, walk2, drib1, jump, shoot, dunk, jab1, defend, ko, win) */
  function frame(k, p, t, dunk) {
    if (dunk) return [4, 1];
    if (k === 'ko') return [6, 9];
    if (k === 'shoot') return [4, 0];
    if (k === 'jab1') return [5, 3];
    if (k === 'win') return [4, Math.floor(t * 6) % 4];
    if (k === 'jump') return (p.vy || 0) > 0 ? [3, 2] : [4, 1];
    if (k === 'defend') return [5, 1];
    if (k.startsWith('walk') || k.startsWith('drib')) return [2, Math.floor((p.walkT || 0) * 4.4) % 8];
    return [0, Math.floor(t * 5) % 5];
  }
  /** v1.1.8 (auditor): the layers start loading now; their images */
  const preload = () => (ready(), Object.values(IM));
  return { ready, sheet, anim, frame, A: BK_ANIM.meta, preload };
})();

// ============ «JETA JAM»: 2D basketball, 3 vs 3 since v0.84 (2 vs 2 before), in the style of the 90s arcade games (v0.65) ============
// Side view of the court, the same pixel-art sprites as the 2D fight (made from the players' real clothes). You and a
// friend of the gang against two rivals: turbo, passes, steals, shoves, blocks, dunks and «en llamas» after 3 baskets.
// Controls (Jonay, simple): HOLD the left mouse button (or E) to shoot and release it while the bar is in the green;
// right button (or Q) passes / steals (with turbo, a shove) and, defending away from the ball, switches to the other
// defender; defending, the shot button jumps to block; Espacio runs (turbo). Running + shooting from mid range =
// ENTRADA EN COMBO: the game stops and you have a few seconds to do one of the 4 specials of the 2D fight (same keys:
// directions + puño = left/E, patada = right/Espacio) for a different dunk. All keys in Opciones › Controles.
// v0.79 (Jonay): every combo is its own spectacular dunk, animated frame by frame (the ball goes with the hands):
// with puño the 360 and the windmill/tomahawk, with patada the back dunk (legs open, the ball down first) and the
