  const PUD = [];
  let pudGeo = null;
  const tmpM = new THREE.Matrix4(),
    tmpV = new THREE.Vector3(),
    aimV = new THREE.Vector3(),
    handV = new THREE.Vector3(),
    O3 = new THREE.Vector3(),
    NEG = new THREE.Vector3(),
    UP3 = new THREE.Vector3(0, 1, 0);
  let flameG = null,
    flameM = null,
    toyIcon = null;
