          B = at(i + 1, j),
          C = at(i - 1, j),
          D = at(i, j + 1);
        let e0 = P0,
          e1 = P0,
          e2 = P0,
          e3 = P0;
        if (C === A && C !== D && A !== B) e0 = A;
        if (A === B && A !== C && B !== D) e1 = B;
        if (D === C && D !== B && C !== A) e2 = C;
        if (B === D && B !== A && D !== C) e3 = D;
        o[2 * j * W2 + 2 * i] = e0;
        o[2 * j * W2 + 2 * i + 1] = e1;
        o[(2 * j + 1) * W2 + 2 * i] = e2;
        o[(2 * j + 1) * W2 + 2 * i + 1] = e3;
