    MUS.song = {
      ...song,
      ch: song.ch.map((c) => ({ ...c, t: Array.isArray(c.n) ? (c.form || c.n.map((_, i) => i)).map((i) => parse(c.n[i])).flat() : parse(c.n) }))
    };
