    for (let i = 0; i < 18; i++) t.push([450 + i * 300, 'p', 0.15 + ((i * 0.41) % 0.7), 5]);
    for (let i = 0; i < 10; i++) t.push([900 + i * 500, 'tf', 0, 1]);
    for (let i = 0; i < 8; i++) t.push([1100 + i * 600, 'h', i % 2 ? 0.3 : 0.7, 3]);
