      boom(e.x, e.y, e.r);
      api.sfx(e.r > 15 ? 'boom' : 'pop');
      if (e.gid !== undefined) {
        const gr = groups[e.gid];
        gr.killed++;
        if (gr.killed >= gr.n) {
          items.push({ k: 'c', x: e.x, y: e.y, t: 0 });
          addScore(500, e.x, e.y - 12);
        }
      }
      if (e.k === 'b') {
        items.push({ k: 'c', x: e.x - 10, y: e.y - 12, t: 0 }, { k: 'c', x: e.x + 10, y: e.y + 12, t: 1 });
        if (e.drop) items.push({ k: e.drop, x: e.x, y: e.y, t: 0 });
      }
