        if (e.st === 'in') {
          e.x -= 40 * dt;
          if (e.x < W - 70) e.st = 'stay';
        } else if (e.st === 'stay') {
          e.y = e.y0 + Math.sin(e.t * 0.8) * 50;
          if (e.t > 12) e.st = 'out';
        } else e.x -= 70 * dt;
