      let ty = H / 2,
        best = null,
        bd = 1e9;
      for (const e of foes)
        if (!e.dead && e.x > p.x + 20 && e.x < W) {
          const d = e.x - p.x;
          if (d < bd) {
            bd = d;
            best = e;
          }
        }
      if (boss && !boss.dying) {
        const wp = boss.parts.find((q) => q.weak);
        if (wp) ty = wp.y;
      } else if (best) ty = best.y;
