      if (g.fireT <= 0) {
        g.fireT = 0.13;
        k.hit.vS = true;
        k.held.vS = true;
      }
      if ((p.cur === 0 && p.spd < 2) || (p.cur === 1 && p.missile < 1) || (p.cur === 2 && !p.dbl && !p.laser) || (p.cur === 4 && p.opts < 2))
        k.hit.vP = true;
