        k,
        x,
        z,
        h: 0,
        vh: 0,
        vx: 0,
        face: -1,
        hp: d.hp * lp(),
        max: d.hp * lp(),
        st: 'walk',
        stT: 0,
        anim: Math.random() * 4,
