// LAS CARRERAS DEL CANARIÓN (coches)
const CAN = 'El Canarión';
function k3RaceStart(m, P, rivals, cps, top) {
  // rivals: [{model, color}] start beside you; countdown; cps along P
  const K = K3(),
    S = m.st;
  S.P = P;
  S.cps = cps;
  S.cp = 0;
  S.rv = [];
  rivals.forEach((r, i) => {
    const sp = s2Path(P.pts);
    sp.s = 0;
    const a = sp.at(0);
    const side = i % 2 ? -1 : 1;
    const c = s2Car(r.model, r.color, a[0] + Math.cos(a[2]) * 3.2 * side, a[1] - Math.sin(a[2]) * 3.2 * side, a[2]);
    c.mode = 'race';
    c.driver = 'race';
    s2Mark(c, 8);
    S.rv.push({ c, P: sp, top: r.top || top });
  });
  ['3', '2', '1'].forEach((t, i) =>
    setTimeout(() => {
      if (K.isActive(m)) {
        HUD.big(t, '#fff', 0.8);
        AUDIO.cash();
      }
    }, i * 1000)
  );
  setTimeout(() => {
    if (!K.isActive(m)) return;
    HUD.big('¡YA!', '#7fe08a', 1.2);
    S.go = true;
    k3RaceCp(m);
  }, 3000);
}
function k3RaceCp(m) {
  const K = K3(),
    S = m.st,
    c = S.cps[S.cp];
  const last = S.cp === S.cps.length - 1;
  K.goto(c[0], c[1], 9, last ? 0xf5b72e : 0x46c3ff);
  K.ahead(S.cps, S.cp, S.P.pts);
  K.setObjective((last ? b2('¡META!') : `Control ${S.cp + 1}/${S.cps.length - 1}`) + (S.rv.length ? ' · Gana al Canarión' : ' · ¡Contra el reloj!'));
}
function k3RaceUpdate(m, dt, win, lose) {
  const K = K3(),
    S = m.st;
  if (!S || !S.go || S.done) return;
  for (const r of S.rv) {
    const d = Math.hypot(PLAYER.x - r.c.x, PLAYER.z - r.c.z);
    const ahead = r.P.s > S.myS;
    if (s2DriveCar(r.c, r.P, dt, r.top, () => (ahead ? (d > 160 ? 0.82 : 0.97) : d > 160 ? 1.12 : 1.02))) {
      S.done = true;
      lose();
      return;
    }
  }
  if (!PLAYER.car) {
    K.setObjective('¡Vuelve a un coche!');
    return;
  }
  S.myS = S.cpS ? S.cpS[S.cp] : 0;
  if (s2AtGoal(10)) {
    AUDIO.cash();
    S.cp++;
    if (S.cp >= S.cps.length) {
      S.done = true;
      win();
      return;
    }
    k3RaceCp(m);
  }
}
function k3Cps(P, every) {
  const out = [],
    cpS = [];
  for (let s = every; s < P.tot - every * 0.4; s += every) {
    const q = P.at(s);
    out.push([q[0], q[1]]);
    cpS.push(s);
  }
  const e = P.at(P.tot);
  out.push([e[0], e[1]]);
  cpS.push(P.tot);
  return [out, cpS];
}
